// Файл згенеровано scripts/build_kz_akafisty.py. Абзац з префіксом § — рубрика, з префіксом # — підзаголовок.
import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст святому славному пророку, Предтечі і Хрестителю Господньому Іоанну","e":"Akathist to the Holy Glorious Prophet, Forerunner and Baptist of the Lord John","secs":[{"h":"Кондак 1","ps":["Ізбра́нний от літ дре́вніх би́ти Предте́чею і Крести́телем Спаси́теля ми́ра Христа́ Бо́га, Іоа́нне богохва́льне, прославля́юще просла́вльшаго тя Го́спода, похва́льная воспису́єм ті, я́ко бо́льшему всіх рожде́нних жена́ми, во пло́ті А́нгелу, покая́нія пропові́днику; ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́ких бід свобожда́й і к покая́нію воздвиза́й нас, любо́вію тебі́ зову́щих:","Ра́дуйся, вели́кий Іоа́нне, Проро́че, Предте́че і Крести́телю Госпо́день."]},{"h":"Ікос 1","ps":["Арха́нгел Гавриї́л, предстоя́й пред Бо́гом, по́слан бисть ко ієре́ю Заха́рії, єгда́ той, служа́ по чи́ну чреди́ своєя́, вни́де покади́ти в це́рков Госпо́дню; і, предста́в одесну́ю олтаря́ кади́льнаго, благовіствова́ше о твоє́м рождестві́, вели́кий Іоа́нне, возвіща́я Заха́рії ра́дость і весе́ліє, і я́ко мно́зі о рождестві́ твоє́м возра́дуються. Сего́ ра́ди і ми, ди́вному о тебі́ Бо́жию благоволе́нію чудя́щеся і ра́дующеся, со благогові́нієм в похвалу́ тебі́ вопіє́м:","Ра́дуйся, Сові́та Бо́жия неізрече́ннаго таї́нниче;","ра́дуйся, ди́внаго смотре́нія Єго́ ісполне́ніє.","Ра́дуйся, пре́жде літ мно́гих проро́чеством Іса́її проявле́нний;","ра́дуйся, ве́стниче пред лице́м Госпо́днім, дре́вле прорече́нний.","Ра́дуйся, предназна́ченний би́ти вели́ким проро́ком Ви́шняго;","ра́дуйся, по обітова́нію А́нгела рожде́нний.","Ра́дуйся, єще́ во чре́ві ма́тере твоєя́ Ду́ха Свята́го іспо́лненний;","ра́дуйся, пре́жде рождества́ твоєго́ на вели́коє служе́ніє освяще́нний.","Ра́дуйся, непло́дства роди́телей разріше́ніє;","ра́дуйся, ієре́я Бо́жия ра́дость і весе́ліє.","Ра́дуйся, дще́ре Ааро́нови прозябе́ніє;","ра́дуйся, плод моли́тви Богодарова́нний.","Ра́дуйся, вели́кий Іоа́нне, Проро́че, Предте́че і Крести́телю Госпо́день."]},{"h":"Кондак 2","ps":["Ви́дя Заха́рія я́вльшагося єму́ А́нгела, смути́ся, і страх нападе́ нань, і не ві́рова словесе́м благові́стія єго́ о рождестві́ твоє́м; єгда́ же за неві́ріє німото́ю свя́зан бисть, удивля́шеся пресла́вному чудеси́, всім се́рдцем вопія́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум неуразумева́ємий разумі́ти і́щуще лю́діє, жду́ще Заха́рію, і чудя́хуся, уме́длившу єму́ в це́ркві; ізше́дшу же єму́ і не могу́щу глаго́лати к ним, но то́кмо помава́ющу, разумі́ша всі, я́ко ви́дініє ви́ді в це́ркві. Ми же, прославля́юще ди́внаго Творця́ чуде́с, Бо́га, вопіє́м тебі́ такова́я:","Ра́дуйся, благи́й вино́вниче безгла́сія о́тча;","ра́дуйся, слез ма́тере твоєя́ преміне́ніє на ра́дость.","Ра́дуйся, тоя́ поноше́нія в лю́діх от'я́тіє;","ра́дуйся, вели́коє ро́ждшим тя утіше́ніє.","Ра́дуйся, я́ко в шести́й мі́сяць о зача́тії твоє́м Пресвята́я Ді́ва Марі́я в Назаре́ті от А́нгела ізвісти́ся;","ра́дуйся, я́ко о рождестві́ твоє́м мно́зі возвесели́шася.","Ра́дуйся, я́ко і́м'я благода́тноє, от А́нгела нарече́нноє, получи́вий;","ра́дуйся, я́ко і́менем твої́м німотствова́ніє отця́ твоєго́ Заха́рії разріши́ся.","Ра́дуйся, я́ко і́м'я Бо́жиє о тебі́ отце́м твої́м благослови́ся;","ра́дуйся, я́ко о чу́днім рождестві́ твоє́м страх і удивле́ніє в о́крест живу́щих яви́ся.","Ра́дуйся, я́ко по всей страні́ Іуде́йстій о ди́внім рождестві́ твоє́м возвісти́ся;","ра́дуйся, я́ко тобо́ю спасе́ніє мно́гим в ми́рі сем яви́ся.","Ра́дуйся, вели́кий Іоа́нне, Проро́че, Предте́че і Крести́телю Госпо́день."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго разріши́ непло́дство заматоре́вшия во днех свої́х пра́ведния Єлисаве́ти: зача́т бо тя, сла́вний Предте́че Госпо́день, і тая́шеся мі́сяць п'ять, глаго́лющи: я́ко та́ко мні сотвори́ Госпо́дь во дні, в ня́же призрі́ от'я́ти поноше́ніє моє́ в челові́ціх. Єгда́ же прия́ Іму́щую во чре́ві Христа́, іспо́лнися Ду́ха Свя́та і возопи́ гла́сом ве́ліїм: «Отку́ду мні сіє́, я́ко при́йде Ма́ти Го́спода моєго́ ко мні!» С Не́юже ра́дующися, взива́ше Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй предити́ пред Го́сподем ду́хом і си́лою Іліїно́ю, єще́ із чре́ва ма́тере твоєя́ іспо́лнился єси́ Ду́ха Свята́го, отону́дуже і Проро́к ди́вний показа́лся єси́, єгда́ во утро́бі ма́тере твоєя́ сий, взигра́лся єси́ ра́дощами прише́ствію Ма́тері Госпо́дней. Бо́га бо позна́л єси́ носи́ма в ложесна́х Благода́тния і Того́ ма́тернім гла́сом пропові́дал єси́: подоба́ше бо Боже́ственних веще́й пресла́вним би́ти нача́лом. Сему́ у́бо благогові́йно удивля́ющеся, с ра́достію тебі́ вопіє́м:","Ра́дуйся, єще́ во утро́бі ма́терней предпосла́вшаго тя Го́спода чу́дним весе́лієм пред'яви́вий;","ра́дуйся, я́ко тебе́ ра́ди і ма́тері твоє́й Єлисаве́ті воплоще́ніє Христо́во откри́ся.","Ра́дуйся, я́ко і та іспо́лнися Ду́ха Свя́та;","ра́дуйся, я́ко і она́ преди́вная проро́чиця яви́ся.","Ра́дуйся, я́ко от нея́ Пресвята́я Ді́ва Марі́я Блаже́нною в жена́х нарече́ся;","ра́дуйся, я́ко то́ю Она́ і Ма́терію Го́спода найменова́ся.","Ра́дуйся, я́ко і безсі́менний плод Тоя́ Благослове́нним пронарече́ся;","ра́дуйся, Прему́дросте Боже́ственния пред'явле́ніє.","Ра́дуйся, свята́го супру́жества благослове́ніє;","ра́дуйся, непло́дних ложе́сн ди́вноє прозябе́ніє.","Ра́дуйся, рожде́нієм твої́м удиви́вий лю́ди;","ра́дуйся, сві́тлий Сло́ва гла́се.","Ра́дуйся, вели́кий Іоа́нне, Проро́че, Предте́че і Крести́телю Госпо́день."]},{"h":"Кондак 4","ps":["Бу́рею сомні́нія смуще́нний, ієре́й Заха́рія не можа́ше, по словесі́ а́нгельському, проглаго́лати. Єгда́ же по рождестві́ твоє́м, Предте́че Госпо́день, написа́ благода́тноє і́м'я твоє́, а́біє отверзо́шася уста́ і язи́к єго́, і глаго́лаше, благослов'я́ Бо́га, і проро́чествова, глаго́ля: благослове́н Госпо́дь Бог Ізра́їлев, я́ко посіти́ і сотвори́ ізбавле́ніє лю́дем Свої́м, і ти, отроча́, Проро́к Ви́шняго нарече́шися, поя́ Тому́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша о́крест живу́щії лю́діє о пресла́внім і чу́днім рождестві́ твоє́м, со удивле́нієм глаго́лаху в себі́: «Что у́бо отроча́ сіє́ бу́деть?» Ми же тя, пресла́вний Предте́че Госпо́день, я́ко бо́льша всіх рожде́нних жена́ми, досто́йно чту́ще, ублажа́єм си́це:","Ра́дуйся, от зача́тія твоєго́ благода́тних явле́ній іспо́лненний;","ра́дуйся, в рождестві́ твоє́м Бо́гом просла́вленний.","Ра́дуйся, во младе́нчестві твоє́м от отця́ твоєго́ Проро́ком Ви́шняго нарече́нний; ра́дуйся, во о́трочестві твоє́м Ду́хом Святи́м просвіще́нний і укрепле́нний.","Ра́дуйся, Бо́га воплоти́вшагося сро́дник по пло́ті би́вий;","ра́дуйся, от Бо́га висо́коє зва́ніє Предте́чі і Крести́теля приє́мий.","Ра́дуйся, заре́, Світ но́вий ми́ру возвісти́вшая;","ра́дуйся, звіздо́, путь, веду́щий ко Христу́, освіти́вшая.","Ра́дуйся, денни́це Со́лнця незаходи́маго;","ра́дуйся, світи́льниче Сві́та неугаса́ємаго.","Ра́дуйся, путь гряду́щему Христу́ уготовля́яй;","ра́дуйся, А́нгела і челові́ка в себі́ явля́яй.","Ра́дуйся, вели́кий Іоа́нне, Проро́че, Предте́че і Крести́телю Госпо́день."]},{"h":"Кондак 5","ps":["Богопроти́вноє велі́ніє беззако́ннаго детоуби́йці І́рода ізгна́ тя із до́му о́тча в непрохо́дную пусти́ню, носи́ма ма́терію, Предте́че Госпо́день, іді́же і пребива́л єси́ до дне явле́нія твоєго́ ко Ізра́їлю, яди́й акри́ди і мед ди́вій і Бо́гу вопія́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще ди́вноє Бо́жиє о тебі́ промишле́ніє, Іоа́нне богохва́льне, я́ко от младе́нчеських пеле́н по́стничеськаго житія́ люби́тель показа́лся єси́, отону́дуже во́лею Ви́шняго по́слан бил єси́ пропові́дати лю́дем гряду́щеє во Христі́ спасе́ніє, сего́ ра́ди со удивле́нієм і любо́вію тебі́ взива́єм:","Ра́дуйся, я́ко, єще́ младе́нець сий, царя́ І́рода устраши́л єси́;","ра́дуйся, от напра́снаго убіє́нія тім десни́цею Ви́шняго сохране́нний.","Ра́дуйся, пусти́ні шипо́к благово́нний;","ра́дуйся, висото́ю подвиго́в твої́х всіх удиви́вий.","Ра́дуйся, пра́ваго путі́ ві́рний указа́телю;","ра́дуйся, чистоти́ і цілому́дрія преди́вний храни́телю.","Ра́дуйся, єва́нгельськаго самоотверже́нія о́бразе соверше́нний;","ра́дуйся, мона́шествующих покро́ве і утвержде́ніє.","Ра́дуйся, богосло́вствующих умо́в просвіще́ніє;","ра́дуйся, грі́шним милосе́рдія Бо́жия две́рі отверза́яй.","Ра́дуйся, ка́ющимся грі́шником от Го́спода проще́ніє подава́яй;","ра́дуйся, плоди́ досто́йни покая́нія твори́ти помога́яй.","Ра́дуйся, вели́кий Іоа́нне, Проро́че, Предте́че і Крести́телю Госпо́день."]},{"h":"Кондак 6","ps":["Пропові́дник сла́вний ти, боже́ственний Предте́че, показа́лся єси́ в пусти́ні Іорда́нстій во дні явле́нія Христа́ Бо́га ми́ру. Сего́ бо, Гряду́щаго к тебі́, показа́л єси́ лю́дем, глаго́ля: «Се, А́гнець Бо́жий, взе́мляй гріхи́ ми́ра!»; Єго́же ми ві́рою позна́вше, поє́м Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ світ і́стини, Іоа́нне богопросвеще́нне, всім явля́яй Сла́ви О́тчія сія́ніє, я́вльшеєся пло́тськи нас ра́ди. Вопія́л бо єси́ в пусти́ні лю́дем: «Пока́йтеся, прибли́жи бо ся Ца́рствіє Небе́сноє: сотворі́те плоди́ досто́йни покая́нія. Се бо гряде́ть по мні, І́же крести́ть ви водо́ю і Ду́хом». Сего́ ра́ди похва́льная тебі́ вопіє́м:","Ра́дуйся, прише́ствія Мессі́ї возвісти́телю;","ра́дуйся, путе́й Госпо́дніх угото́вателю.","Ра́дуйся, ве́тхия і но́вия благода́ті хода́таю;","ра́дуйся, проро́ков преді́ле і нача́ло Апо́столов.","Ра́дуйся, гла́се Сло́ва благознамени́тий;","ра́дуйся, покая́нія пропові́дниче велегла́сний.","Ра́дуйся, мно́гих сино́в Ізра́їлевих ко Го́споду обрати́вий;","ра́дуйся, лю́ди соверше́нни Го́сподеві угото́вавий.","Ра́дуйся, фарисе́єв і саддуке́єв дерзнове́нно обличи́вий;","ра́дуйся, плоди́ досто́йни покая́нія твори́ти научи́вий.","Ра́дуйся, просвіще́нія духо́внаго указа́телю;","ра́дуйся, і́щущим предста́тельства твоєго́ неуси́пний засту́пниче.","Ра́дуйся, вели́кий Іоа́нне, Проро́че, Предте́че і Крести́телю Госпо́день."]},{"h":"Кондак 7","ps":["Хотя́щу от тебе́ крести́тися Го́споду Ісу́су, Іоа́нне богоблаже́нне, глаго́лал єси́: «Аз тре́бую Тобо́ю крести́тися», оба́че повину́яся, ре́кшу Тому́: «Оста́ви ни́ні», воздви́гл єси́ десни́цю твою́ на главу́ Єго́ і, крести́в не тре́бующаго очище́нія, вопія́л єси́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую подая́ благода́ть крести́тися ізво́ливий от тебе́ Госпо́дь, сподо́би тя Ду́ха прише́ствіє ви́діти і глас О́тчеський с Небесе́, свиде́тельствующий Єго́ Синовство́, сли́шати. Отону́дуже в Тріє́х Ли́ціх Єди́ному Бо́гу покланя́тися нас научи́л єси́. Єго́же бре́нними прославля́юще устна́ми, в похвалу́ сія́ тебі́ прино́сим:","Ра́дуйся, Тро́їчеськаго Богоявле́нія пе́рвий пропові́дниче;","ра́дуйся, в Тріє́х Ли́ціх Єди́наго Бо́га і́стинний покло́нниче.","Ра́дуйся, Ду́ха Свята́го во ви́ді голуби́ні яснозри́телю;","ра́дуйся, снисхожде́нія Єго́ от Отця́ на Си́на свиді́телю.","Ра́дуйся, гла́са с Небесе́ от Бо́га Отця́ сли́шателю;","ра́дуйся, явле́нія любве́ О́тчі к Си́ну созерца́телю.","Ра́дуйся, Си́на Бо́жия ізбра́нний Крести́телю;","ра́дуйся, во́лі Єго́ святи́я ісполни́телю.","Ра́дуйся, сла́внаго служе́нія спасе́нію ро́да челові́чеськаго ре́вностний рачи́телю;","ра́дуйся, вели́каго Та́їнства Креще́нія пе́рвий соверши́телю.","Ра́дуйся, Боже́ственния ра́дости ве́стниче;","ра́дуйся, Но́ваго Заві́та пе́рвий учи́телю.","Ра́дуйся, вели́кий Іоа́нне, Проро́че, Предте́че і Крести́телю Госпо́день."]},{"h":"Кондак 8","ps":["Стра́нноє і неізрече́нноє смире́ніє воплоти́вшагося Бо́га Сло́ва ви́дів, богоблаже́нне Крести́телю, Боже́ственную Свою́ главу́ приклони́вша і ра́бськоє креще́ніє приє́мша, ти і сам весь іспо́лнился єси́ вели́каго смире́нія. Іспроси́ у́бо боголюбе́зную доброді́тель сію́ і нам, одержи́мим го́рдостію, я́ко да от сердця́ смире́нна вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь благода́тних дарова́ній іспо́лненний, тече́ніє вре́менния жи́зні скончава́я, Іоа́нне богознамені́те, всіх поуча́л єси́ ісполне́нієм Зако́на і покая́нієм благоугожда́ти Го́сподеві. Сего́ ра́ди благода́рственноє хвале́ніє тебі́, вели́кому учи́телю і́стини, воспіва́єм:","Ра́дуйся, Зако́на і оправда́ній Госпо́дніх насади́телю;","ра́дуйся, І́родова беззако́нія обличи́телю.","Ра́дуйся, о іспра́вленії того́ рачи́телю;","ра́дуйся, пра́вди ра́ди темни́чноє заключе́ніє і у́зи претерпі́вий.","Ра́дуйся, за і́стину во главу́ усі́ченний;","ра́дуйся, я́ко ті́ло твоє́ от ученико́в твої́х че́стне погребе́ся.","Ра́дуйся, я́ко Бо́жиїм смотре́нієм глава́ твоя́ нетлі́нна соблюде́ся;","ра́дуйся, я́ко та на утіше́ніє, освяще́ніє і цільби́ христия́ном даде́ся.","Ра́дуйся, я́ко і десни́це твоє́й, крести́вшей Го́спода, ві́рнії благоче́стне покланя́ються;","ра́дуйся, я́ко от тебе́ мно́гая чудеса́ ті́ми дони́ні соверша́ються.","Ра́дуйся, я́ко тобо́ю ві́рнії от страсте́й безче́стія ізбавля́ються;","ра́дуйся, я́ко тобо́ю грі́шнії к покая́нію воздвиза́ються.","Ра́дуйся, вели́кий Іоа́нне, Проро́че, Предте́че і Крести́телю Госпо́день."]},{"h":"Кондак 9","ps":["Все єстество́ а́нгельськоє удиви́ся висоті́ служе́нія твоєго́, і Це́рков благогові́йно прославля́єть тя, я́ко дру́га Христа́ Бо́га, предше́дшаго пред Ним ду́хом і си́лою Іліїно́ю. Ревну́я бо по і́стині, дерзнове́нно облича́л єси́ фарисе́єв і беззако́ннаго І́рода, от него́ же і му́ченичеськую кончи́ну прия́л єси́. Покланя́ющеся у́бо честні́й главі́ твоє́й, мо́лимся ті: ізба́ви нас от страсте́й безче́стія, да чи́стим се́рдцем і усти́ поє́м: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство вся́коє земноро́дних не довлі́єть досто́йно восхвали́ти тя, Іоа́нне богохва́льне: тебі́ бо уста́ Христо́ви похвали́ша, ви́сша проро́ков і бо́льша всіх рожде́нних жена́ми тя найменова́ша. Отону́дуже досто́йную похвалу́ принести́ тебі́ недоуміва́юще, вопіє́м ті сицева́я:","Ра́дуйся, Це́ркве Христо́ви вели́кая сла́во;","ра́дуйся, А́нгелов преди́вноє чу́до.","Ра́дуйся, пра́отцев ра́дость і прославле́ніє;","ра́дуйся, проро́ков висо́кая похвало́.","Ра́дуйся, Апо́столов богосві́тлий ві́нче;","ра́дуйся, святи́телей велеле́пая красото́.","Ра́дуйся, му́чеников в но́вой благода́ті нача́ло;","ра́дуйся, преподо́бних соверше́ніє.","Ра́дуйся, пра́ведних удобре́ніє;","ра́дуйся, ді́вственников і по́стников основа́ніє.","Ра́дуйся, всіх христия́н вели́коє утіше́ніє;","ра́дуйся, я́ко от всіх христия́нских родо́в і́м'я твоє́ прославля́ється.","Ра́дуйся, вели́кий Іоа́нне, Проро́че, Предте́че і Крести́телю Госпо́день."]},{"h":"Кондак 10","ps":["Спасти́ мир прише́дшаго во пло́ті Христа́ Бо́га благовісти́л єси́ і су́щим во а́ді: я́коже бо денни́ця, предходя́щая со́лнцю, освіти́л єси́ во тьмі і сі́ні сме́ртній сідя́щих. Отону́дуже вско́рі Го́сподем ізведе́н бил єси́ со всі́ми от ві́ка пра́ведними, поя́ Єму́, я́ко Ізба́вителю і Побіди́телю сме́рти: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і прибі́жище спаси́тельноє всім, моли́твенно к тебі́ притека́ющим, боже́ственний Іоа́нне: сего́ ра́ди пі́сньми похва́льними ублажа́єм тя си́це:","Ра́дуйся, мо́щний засту́пниче наш і ві́рний от бід храни́телю;","ра́дуйся, злостра́ждущих от духо́в зло́би ско́рий помо́щниче і ізба́вителю.","Ра́дуйся, непло́дствующим благослове́ніє от Бо́га низпосила́яй;","ра́дуйся, притека́ющих к тебі́ с ві́рою от треволне́нія страсте́й ізбавля́яй.","Ра́дуйся, во вражді́ су́щих ско́ро умиротворя́яй;","ра́дуйся, во вся́кой нужді́ і печа́лі усе́рдно притека́ющим к тебі́ ско́рую по́мощ подава́яй.","Ра́дуйся, благотеку́щих от самообольще́нія і пре́лести ізима́яй;","ра́дуйся, вруча́ющим себі́ твоєму́ хода́тайству в час сме́ртний помога́яй.","Ра́дуйся, лю́б'ящих тя от возду́шних мита́рств предста́тельством твої́м свобожда́яй;","ра́дуйся, почита́ющих сла́вную па́м'ять твою́ ві́чния жи́зні моли́твами твої́ми сподобля́яй.","Ра́дуйся, ни́щих і вдови́ць і сиро́т заступле́ніє;","ра́дуйся, по Бо́зі і Богоро́дице христия́ном прибі́жище і упова́ніє.","Ра́дуйся, вели́кий Іоа́нне, Проро́че, Предте́че і Крести́телю Госпо́день."]},{"h":"Кондак 11","ps":["Пі́ніє вся́коє не довлі́єть по достоя́нію до́блестей твої́х восхвали́ти тя, Крести́телю Госпо́день; но ми, любо́вію пону́ждені, дерза́єм воспіва́ти вели́чія твоя́, є́же ми́лостивно прийми́ от нас, первостоя́телю у Престо́ла Пресвяти́я Тро́йці, і моли́ свободи́тися нам от вся́кия скве́рни гріхо́вния, да чи́стим се́рдцем і устна́ми поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льника Сві́та непристу́пнаго і всесві́тлих благода́тних дарова́ній всего́ іспо́лнена тя, Іоа́нне богопросвеще́нне, ві́дуще, ра́достно прино́сим ті такова́я:","Ра́дуйся, самови́дче озари́вшаго тя сви́ше Боже́ственнаго Сві́та;","ра́дуйся, сві́том доброді́телей твої́х просла́вивий Бо́га.","Ра́дуйся, Пресвяти́я Тро́йці велеле́пую сла́ву яви́вий;","ра́дуйся, пра́вий і ди́вний путь к Небесі́ показа́вий.","Ра́дуйся, і су́щим во а́ді Бо́га, я́вльшагося во пло́ті, благовести́телю;","ра́дуйся, душ пра́ведних, от ві́ка в преіспо́дней держи́мих, возвесели́телю.","Ра́дуйся, Влади́ки Христа́ Бо́га дру́же і́скренній;","ра́дуйся, яви́вий ми́ру Світ і́стинний.","Ра́дуйся, світоза́рноє сві́та єва́нгельськаго сія́ніє;","ра́дуйся, ро́да христия́нськаго прославле́ніє.","Ра́дуйся, Сові́та Бо́жия ісполне́ніє;","ра́дуйся, я́ко от восто́к со́лнця да́же до за́пад хва́льно і́м'я твоє́.","Ра́дуйся, вели́кий Іоа́нне, Проро́че, Предте́че і Крести́телю Госпо́день."]},{"h":"Кондак 12","ps":["Благода́ті тезоимени́тий, Крести́телю Госпо́день, і то́ю обогати́вся, побідоно́сець пресла́вний показа́лся єси́: побіди́л бо єси́ враги́ і вся́кую зло́бу, і вели́коє служе́ніє твоє́ му́ченичеським по́двигом запечатлі́л єси́. Ни́ні же, предстоя́ Престо́лу Царя́ ца́рствующих, моли́ Єго́ дарова́ти ві́рним побі́ди на враги́ і во всем благопоспіше́ніє, в доброді́теліх же благода́тноє укріпле́ніє, пою́щим Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Бо́га, ди́вно в тебі́ просла́вльшагося, хва́лим тя, богоблаже́нне Крести́телю, я́ко і́скренняго дру́га Христо́ва, прославля́єм вели́кия по́двиги твоя́, ублажа́єм му́ченичеськую кончи́ну твою́ і сицева́я ра́достно вопіє́м ті:","Ра́дуйся, вселе́нський Апо́столе і Но́ваго Заві́та первому́чениче;","ра́дуйся, явле́нієм Христа́ на землі́ откри́вшагося Ца́рствія Небе́снаго пе́рвий пропові́дниче.","Ра́дуйся, язи́ков Боже́ственноє призва́ніє предвозвісти́вий;","ра́дуйся, безві́стная і та́йная прему́дрости Бо́жия ми́ру яви́вий.","Ра́дуйся, боже́ственними дія́нії плодоно́сен па́че іни́х яви́вийся;","ра́дуйся, я́ко сві́том діл твої́х просла́вися Оте́ць Небе́сний.","Ра́дуйся, я́ко в па́м'яті твоє́й Це́рков Христо́ву весели́ши неізрече́нно;","ра́дуйся, я́ко ни́ні ві́чнаго наслажда́єшися весе́лія ізоби́льно.","Ра́дуйся, боже́ственними луча́ми Трисо́лнечнаго Сві́та осіява́ємий;","ра́дуйся, я́ко со безпло́тними Трисвяту́ю піснь Бо́гу немо́лчно вопіє́ши.","Ра́дуйся, я́ко ни́ні, зерца́лом разре́шшимся, несре́дственне зри́ши Святу́ю Тро́йцю.","Ра́дуйся, вели́кий Іоа́нне, Проро́че, Предте́че і Крести́телю Госпо́день."]},{"h":"Кондак 13","ps":["О вели́кий і пресла́вний Предте́че і Крести́телю Госпо́день Іоа́нне, прийми́ от нас ни́ні приноси́моє тебі́ моле́ніє і твої́ми богоприя́тними к Бо́гу моли́твами ізба́ви нас от вся́каго зла, і ві́чния ізми́ му́ки, і наслі́дниками Ца́рствія Небе́снаго соді́лай, да во ві́ки поє́м Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгел Гавриї́л, предстоя́й пред Бо́гом, по́слан бисть ко ієре́ю Заха́рії, єгда́ той, служа́ по чи́ну чреди́ своєя́, вни́де покади́ти в це́рков Госпо́дню; і, предста́в одесну́ю олтаря́ кади́льнаго, благовіствова́ше о твоє́м рождестві́, вели́кий Іоа́нне, возвіща́я Заха́рії ра́дость і весе́ліє, і я́ко мно́зі о рождестві́ твоє́м возра́дуються. Сего́ ра́ди і ми, ди́вному о тебі́ Бо́жию благоволе́нію чудя́щеся і ра́дующеся, со благогові́нієм в похвалу́ тебі́ вопіє́м:","Ра́дуйся, Сові́та Бо́жия неізрече́ннаго таї́нниче;","ра́дуйся, ди́внаго смотре́нія Єго́ ісполне́ніє.","Ра́дуйся, пре́жде літ мно́гих проро́чеством Іса́її проявле́нний;","ра́дуйся, ве́стниче пред лице́м Госпо́днім, дре́вле прорече́нний.","Ра́дуйся, предназна́ченний би́ти вели́ким проро́ком Ви́шняго;","ра́дуйся, по обітова́нію А́нгела рожде́нний.","Ра́дуйся, єще́ во чре́ві ма́тере твоєя́ Ду́ха Свята́го іспо́лненний;","ра́дуйся, пре́жде рождества́ твоєго́ на вели́коє служе́ніє освяще́нний.","Ра́дуйся, непло́дства роди́телей разріше́ніє;","ра́дуйся, ієре́я Бо́жия ра́дость і весе́ліє.","Ра́дуйся, дще́ре Ааро́нови прозябе́ніє;","ра́дуйся, плод моли́тви Богодарова́нний.","Ра́дуйся, вели́кий Іоа́нне, Проро́че, Предте́че і Крести́телю Госпо́день."]},{"h":"Кондак 1","ps":["Ізбра́нний от літ дре́вніх би́ти Предте́чею і Крести́телем Спаси́теля ми́ра Христа́ Бо́га, Іоа́нне богохва́льне, прославля́юще просла́вльшаго тя Го́спода, похва́льная воспису́єм ті, я́ко бо́льшему всіх рожде́нних жена́ми, во пло́ті А́нгелу, покая́нія пропові́днику; ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́ких бід свобожда́й і к покая́нію воздвиза́й нас, любо́вію тебі́ зову́щих:","Ра́дуйся, вели́кий Іоа́нне, Проро́че, Предте́че і Крести́телю Госпо́день."]},{"h":"Молитва","ps":["Крести́телю Христо́в, пропові́дниче покая́нія, ка́ющагося не пре́зри мене́, но, совокупля́яся с во́ї Небе́сними, моли́ся ко Влади́ці за мене́, недосто́йнаго, уни́лаго, немощна́го і печа́льнаго, во мно́гія біди́ впа́дшаго, утружде́ннаго бу́рними по́мисли ума́ моєго́. Аз бо єсьм верте́п злих діл, отню́д не імі́яй конця́ гріхо́вному оби́чаю: пригвожде́н бо єсть ум мой земни́м веще́м. Что сотворю́, не вім, і ко кому́ прибі́гну, да спасе́на бу́деть душа́ моя́, то́кмо к тебі́, святи́й Іоа́нне, благода́ті тезоімені́те, я́ко тя пред Го́сподем, по Богоро́дице, вім бо́льша би́ти рожде́нних всіх: ти бо сподо́бился єси́ косну́тися верху́ Царя́ Христа́, взе́млющаго гріхи́ ми́ра, А́гнця Бо́жия. Єго́же моли́ за грі́шную мою́ ду́шу, да поне́ отни́ні, в первийна́десять час, понесу́ тяготу́ благу́ю і прийму́ мзду с послі́дніми. Єй, Крести́телю Христо́в, честни́й Предте́че, кра́йній проро́че, пе́рвий во благода́ті му́чениче, по́стников і пусти́нников наста́вниче, чистоти́ учи́телю і бли́жній дру́же Христо́в, тя молю́, к тебі́ прибіга́ю, не отри́ни мене́ от твоєго́ заступле́нія, но возста́ви м'я, па́дшагося мно́гими гріхи́: обнови́ ду́шу мою́ покая́нієм, я́ко втори́м креще́нієм, поне́же обоєго́ нача́льник єси́: креще́нієм омива́яй гріх, покая́ніє же пропові́дуяй во очище́ніє кого́ждо діл скве́рних: очи́сти у́бо м'я, гріхми́ оскверне́ннаго і пону́ди вни́ти, а́може нічто́же скве́рно вхо́дить в Ца́рствіє Небе́сноє. Амі́нь."]},{"h":"Тропар собору і усікновенню, глас 2","ps":["Па́м'ять пра́веднаго с похвала́ми, / тебі́ же довлі́єть свиді́тельство Госпо́днє, Предте́че: / пока́зал бо ся єси́ воі́стину і проро́ков честні́йший, / я́ко і в струя́х крести́ти сподо́бился єси́ Пропові́даннаго. / Ті́мже за і́стину пострада́в ра́дуяся, / благовісти́л єси́ і су́щим во а́ді Бо́га я́вльшагося пло́тію, / взе́млющаго гріх ми́ра, // і подаю́щаго нам ве́лію ми́лость."]},{"h":"Тропар зачаттю, глас 4","ps":["Пе́рвіє неражда́ющая непло́ди, возвесели́ся, / се бо зачала́ єси́ Со́лнця світи́льника я́ві, / просвіща́ти іму́ща всю вселе́нную, сліпото́ю неду́гующую. / Лику́й, Заха́ріє, вопія́ со дерзнове́нієм: // проро́к Ви́шняго єсть хотя́й роди́тися."]},{"h":"Тропар різдву, глас 4","ps":["Проро́че і Предте́че прише́ствія Христо́ва, / досто́йно восхвали́ти тя недоумі́єм ми, любо́вію чту́щії тя: / непло́дство бо ро́ждшия і о́тчеє безгла́сіє разріши́ся / сла́вним і честни́м твої́м рождество́м, // і воплоще́ніє Си́на Бо́жия ми́рові пропові́дується."]},{"h":"Тропар першому і другому знайденню глави, глас 4","ps":["От землі́ возсія́вши, Предте́чева глава́, / лучи́ іспуща́єть нетлі́нія, ві́рним ісціле́ній, / сви́ше собира́єть мно́жество А́нгел, / до́лі же созива́єть челові́чеський род, // єдиногла́сную возсила́ти сла́ву Христу́ Бо́гу."]},{"h":"Тропар третьому знайденню глави, глас 4","ps":["Я́ко Боже́ственноє сокро́вище сокрове́нноє в землі́, / Христо́с откри́ главу́ твою́ нам, проро́че і Предте́че. / Всі у́бо соше́дшеся в сея́ обрі́теніє, / пі́сньми богоглаго́ливими Спа́са воспої́м, // спаса́юща нас от тлі́нія моли́твами твої́ми."]},{"h":"Тропар на перенесення правиці, глас 4","ps":["От за́пада возсія́вши Предте́чева рука́, / лучи́ іспуща́єть нетлі́нія ві́рним ісціле́ній, / сви́ше собира́єть мно́жество А́нгел, / до́лі же созива́єть челові́чеський род, // єдиногла́сно возсила́ти сла́ву Христу́ Бо́гу."]},{"h":"Кондак собору, глас 6","ps":["Плотська́го Твоєго́ прише́ствія убоя́вся Іорда́н, / стра́хом возвраща́шеся, / проро́чеськоє же служе́ніє ісполня́я Іоа́нн, / тре́петом спря́ташеся, / А́нгельстії чи́ни ужаса́хуся, / зря́ще Тя во струя́х пло́тію креща́єма, / і всі су́щії во тьмі озаря́хуся, // воспева́ющеТя, я́вльшагося і просвіти́вшаго вся."]},{"h":"Кондак зачаттю, глас 1","ps":["Весели́ться сві́тло Заха́рія вели́кий / со всесла́вною Єлисаве́тію сопру́жницею, / досто́йно зачина́юще Іоа́нна Предте́чу, / єго́же Арха́нгел благовісти́, ра́дуяся, / і челові́ци достодо́лжно почти́м, // я́ко таї́нника благода́ті."]},{"h":"Кондак різдву, глас 3","ps":["Пре́жде непло́ди, днесь Христо́ва Предте́чу ражда́єть, / і той єсть ісполне́ніє вся́каго проро́чества: / Єго́же бо проро́ци пропові́даша, / на Сего́ во Іорда́ні ру́ку положи́в, // яви́ся Бо́жия Сло́ва проро́к, пропові́дник вку́пі і Предте́ча."]},{"h":"Кондак усікновенню, глас 5","ps":["Предте́чево сла́вноє усікнове́ніє, / смотре́ніє бисть ні́коє Боже́ственноє; / да і су́щим во а́ді Спа́сово пропові́сть прише́ствіє. / Да рида́єть у́бо Іроді́я, / беззако́нноє уби́йство іспроси́вши: / не зако́н бо Бо́жий, ні живи́й вік возлюби́, // но притво́рний, привре́менний."]},{"h":"Інший кондак усікновенню, глас 4","ps":["І́род, Предте́че, беззако́нновав, / жені́ подаде́ главу́ твою́ честну́ю, / є́йже покланя́ющеся, веселі́мся; // Іроді́я же пла́четь і рида́єть, / і І́род, і пляса́вшая."]},{"h":"Кондак першому і другому знайденню глави, глас 2","ps":["Про́роче Бо́жий і Предте́че благода́ті, / главу́ твою́ я́ко ши́пок свяще́ннійший от землі́ обрі́тше, / ісціле́нія всегда́ приє́млем, // і́бо па́ки, я́коже пре́жде в ми́рі пропові́дуєши покая́ніє."]},{"h":"Кондак третьому знайденню глави, глас 6","ps":["Світоявле́нний і Боже́ственний в ми́рі столп, / со́лнця світи́льник, / Предте́ча, главу́ світоно́сную і Боже́ственную свою́ показа́вий в конці́х, / освяща́єть той ві́рно покланя́ющихся і взива́ющих: // Христо́в прему́дрий Крести́телю, спаси́ всіх нас."]},{"h":"Кондак на перенесення правиці, глас 6","ps":["У́мнаго Со́лнця світи́льник Боже́ственний Предте́ча, / показа́вий в конці́х світоно́сную свою́ десни́цю, / ни́ні на сі́вері озаря́єть є́ю блаже́нноє Оте́чество на́ше, / просвіща́я і освяща́я ві́рно покланя́ющихся, і Христу́ вопію́щих: // спаси́ нас моли́твами проро́ка Твоєго́, Царю́ Ви́шній."]},{"h":"Величання різдву","ps":["Велича́єм тя, Предте́че Спа́сов Іоа́нне, і чтим є́же от непло́дове пресла́вноє рождество́ твоє́."]},{"h":"Величання усікновенню","ps":["Велича́єм тя, / Крести́телю Спа́сов Іоа́нне, / і почита́єм всі / честни́я твоєя́ глави́ // усікнове́ніє."]},{"h":"Величання знайденню","ps":["Велича́єм тя, / Крести́телю Спа́сов Іоа́нне, / і почита́єм всі / честни́я твоєя́ глави́ // обрі́теніє."]}],"notes":[]},{"u":"Акафіст первоверховним апостолам Петру і Павлу","e":"Akathist to the Foremost Apostles Peter and Paul","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії пропові́дници А́гнця Непоро́чнаго, за ни закла́ннаго, Христа́ Бо́га, пресла́внії Апо́столи Пе́тре і Па́вле! Я́ко Богові́дінієм конці́ ми́ра озари́вшії і оби́льні струя́ми благода́ті напоі́вшії, і ни́ні с любо́вію при́зріте на чту́щия усе́рдно па́м'ять ва́шу. Іспо́лніте нас ду́ха прему́дрости, сердця́ на́ша ві́рою утверді́те, да непреста́нно благода́рственная вам поє́м, со умиле́нієм зову́ще:","Ра́дуйтеся, святі́ї первоверхо́внії Апо́столи Пе́тре і Па́вле."]},{"h":"Ікос 1","ps":["А́нгели благові́стници яви́стеся на землі́, Апо́столи Пе́тре і Па́вле блаже́ннії, зане́ от Самаго́ Вино́вника спасе́нія на́шего на ді́ланіє ва́ше призва́ни би́вше, широту́ всея́ землі́ обтеко́сте, іуде́ом і е́ллином Христа́ расп'я́таго, Бо́жию Си́лу і Бо́жию Прему́дрость, пропові́дающе. Ті́мже і ми, сві́том уче́ній ва́ших озаря́ємі, се́рдцем і усти́ взива́єм к вам сицева́я:","Ра́дуйтеся, зві́зди світоза́рния, от восто́ка возсія́вшия і всім лю́дем путь ко Христу́ показа́вшия;","ра́дуйтеся, Це́ркве Христо́ви утвержде́ніє і столпи́ непоколеби́мії.","Ра́дуйтеся, власть в'яза́ти і ріши́ти гріхи́ на́ша от Христа́ приі́мшії;","ра́дуйтеся, во святи́х писа́ніїх ва́ших к ві́рі і упова́нію на Бо́га вся ни призива́ющії.","Ра́дуйтеся, в житії́ ва́шем о́брази обраще́нія согреша́ющим яви́вшії;","ра́дуйтеся, висоту́ любве́ і́стинния сло́вом і ді́лом нам показа́вшії.","Ра́дуйтеся, святі́ї первоверхо́внії Апо́столи Пе́тре і Па́вле."]},{"h":"Кондак 2","ps":["Ви́дя тя, апо́столе Пе́тре, на мо́ре Галиле́йстім вку́пі со Андре́ом, бра́том твої́м, вмета́юща мре́жі, Госпо́дь рече́ вам: «Гряди́та по Мні, і сотворю́ ви ловця́ челові́ком». І а́біє, оста́вльше мре́жі, по Нем ідо́сте. Ті́мже, красото́ Це́ркві вселе́нськия, сотвори́ і нас предста́тельством твої́м ско́ри би́ти на ді́ланіє за́повідей Бо́жиїх, ко́сни же ко гріху́, да, зло́бою младе́нствующе, дости́гнем всі в мі́ру во́зраста му́жа соверше́нна, пою́ще Бо́гові: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Боже́ственний освіти́ тя, Па́вле, ізбра́нний сосу́де Бо́жий, єгда́, ревну́я о оте́чеських преда́ніїх, ше́ствовал єси́ в Дама́ск гони́ти Це́рков Христо́ву. Тогда́ бо внеза́пу сія́ніє Сла́ви Госпо́дні облиста́ тебі́ і глас бисть с Небесе́: «Са́вле, Са́вле, что М'я го́ниши?» Ти же, а́ще зрі́нієм плотськи́м омрачи́лся єси́, но ду́хом узрі́л єси́ Си́лу і Сла́ву Христа́ расп'я́та, тьму просвіща́юща і любо́вію Це́рков Свою́ созида́юща, і того́ ра́ди плени́лся єси́ ду́хом, покая́ніє і послуша́ніє нося́ і глаго́ля: «Го́споди, что сотворю́?» Посе́м, восприї́м жре́бій апо́стольства от руки́ Госпо́дні і креще́ніє водо́ю і Ду́хом от Ана́нії блаже́ннійшаго, яви́лся єси́ преди́вно сосу́д ізбра́нний благода́ті і свиді́тель немо́лчний Спаси́теля на́шего, от Него́же і ми, просвіща́ємії, пі́ти тебі́ навико́хом сицева́я:","Ра́дуйся, сві́тлосте церко́вная, от Сві́та Неізрече́ннаго на путі́ пречу́дно во открове́ніє язи́ков возжже́нная;","ра́дуйся, зна́менія Си́ли Бо́жия в житії́ твоє́м чу́дно яви́вий і тім уста́ непокори́вим наві́ки загради́вий.","Ра́дуйся, сосу́де ізбра́нний, ме́ньша от Апо́стол і пе́рваго от грі́шник себі́ сокруше́нно нареки́й;","ра́дуйся, я́коже Херуви́м тайнозри́тель, да́же до тре́тіяго Небесе́ ві́рою і любо́вію вознесе́нний.","Ра́дуйся, я́коже Серафи́м пла́менний, ре́вностію по Бо́зі непреста́нно снеда́ємий і істаєва́ємий;","ра́дуйтеся, Па́вле і Пе́тре, благові́стія труби́ громогла́сния, основа́нія ве́тхаго ми́ра, я́коже Ієрихо́н втори́й сокруши́вшия.","Ра́дуйтеся, святі́ї первоверхо́внії Апо́столи Пе́тре і Па́вле."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго, в не́мощіх познава́ємая, ізлія́ на тя, Па́вле, адама́нте ві́ри, благода́ть на благода́ть, зане́ нело́жно іспове́довал єси́: «Вся могу́ о укріпля́ющем м'я Ісу́се». І воі́стину пропові́дал єси́ Єва́нгеліє во явле́нії Ду́ха і си́ли, творя́ вели́кая і неізрече́нная, сла́вная же і ужа́сная, я́ко не ві́дущії Бо́га Богові́дінію науча́хуся, сердца́ ожесточе́нная єле́ом милосе́рдія напая́хуся і вся о́вці расточе́нния во огра́ду Па́стиря Єди́наго отвсю́ду стека́хуся, Єму́же і пі́ти согла́сно научи́шася: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я дерзнове́нную любо́в ко Го́споду, ше́ствовал єси́, Пе́тре, по вода́м воздвиза́ємим, я́ко по су́ху. Но а́ще і потопле́нієм бил єси́ устраша́єм і сомне́нієм обурева́єм, не потопи́лся єси́ в пучи́ні, поне́же просте́рл єси́ ру́ці і о́чі ко Спа́су, вопія́ Єму́ із глубини́ серде́чния: «Го́споди, спаси́ м'я». І в той час ру́ку по́мощі восприя́л єси́ от Христа́, Ізба́вителя на́шего. Та́ко і ми в сей юдо́лі земні́й, біда́ми устраша́ємі і волна́ми страсте́й потопля́ємі, взира́юще на тече́ніє твоє́, к ти́хому приста́нищу до́брі нас наставля́ющеє, благода́рственно воспіва́єм ті си́це:","Ра́дуйся, ка́меню ві́ри многоці́нний, от Ка́мене Краєуго́льна ізбра́нний і утвержде́нний;","ра́дуйся, хра́мі Ду́ха Свята́го, многоразли́чними дарова́ньми от Того́ преізря́дно украше́нний.","Ра́дуйся, ри́барю препро́стий, прему́дрости Бо́жия іспо́лненний, є́йже от челові́к нікто́же проти́витися мо́жеть;","ра́дуйся, самови́дче вели́чія Бо́жия, па́че царе́й і сла́вних землі́ от Го́спода на вся ві́ки просла́вленний.","Ра́дуйся, ха́ртіє одухотворе́нная, в ню́же о́гненними письмени́ сло́во Бо́жиє вписа́ся;","ра́дуйся, с Па́влом апо́столом світи́ло равноче́стноє і незаходи́моє.","Ра́дуйтеся, святі́ї первоверхо́внії Апо́столи Пе́тре і Па́вле."]},{"h":"Кондак 4","ps":["Бу́рю лю́тих іскуше́ній воздви́же дре́вле человікоуби́йця, іскони́ іски́й Це́рков Бо́жию потреби́ти і ученики́ Спа́сови, я́коже пшени́цю, разсі́яти: но Госпо́дь моли́ся о тебі́, Пе́тре, да не оскуді́єть ві́ра твоя́. І та́ко, от Спа́са просвіща́єм і от Него́ в не́мощі укріпля́єм, воі́стину сокруши́л єси́ че́люсти вра́жия і обра́щся утверди́л єси́ бра́тію твою́, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще, Па́вле прему́дре, о ди́внім ізбра́нії твоє́м, во є́же возвісти́ти і́м'я Го́спода Ісу́са наро́дом і царе́м і сино́м Ізра́їлевим, і ви́дяще тя в сло́ві, в житії́, в любві́, в ду́сі, во ві́рі, в чистоті́, я́коже сві́та язи́ком во спасе́ніє їх поста́влена, неві́рнії ві́рою просвіща́хуся, ві́рнії же, ликовству́юще, Го́спода прославля́ху. Ті́мже і ми, сора́доватися за́повідь приє́мше, прино́сим ті гла́сом ра́дованія такова́я:","Ра́дуйся, ві́рний служи́телю Христо́в, вся сла́вная ми́ра я́коже сор і прах вміни́вий і всім себі́ поработи́вий Христа́ ра́ди і Єва́нгелія;","ра́дуйся, до́брий во́їне Христо́в, во вся ору́жія Бо́жия облече́нний і вся язи́ки в послуша́ніє Христо́во покори́вий.","Ра́дуйся, же́ртво прия́тнейшая, Христу́ сораспе́ншаяся, Христа́ ра́ди по вся дні умира́ти приоби́кшая;","ра́дуйся, сі́ятелю слеза́ми мно́гими, у́зниче і іспові́дниче пресла́вний, я́зви Го́спода Ісу́са Христа́ на ті́лі твоє́м ра́достно носи́вий.","Ра́дуйся, сла́во і похвало́ Це́ркве Вселе́нськия, позо́рище ми́рові би́вий, глад, жа́жду, наготу́, біє́ніє і поруга́ніє за Христа́ многоча́стні претерпі́вий;","ра́дуйтеся, Па́вле і Пе́тре, Апо́столов украше́ніє, ми́ру благові́стници, Це́ркве утвержде́ніє.","Ра́дуйтеся, святі́ї первоверхо́внії Апо́столи Пе́тре і Па́вле."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́лся єси́, Па́вле, єгда́ тече́ніє твоє́, пресві́тло наче́н от Дама́ська, да́же до Ри́ма просте́рл єси́ і, я́коже пре́жде звізда́ от восто́к научи́ волхви́ кла́нятися Со́лнцю Пра́вди, си́це і ти, Богому́дре, путь ко Христу́ показа́л єси́ всім, хотя́щим дости́гнути спасе́нія, взива́я со дерзнове́нієм мно́гим: «Подража́телі мні бива́йте, я́коже і аз Христу́». Єму́же і пі́ти научи́л єси́ нас єди́німи усти́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів на горі́ Фаво́рстій Сла́ву Єдиноро́днаго от Отця́, оді́яна Сві́том, я́ко ри́зою, хотя́ща же за ни облещи́ся в ри́зу поруга́нія, глаго́лал єси́, Пе́тре, Ісу́сові, прови́дя сла́ву несказа́нную іскупле́нних Кро́вію А́гнця Непоро́чна Христа́: «Го́споди, добро́ єсть нам зді би́ти». Сего́ ра́ди і ми, ро́ди да́льнії, лише́ни чистоти́ світоза́рния, а́ще і недосто́йни су́ще, оба́че твої́м а́нгельським гла́сом призва́ннії к наслі́дію нетлі́нну, чи́сту, неув'яда́єму, соблюда́єму на Небесі́х, я́коже о́бщници хотя́щей откри́тися Сла́ві, воспіва́єм ті си́це:","Ра́дуйся, блаже́нне, от Присносу́щния І́стини досто́йно «блаже́н» нарече́нний;","ра́дуйся, би́сере предо́брий, от Го́спода при є́зері обрете́нний і сві́том от Сві́та осія́нний.","Ра́дуйся, от Самаго́ Іскупи́теля ро́да челові́ча на про́повідь Єва́нгелія по́сланний;","ра́дуйся, воі́стину лове́ць челові́ков яви́вийся, ти бо, я́коже і пре́жде, благода́тію влече́ши ду́ші омраче́нния в чу́дний Світ Христа́ Бо́га.","Ра́дуйся, істо́чниче животво́рний, от Істо́чника жи́зні ві́чния істеки́й і от бога́тства даро́в Ду́ха Свята́го жа́ждущия ду́ші напоя́яй;","ра́дуйтеся, Пе́тре і Па́вле, я́коже Серафи́ми шестокрила́тії, у Престо́ла Царя́ Сла́ви паря́щії і ко сві́ту Тайн Бо́жиїх приниця́ющії.","Ра́дуйтеся, святі́ї первоверхо́внії Апо́столи Пе́тре і Па́вле."]},{"h":"Кондак 6","ps":["Пропові́дник немо́лчен і по сме́рті твоє́й, Пе́тре Богоно́сне, яви́лся єси́, зане́ с не́ба ми́сленнаго, я́коже гром та́їнственний, о зва́нії христия́нстім многоразли́чне напомина́єши. Ми же, ві́дяще любо́в твою́ ніколи́же отпа́дающу і моли́тву о нас непреста́нно у Престо́ла Бо́жия де́єму, поє́м се́рдцем умиле́нним: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, Па́вле великоімени́те, зна́меньми і чудеси́ вско́рі, отне́ліже Дух Святи́й во Антіохі́ї повелі́ ті нача́ти превели́коє служе́ніє Апо́стола язи́ков: та́же, дости́г Кі́пра, Єли́ми волхва́ зрі́ніє омрачи́л єси́ і Се́ргия проко́нсула сві́том і́стини озари́л єси́. Сподо́би і нас, сві́та сего́ прича́щшихся, просла́вити ди́вная ді́ла твоя́ в пі́сніх і пі́ніїх духо́вних і воспіва́ти тебі́ такова́я:","Ра́дуйся, сві́те серде́ць кро́тких і разу́мних, я́же, я́ко доі́лиця, грі́єши і пе́стунствуєши писа́ньми твої́ми Богодухнове́нними;","ра́дуйся, же́зле наказа́нія, сосу́ди лжі і льсти до конця́ сокруша́яй, сердця́ же сокруше́нная на недви́жимім ка́мені ві́ри воздвиза́яй.","Ра́дуйся, Христо́во Єва́нгеліє в себі́ воплоти́вий і сего́ ра́ди преви́ше ви́димих вознесе́нний і просла́вленний;","ра́дуйся, уста́ медото́чная, ра́дость мно́гую Апо́столом і ві́рним возвісти́вшая, я́ко отве́рзе тобо́ю Госпо́дь двер спасе́нія всім язи́ком.","Ра́дуйся, ревни́телю по Бо́зі, но́вий Іліє́, не на чужде́м основа́нії созида́яй і ре́вностію твоє́ю стра́ни да́льнія обтека́яй;","ра́дуйтеся, Па́вле і Пе́тре, весь мир между́ ва́ми раздели́вшії, во є́же о́вому у́бо би́ти Апо́столу язи́ков, друго́му же пропові́дати наро́ду ізбра́нному.","Ра́дуйтеся, святі́ї первоверхо́внії Апо́столи Пе́тре і Па́вле."]},{"h":"Кондак 7","ps":["Хотя́ і́стину утверди́ти і мир Це́ркві огради́ти, прише́л єси́, Па́вле, побо́рниче пра́вди, во святи́й град, в не́мже на собра́нії святи́х Апо́стол і ві́рних свиді́тельствовал єси́ вку́пі с Петро́м і Варна́вою, я́ко Дух Святи́й ди́шить, іді́же хо́щеть, да́руя благода́ть Свою́ незави́стно іуде́ом і е́ллином і ві́рою вся спаса́я, а не ме́ртвенними ді́ли ве́тхаго зако́на. І та́ко воі́стину всі ві́рнії, свобо́ду і мир получи́вше, сою́зом любве́ связу́ємі, благода́рственно воспіва́ють Бо́гові: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго арха́нгела, провозві́стника та́йни, от ві́ка сокрове́нния, ізбра́ тя, Апо́столе Пе́тре, Госпо́дь, єгда́ вопроси́ ученики́ Своя́: «Ви же кого́ М'я глаго́лете би́ти?» Ти же, от Отця́ Небе́снаго просвіща́єм, возвісти́л єси́ несомні́нноє основа́ніє на́шея ві́ри, глаго́ля ко Спа́су: «Ти єси́ Христо́с, Син Бо́га Жива́го». Того́ ра́ди і ми, чту́ще тя, я́ко наде́жду на́шего спасе́нія неприкрове́нно іспові́давша, взива́єм ті такова́я:","Ра́дуйся, Сина́ю но́вий, скрижа́ль спасе́нія лю́дем я́сно показа́вий і свобо́ду во Христі́ возвісти́вий;","ра́дуйся, первоположе́нний от Архите́ктона Небе́снаго ка́меню ві́ри і іспові́данія, на не́мже Це́рков Христо́ва необори́мо основа́ся.","Ра́дуйся, первопоста́вленний врата́рю вхо́да ра́йськаго, єму́же пе́рвіє обіща́ся Госпо́дь да́ти ключи́ Ца́рствія Небе́снаго;","ра́дуйся, судіє́ пра́ведний, іми́й суди́ти с про́чими Апо́столи обімана́десяте колі́нома Ізра́їлевома.","Ра́дуйся, я́ко о́че́са́ і ушеса́ твоя́ блаже́нная Христа́ Спа́са на́шего, Єго́же лицезре́ти проро́ци пла́менні жела́ху, во пло́ті су́ща на землі́ ви́діша і сли́шаша;","ра́дуйтеся, Пе́тре і Па́вле, іму́щії но́ги благовіствова́нія красні́йшия і сердця́ освяще́нная, ви бо Єва́нгелію послужи́сте і єва́нгельськи пожи́сте.","Ра́дуйтеся, святі́ї первоверхо́внії Апо́столи Пе́тре і Па́вле."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до і неудо́б разуміва́ємоє яви́лся єси́, Пе́тре, му́дрствующим земна́я, я́ко незна́тна ми́ра і уничиже́на ізбра́ тя Госпо́дь, і посрами́л єси́ му́дрия, одолі́л єси́ ца́рства, приве́л єси́ со́нми омраче́нних ко Сві́ту І́стини, і дони́ні, я́коже столп о́гненний, озаря́єши вся земноро́дния, указу́я несомні́нний путь во блаже́нноє Оте́чество. Сего́ ра́ди, бога́тству благода́ті в тебі́ див'я́щеся, поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім бил єси́ вся, Па́вле, любо́вію всіх об'є́мля, сло́вом спасе́нія да́льних і бли́жніх достиза́я, ві́рою вся превозмога́я: зане́ і во Фили́ппіх, мир благовіству́я, а́ще і па́лицями біє́н бил єси́ лю́ті і в темни́цю во око́вах вве́ржен, но воспі́л єси́ та́мо вку́пі с Си́лою піснь чу́дную хвали́ і благодаре́нія Бо́гу, І́же і возгремі́ рабо́м Свої́м тру́сом ве́ліїм, я́ко і основа́нія темни́чная поколеба́шася і две́рі отверзо́шася. Ми же, ви́дяще тя, прему́дре, тьму узи́лища сві́том Богові́дінія озаря́юща і свобо́ду о Христі́ у́зником подаю́ща, воспіва́єм ті сицева́я:","Ра́дуйся, у́зниче Христо́в, темни́цю во храм претвори́вий і у́зами твої́ми де́монов це́пи лю́дем разріши́вий;","ра́дуйся, си́льне, не́мощі немощни́х понеси́й, не себі́, но бли́жнім угожда́ти іски́й.","Ра́дуйся, пречу́дне, у́зами і скорбми́ хвали́вийся, ра́доватися с ра́дующимися і пла́кати с пла́чущими научи́вий;","ра́дуйся, уме́рий гріху́, но при́сно живи́й Бо́гові, тебі́ бо жизнь Христо́с і смерть приобрі́теніє.","Ра́дуйся, о́бразе неуси́пнаго ді́ланія, за́дняя забива́яй, в пре́дняя простира́яйся і всім помишле́нієм к по́чести ви́шняго зва́нія теки́й;","ра́дуйтеся, Па́вле і Пе́тре, да́же до сме́рти му́ченичеськи Го́споду послужи́вшії і се́ю, я́ко вінце́м, по́двиг ваш венча́вшії.","Ра́дуйтеся, святі́ї первоверхо́внії Апо́столи Пе́тре і Па́вле."]},{"h":"Кондак 9","ps":["Вся ко Христу́ приводя́, возвісти́л єси́, Па́вле, во Афи́ніх мня́щимся му́дрим би́ти Прему́дрость, сви́ше сходя́щую, да, ві́дяще су́єтная, отсе́лі уві́дять Бо́га, неви́димаго їм, і ося́жуть Єго́, о Нем бо живе́м і дви́жемся і єсьми́. Ті́мже і ми, благода́тію неізрече́нною ра́зум і́стини восприє́мше і се́рдцем нело́жно, я́ко благ Госпо́дь, пости́гше, поє́м Єму́ ві́рою тве́рдою, я́коже пе́рстом от Фоми́, осязу́єму: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йствовати не можа́ше язи́к челові́ч, єгда́ Госпо́дь Сил но́зі рабо́м Свої́м умива́ше і ле́нтієм отира́ше. Ти же, Пе́тре, стра́хом побіжда́єм, а́ще возгласи́л єси́: «Не уми́єши ногу́ моє́ю вове́ки», но а́біє весь в послуша́ніє преложи́лся єси́, єгда́ усли́шал єси́ глаго́л, рече́нний от Го́спода: «А́ще не уми́ю тебі́, не і́маши ча́сти со Мно́ю». І та́ко всім се́рдцем возопи́л єси́: «Го́споди, не но́зі мої́ то́кмо, но і ру́ці, і главу́». Ми же, ві́дяще тя в сих, я́коже зла́то во огні́ іскуше́нія, очища́єма і познава́юще от смире́нія к послуша́нію восхожде́ніє твоє́, та́їнству Бо́жия промишле́нія покланя́ющеся, воспіва́єм ті се́рдцем смире́нним такова́я:","Ра́дуйся, Пе́тре, очеса́ о́рля, і́миже зрел єси́ Со́лнце Пра́вди — Христа́ Бо́га, Іу́ді но́зі уми́вшаго і от него́ лобза́нієм лука́вим преда́ннаго;","ра́дуйся, наві́ки уневе́стивийся Христу́, ти бо, А́гнцю Непоро́чну, я́коже а́гнець, послі́дуя, до закла́нія твоєго́ ві́рность соблю́л єси́.","Ра́дуйся, у́глю неугаси́мий, от же́ртвенника Небе́снаго огне́м любве́ Боже́ственния непреста́нно об'я́тий;","ра́дуйся, світи́льниче горя́й і світя́й, ро́ди родо́в сві́том пра́вди озаря́яй.","Ра́дуйся, гро́зде многооби́льний виногра́да Христо́ва, на ра́дость ми́ра многопеча́льнаго возраще́нний;","ра́дуйтеся, Пе́тре і Па́вле, Христа́ Бо́га в себі́ ві́рно вообрази́вшії.","Ра́дуйтеся, святі́ї первоверхо́внії Апо́столи Пе́тре і Па́вле."]},{"h":"Кондак 10","ps":["Спасе́нія во Христі́ неізслі́димую пучи́ну і покая́нія мно́гую си́лу яви́л єси́ в себі́, Пе́тре, єгда́ трикра́ти по предрече́нному отве́рглся єси́ Го́спода: «Не вім Челові́ка Сего́!» Єгда́ кля́лся і роти́лся єси́ во дворі́ архієре́я, но а́біє, воспом'яну́в глаго́л Ісу́сов, вні текл єси́, пла́кася го́рко. Ми же, уми́льні взира́юще на пресві́тлий сей о́браз сокруше́нія, в науче́ніє і обличе́ніє жестокови́йних серде́ць на́ших дарова́нний, поє́м Го́споду, па́ки ди́вно возвели́чившему тя: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і ору́жіє непобіди́моє бил єси́, Па́вле, проти́ву миродержи́телей тьми ві́ка сего́, я́ко і ца́рство їх в Кори́нфі, Єфе́сі і іні́х гра́діх вселе́нния сокруши́л єси́, тьму многобо́жія разгоня́я і ра́зум і́стини утвержда́я. Ти бо нело́жно показа́лся єси́ Бо́жий слуга́ в терпі́нії мно́зі, в ско́рбіх, біда́х, в тіснота́х, в ра́нах, темни́цях, в нестроє́ніїх, труді́х, во бді́ніїх, в поще́ніїх, я́ко і ум наш недоумі́єть ізрещи́ бога́тство добро́ти твоєя́, денноно́щния по́двиги со слеза́ми мно́гими. Того́ ра́ди, зря́ще мо́ре любве́ твоєя́, дерза́юще мо́лим: усли́ши нас, убо́гих, грі́шними усти́ глаго́лющих сицева́я:","Ра́дуйся, уме́рий гріху́ благові́стниче непобіди́мий, я́ко в себі́ пе́рвіє ве́тхаго челові́ка побіди́в, Христу́ сорасп'я́лся єси́;","ра́дуйся, учи́телю многопло́дний і волко́в хи́щних обличи́телю, я́ко тобо́ю о́браз ві́рним показа́л єси́, при́сно бо́дрствуя і науча́я вся сугу́бо: сло́вом і житіє́м по сло́ву.","Ра́дуйся, всіх обогати́телю, я́ко, пре́жде сам обнища́в і нічто́же іми́й, вся содержа́л єси́;","ра́дуйся, о христия́ніх пла́менний ревни́телю, обручи́вий я Христу́, я́ко ді́ву чи́сту, непоро́чную неві́сту.","Ра́дуйся, утро́бо многоболе́зненная би́вий о ча́діх твої́х в му́ках рожде́нія, до́ндеже вообрази́ться в них Христо́с;","ра́дуйтеся, Па́вле і Пе́тре, в Ду́сі єди́нице согла́сная во єди́ном гра́де ві́рность Христу́ кро́вію запечатле́вшії.","Ра́дуйтеся, святі́ї первоверхо́внії Апо́столи Пе́тре і Па́вле."]},{"h":"Кондак 11","ps":["Пі́ти і ублажа́ти у́зи і страда́нія твоя́, Па́вле многострада́льне, досто́йно єсть, я́ко не то́кмо в терпі́нії мно́зі, но і с ра́достію предрече́нния ті от Ага́ва проро́ка у́зи восприя́л єси́, і Це́ркві Кесари́йстей свиді́тельствовал єси́ си́це: «Не то́чію свя́зан би́ти хощу́, но і умре́ти гото́в єсьм за і́м'я Го́спода Ісу́са». Єму́же і ми, ди́вному во святи́х Свої́х, поє́м піснь: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́том ра́дости неізре́ченния і Боже́ственния любве́ осія́н бил єси́, Пе́тре, єгда́ Госпо́дь по воскресе́нії пе́рвіє про́чих апо́стол яви́ся тебі́, скорбе́вшему. По сих же па́ки я́влься, Влади́ка жи́зні вопроси́ тя трикра́ти: «Си́моне Іо́нин, лю́биши ли М'я?» Ти же, огне́м Боже́ственния любве́ опаля́єм, отвіща́л єси́ те́плі: «Го́споди, Ти ві́си, я́ко люблю́ Тя». Того́ ра́ди і ми, обнища́вшії ду́хом, пом'яну́вше преізоби́льния то́ки слез і любве́ твоєя́, ї́хже ра́ди воззва́ тя Госпо́дь на пре́жній сте́пень апо́стольства, благогові́йні взива́єм ті сицева́я:","Ра́дуйся, учи́телю покая́нія, слеза́ми го́ркими висоту́ смире́нія стяжа́вий і Воскре́сшим от гро́ба к ра́дости неізглаго́ланній на ві́ки приобще́нний;","ра́дуйся, прему́дрости глубино́, смиренному́дрія висото́, пла́меню любве́, о́браз житія́ всім ві́рним себе́ яви́вий.","Ра́дуйся, дру́же Го́спода Ісу́са, і́го благові́стія ре́вностно понеси́й, над наслі́дієм Бо́жиїм госпо́дствовати не восхоті́вий, но послуша́нію власте́м научи́вий;","ра́дуйся, Апо́столе Христо́в, му́дрость змії́ну і чистоту́ голуби́ну в себі́ сочета́вий і о́бразом сме́рті твоєя́ на кресті́ кра́йнєє смиренному́дріє показа́вий.","Ра́дуйся, ра́бе Го́спода ві́рний, умно́живий да́нний тебі́ тала́нт і в ра́дость Го́спода вше́дий;","ра́дуйтеся, Пе́тре і Па́вле, сердца́ не ті́сная, весь мир любо́вію вмісти́вшая і конці́ вселе́нния просвіти́вшая.","Ра́дуйтеся, святі́ї первоверхо́внії Апо́столи Пе́тре і Па́вле."]},{"h":"Кондак 12","ps":["Благода́ть Ду́ха Уті́шителя, ізлія́вшаяся на глави́ ві́рних во о́бразі язи́ков о́гненних, ско́ро ізлія́ся із уст твої́х, Пе́тре, глаго́лом о́гненним, во є́же благовісти́ти с си́лою мно́гою Христа́ расп'я́та не то́чію поги́бшим овця́м до́му Ізра́їлева, но і язи́честій неплодя́щей це́ркві, да плодоно́сить і сія́ Бо́гові нетлі́нний крин чистоти́ і покая́нія. Іспроси́ і нам, Апо́столе достоблаже́нне, ми́лость Го́спода, творя́щаго тобо́ю вели́кая і чу́дная, руко́ю твоє́ю ме́ртвия воскреша́юща і сме́ртію твоє́ю на кресті́ ме́ртвенную любо́в на́шу воспламеня́юща, да непреста́нно поє́м Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще пресві́тлую па́м'ять твою́, Па́вле, досто́йно ублажа́єм неізре́ченния по́двиги, болі́зні і труди́, я́же во бді́ніїх, во алчбі́ і жа́жді, в поще́ніїх, в зимі́ і наготі́ поне́сл єси́. Кто бо ізочте́ть ра́ни, ско́рби і біди́ твоя́ во гра́діх, в пусти́ні, в мо́рі, біди́ от разбо́йник, біди́ от сро́дник, біди́ от язи́к і лжебра́тії? Кто подо́бен тебі́? Па́че всіх Апо́стол потруди́лся єси́. Ті́мже мо́лим: не возгнуша́йся нас, грі́шних, моля́щихся тебі́, но я́коже всім бил єси́ вся, і ни́ні усли́ши немощни́м гла́сом приноси́мая ті сицева́я:","Ра́дуйся, у́зниче Христо́в, із темни́ці світ распространи́вий, сло́вом і посла́нієм во у́зах мно́го потруди́вийся, зане́ воі́стину сло́во Бо́жиє не в'я́жеться;","ра́дуйся, неізслі́димая пучи́но любве́, по бра́тії твоє́й отлуче́н би́ти от Христа́ преі́скренні восхоті́вий.","Ра́дуйся, подви́жниче преди́вний, по́двигом до́брим подвиза́вийся, тече́ніє соверши́вий і кро́вію твоє́ю Це́рков украси́вий;","ра́дуйся, істоча́яй мо́ре чуде́с, я́ко главотя́жи і убру́сці твої́ неду́ги ісціля́ху і де́мони прогоня́ху.","Ра́дуйся, любве́ Бо́жия неразлу́чний прича́стниче, го́рняя му́дрствуяй, а не земна́я, зане́ і от пло́ті разріши́тися і со Христо́м би́ти возжела́л єси́;","ра́дуйтеся, Па́вле і Пе́тре, ві́ри христия́нськия насади́теліє, благоче́стія вода́ми напоі́теліє і ко приста́нищу ві́чному ві́рнії води́теліє.","Ра́дуйтеся, святі́ї первоверхо́внії Апо́столи Пе́тре і Па́вле."]},{"h":"Кондак 13","ps":["О всехва́льнії благові́стници Пе́тре і Па́вле! Внемлі́те воздиха́нієм серде́ць на́ших, моля́щієся за ни, мно́го бо мо́жеть моли́тва пра́ведних пред Бо́гом: потщі́теся і ни́ні воспомина́ти нам о небе́снім зва́нії і христия́нстій кончи́ні жи́зні на́шея, привлеци́те нас ко сла́дости єва́нгельськия і́стини, свяжі́те у́зами любве́ Христо́ви, да ми всі, отве́ргшеся нече́стія і мирськи́х по́хотей, вни́дем в ра́дость Го́спода на́шего, пою́ще Єму́ со А́нгели і с ли́ки святи́х: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели благові́стници яви́стеся на землі́, Апо́столи Пе́тре і Па́вле блаже́ннії, зане́ от Самаго́ Вино́вника спасе́нія на́шего на ді́ланіє ва́ше призва́ни би́вше, широту́ всея́ землі́ обтеко́сте, іуде́ом і е́ллином Христа́ расп'я́таго, Бо́жию Си́лу і Бо́жию Прему́дрость, пропові́дающе. Ті́мже і ми, сві́том уче́ній ва́ших озаря́ємі, се́рдцем і усти́ взива́єм к вам сицева́я:","Ра́дуйтеся, зві́зди світоза́рния, от восто́ка возсія́вшия і всім лю́дем путь ко Христу́ показа́вшия;","ра́дуйтеся, Це́ркве Христо́ви утвержде́ніє і столпи́ непоколеби́мії.","Ра́дуйтеся, власть в'яза́ти і ріши́ти гріхи́ на́ша от Христа́ приі́мшії;","ра́дуйтеся, во святи́х писа́ніїх ва́ших к ві́рі і упова́нію на Бо́га вся ни призива́ющії.","Ра́дуйтеся, в житії́ ва́шем о́брази обраще́нія согреша́ющим яви́вшії;","ра́дуйтеся, висоту́ любве́ і́стинния сло́вом і ді́лом нам показа́вшії.","Ра́дуйтеся, святі́ї первоверхо́внії Апо́столи Пе́тре і Па́вле."]},{"h":"Кондак 1","ps":["Ізбра́ннії пропові́дници А́гнця Непоро́чнаго, за ни закла́ннаго, Христа́ Бо́га, пресла́внії Апо́столи Пе́тре і Па́вле! Я́ко Богові́дінієм конці́ ми́ра озари́вшії і оби́льні струя́ми благода́ті напоі́вшії, і ни́ні с любо́вію при́зріте на чту́щия усе́рдно па́м'ять ва́шу. Іспо́лніте нас ду́ха прему́дрости, сердця́ на́ша ві́рою утверді́те, да непреста́нно благода́рственная вам поє́м, со умиле́нієм зову́ще:","Ра́дуйтеся, святі́ї первоверхо́внії Апо́столи Пе́тре і Па́вле."]},{"h":"Молитва","ps":["О пресла́внії апо́столи Пе́тре і Па́вле, ду́ші за Христа́ преда́вшії і кро́вію ва́шею па́жить Єго́ удобри́вшії! Усли́шіте чад ва́ших моли́тви і воздиха́нія, се́рдцем сокруше́нним ни́ні приноси́мия. Се бо беззако́ньми омрачи́хомся і того́ ра́ди біда́ми, я́коже ту́чами, обложи́хомся, єле́я же до́браго житія́ обнища́хом зіло́ і не возмо́жем проти́витися волко́м хи́щним, і́же расхища́ти наслі́діє Бо́жиє де́рзостно тща́ться. О си́льнії! Понесі́те не́мощі на́ша, не отлуча́йтеся ду́хом от нас, да не разлучи́мся вконе́ць от любве́ Бо́жия, но крі́пким заступле́нієм ва́шим нас защиті́те, да поми́луєть Госпо́дь всіх нас моли́тв ва́ших ра́ди, да істреби́ть же рукописа́ніє безмі́рних гріхо́в на́ших і да сподо́бит со всі́ми святи́ми блаже́ннаго Ца́рствія і бра́ка А́гнця Своєго́, Єму́же честь, і сла́ва, і благодаре́ніє, і поклоне́ніє во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Апо́столов первопресто́льници, / і вселе́нния учи́теліє, / Влади́ку всіх молі́те / мир вселе́нній дарова́ти // і душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 2","ps":["Тве́рдия і боговіща́нния пропові́дателі, / верх апо́столов Твої́х, Го́споди, / прия́л єси́ в наслажде́ніє благи́х Твої́х і поко́й: / болі́зні бо о́ніх і смерть прия́л єси́ па́че вся́каго всепло́дія, // Єди́не, сві́дий серде́чная."]},{"h":"Величання","ps":["Велича́єм вас, / апо́столи Христо́ви Пе́тре і Па́вле, / весь мир уче́ньми свої́ми просвети́вшия // і вся конці́ ко Христу́ приве́дшия."]}],"notes":[]},{"u":"Акафіст святому великомученику Георгію Побідоносцю","e":"Akathist to the Holy Great Martyr George the Victorious","secs":[{"h":"Кондак 1","ps":["Взбра́нному воєво́ді і Побідоно́сцю Гео́ргію соста́вим похвалу́, я́ко хода́таю на́шему і ско́рому помо́щнику: ти же, святи́й великому́чениче, я́ко імі́яй дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, да зове́м ті:","Ра́дуйся, Гео́ргіє, вели́кий Побідоно́сче."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і всея́ тва́рі Соді́тель, яви́вий тя Це́ркві Своє́й ві́ри побо́рника і за ві́ру непобіди́маго страстоте́рпця, внуша́єть нам за по́двиги страда́ній твої́х восхваля́ти тя, свя́те Гео́ргіє, си́це:","Ра́дуйся, до конця́ Ісу́са Си́на Бо́жия возлюби́вий;","ра́дуйся, за і́м'я Єго́ с любо́вію ду́шу свою́ положи́вий.","Ра́дуйся, іспові́дниче, от Бо́га призва́нний;","ра́дуйся, подви́жниче, Бо́жиєю благода́тію просла́вленний.","Ра́дуйся, А́нгелов сожи́телю;","ра́дуйся, проро́ков равностоя́телю.","Ра́дуйся, Гео́ргіє, вели́кий Побідоно́сче."]},{"h":"Кондак 2","ps":["Ви́дя гоне́ніє нечести́вих на христия́ни, не убоя́лся єси́ ко́зні їх і мучи́тельства, богому́дре, но я́ко до́брий во́їн Христо́в, вся своя́ ни́щим разда́в, во́лею поте́кл єси́ на сові́т їх непра́ведний, Христу́ вождю́ і Бо́гу своєму́ поя́: Аллилу́я."]},{"h":"Ікос 2","ps":["Разу́мно уразумі́в Єди́наго Бо́га, в Тріє́х Іпоста́сіх боголі́пно покланя́ємаго, тве́рдим умо́м іспові́дал єси́ Єго́ на собо́рищі нечести́вих і та́ко обличи́л єси́ безу́мнаго царя́ безу́мноє поклоне́ніє тва́рі. Сего́ ра́ди за твоє́ висо́коє любому́дріє прийми́ от нас, Гео́ргіє, усе́рдния похвали́:","Ра́дуйся, Єди́наго і́стиннаго Бо́га пропові́дниче;","ра́дуйся, Пресвяти́я Тро́йці ві́рний защи́тниче.","Ра́дуйся, ве́лію правосла́внаго іспові́данія та́йну неві́рним показа́вий;","ра́дуйся, і́дольськаго служе́нія пре́лесть обличи́вий.","Ра́дуйся, ри́торе Бо́жий;","ра́дуйся, виті́є, прему́дрости іспо́лненний.","Ра́дуйся, Гео́ргіє, вели́кий Побідоно́сче."]},{"h":"Кондак 3","ps":["Си́ла Бо́жия, просвіща́ющая вся́каго челові́ка, гряду́щаго в мир, і в темни́ці тя стра́ждущаго посіти́ла єсть, смиренному́дре Гео́ргіє: поне́же ти вся житія́ сего́ тлі́нная, я́ко уме́ти презрі́в, єди́ному Христу́ приліпи́лся єси́, да за і́м'я Єго́ до́брі во́їнствовав, сподо́бишися Тому́ со А́нгели ві́чно воспіва́ти: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я ум і се́рдце, Ду́хом Святи́м озаре́нния, ти по внуше́нію Єго́ поревнова́л єси́ подвиза́тися за і́м'я Христо́во, до кро́ве стоя́ бо му́жественно во ві́рі, обличи́л єси́ вознесе́нную нечести́ваго собо́рища горди́ню. Сего́ ра́ди хва́лим тя, всему́дре Гео́ргіє, си́це:","Ра́дуйся, щі́те, воздви́гнутий на охране́ніє благоче́стія;","ра́дуйся, мечу́, под'я́тий на посіче́ніє нече́стія.","Ра́дуйся, сто́лпе ві́ри;","ра́дуйся, стіно́ і утвержде́ніє Христо́ви Це́ркві.","Ра́дуйся, ві́рних удобре́ніє;","ра́дуйся, неві́рних страх і посрамле́ніє.","Ра́дуйся, Гео́ргіє, вели́кий Побідоно́сче."]},{"h":"Кондак 4","ps":["Безу́мний мучи́тель, ди́шащий на тя уби́йством, страстоте́рпче Гео́ргіє, жа́ждал бо кро́ве твоєя́, я́ко пес а́лчний, повеліва́я расп'я́ти на колесе́ ті́ло твоє́ і злі́йшим му́кам преда́ти; ти же, возмога́я о Го́споді, с тве́рдим упова́нієм к Бо́гу взива́л єси́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше от тебе́ Діоклетія́н і жреци́ і́дольстії словеса́ прему́дрости, распиха́хуся на тя зло́бою, па́че же єгда́ рекл єси́: «О царю́ мучи́телю! Почто́ м'я всу́є істязу́єши? Мні бо є́же жи́ти, Христо́с, і є́же умре́ти, приобрі́теніє. Тру́дно ті єсть проти́ву рожна́ пра́ти». Сего́ ра́ди ми взива́єм ті, великоімени́те Гео́ргіє, си́це:","Ра́дуйся, за му́жественноє іспові́даніє ві́ри на колесе́ кров свою́ пролія́вий;","ра́дуйся, кро́вію своє́ю торжество́ ві́ри возвели́чивий.","Ра́дуйся, Апо́столов соревни́телю;","ра́дуйся, во́льним Христо́вим Страсте́м подража́телю.","Ра́дуйся, побо́рниче ві́ри непоколеби́мий;","ра́дуйся, страстоте́рпче, адама́нта тверді́йший.","Ра́дуйся, Гео́ргіє, вели́кий Побідоно́сче."]},{"h":"Кондак 5","ps":["Боготе́чной звізді́ подо́бен бил єси́ Гео́ргіє, чуде́сним бо от А́нгела ісціле́нієм і ви́димим от колеса́ отреше́нієм научи́л єси́ неві́рних ві́ровати в Тро́йцю Єдиносу́щную і Той ку́пно с тобо́ю воспіва́ти: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша наро́ди чудеса́ си́ли Бо́жия, я́ві на тебі́ бива́ємия, с кро́тостію уче́ніє Христо́во от тебе́ прия́ша і возопи́ша, глаго́люще: «Воі́стину вели́к Бог христия́нський!» Сего́ ра́ди і ми, восхваля́я тя, достосла́вне Гео́ргіє, взива́єм си́це:","Ра́дуйся, світоно́сним спасе́нія сло́вом тьму неві́рія разгна́вий;","ра́дуйся, му́ченичеським ві́ри іспові́данієм неві́рния ко Христу́ обрати́вий.","Ра́дуйся, легіо́ни во́їнов земни́х в небе́сноє во́їнство предводя́й;","ра́дуйся, я́ко во́їн Христо́в с небе́сними во́ї пребива́яй.","Ра́дуйся, ратобо́рцев сла́во;","ра́дуйся, пресві́тлаго му́ченичеськаго ли́ка красото́.","Ра́дуйся, Гео́ргіє, вели́кий Побідоно́сче."]},{"h":"Кондак 6","ps":["Пропові́дником і́стини, духоно́сним Апо́столом поревнова́в, кресто́м ми́ру расп'я́лся єси́, страстоте́рпче; се бо, я́ко Іо́на во чре́во кито́во, в пещ нерастворе́нния і́звести стремгла́во вве́ржен бил єси́, да просла́виться тебе́ ра́ди ди́вний во святи́х Госпо́дь, Єму́же ти і в ро́ві ізве́стнем, я́ко во хра́мі сла́ви, у́мно взива́л єси́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вий в тридне́вном Своє́м от гро́ба воста́нії всеси́льний а́да і сме́рті Побіди́тель Ісу́с спасе́ тя от а́дова істлі́нія, страстоте́рпче Гео́ргіє: по тріє́х бо днех обріто́ша тя в і́звести жи́ва і во воздея́нії рук пою́ща Бо́га; сего́ ра́ди вельми́ пристра́шни би́ша і ужасо́шася. Ми же, ра́дующеся, воспису́єм ті побі́дную піснь:","Ра́дуйся, позо́рним в ізві́стний ров низверже́нієм, вознесе́нную дия́вола горди́ню низложи́вий;","ра́дуйся, ди́вним от Бо́га спасе́нієм зві́рство мучи́телей побіди́вий.","Ра́дуйся, я́ко незло́бив сий, за твори́вших ті напа́сть моли́лся єси́, я́ко за благотво́рцев;","ра́дуйся, я́ко о обраще́нії їх, я́ко же Па́вел о євре́єх, болі́зновал єси́.","Ра́дуйся, му́жу жела́ній;","ра́дуйся, сосу́де ізбра́нний.","Ра́дуйся, Гео́ргіє, вели́кий Побідоно́сче."]},{"h":"Кондак 7","ps":["Хотя́й вся́чеськи улови́ти се́рдце твоє́ к пре́лести і́дол, нечести́вий мучи́тель умишля́єть прельсти́ти тя волше́бними чарова́нії; ти же, богоізбра́нне, с Дави́дом восклиця́я: «О Бо́зі спасе́ніє моє́ і сла́ва моя́», ві́рно Тому́ піл єси́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє показа́ зло лука́вий о́ний сатани́ служи́тель Діоклетія́н, єгда́ в безу́мной своє́й ко і́долом ре́вности повелі́ напоі́ти тя, Гео́ргіє, я́дом; ти же іспо́лнен сий ві́ри і упова́нія, а́ще і сме́ртноє іспи́л, оба́че без вре́да преби́л єси́, богохва́льне, ті́мже і ми вопіє́м ті:","Ра́дуйся, я́ко во упова́нії на Бо́га Жи́ва не посрами́лся єси́;","ра́дуйся, я́ко мучи́теля нівочто́же вміни́л єси́.","Ра́дуйся, бісо́в отгна́телю;","ра́дуйся, волше́бния ко́зні разруши́телю.","Ра́дуйся, я́ко тобо́ю ди́вен Бог во святи́х Свої́х явля́ється;","ра́дуйся, я́ко тобо́ю благоче́стно і́м'я Христо́во прославля́ється.","Ра́дуйся, Гео́ргіє, вели́кий Побідоно́сче."]},{"h":"Кондак 8","ps":["Стра́нний і стра́шний сові́т бисть от ні́коєго волхва́ нечести́вому царю́, да повели́ть ті, в доказа́тельство пра́вости ві́ри Христо́вой, сло́вом воскреси́ти ме́ртваго; ти же, Гео́ргіє, нічто́же сумня́ся, воспіва́л єси́ Тому́, І́же ність Бог ме́ртвих, но Бог живи́х: Аллилу́я."]},{"h":"Ікос 8","ps":["Всежела́нний і Сладча́йший Ісу́с, Єго́же ти все́ю душе́ю і всім се́рдцем возлюби́л єси́, всеблаже́нне Гео́ргіє, сли́ша те́плоє ві́ри твоєя́ моле́ніє, вско́рі повелі́ по сло́ву твоєму́ воскре́снути ме́ртвому, прославле́нія ра́ди І́мені Своєго́ і ві́рних утвержде́нія, неві́рним же і ослепле́нним на удивле́ніє і богопозна́ніє. Сего́ ра́ди по до́лгу вопіє́м ті:","Ра́дуйся, я́ко Госпо́дь сил ди́вная на тебі́ яви́л єсть;","ра́дуйся, я́ко ме́ртваго тобо́ю от гро́ба воскреси́л єсть.","Ра́дуйся, ослепле́нному волхву́ у́мноє прозрі́ніє ві́ри дарова́вий;","ра́дуйся, мно́гим, Христа́ ра́ди пострада́вшим, во свята́я святи́х путь показа́вий.","Ра́дуйся, Ри́ма удивле́ніє;","ра́дуйся, христия́нськаго ро́да возвише́ніє.","Ра́дуйся, Гео́ргіє, вели́кий Побідоно́сче."]},{"h":"Кондак 9","ps":["Всі А́нгели восхвали́ша Бо́га, дарова́вшаго ті таково́є му́жество, Гео́ргіє, я́ко і в темни́чном заточе́нії не престава́л єси́ моли́твенно бо́дрствовати. Сего́ ра́ди, я́ко вели́кий таї́нник Бо́жия благода́ті, удосто́їлся єси́ ви́діти во виді́нії Го́спода, вінце́м нетлі́нія главу́ твою́ венча́юща, да і ми с тобо́ю вопіє́м: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії ри́торськими свої́ми язи́ки не возмо́гуть ізрещи́ тебі́ досто́йния хвали́, Гео́ргіє, мно́гих ра́ди твої́х по́двигов і болі́зней, ї́хже за Христа́ і Це́рков под'я́л єси́ во́лею. Сего́ ра́ди і ми, недоумі́я восхваля́ти тя по достоя́нію, воспіва́єм си́це:","Ра́дуйся, во́льним за Христа́ і Це́рков страда́нієм ве́тхаго в себі́ Ада́ма расп'я́вий;","ра́дуйся, за до́блестноє страда́ніє віне́ць пра́вди от руки́ Госпо́дні прия́вий.","Ра́дуйся, пра́вило ре́вности благочести́вия;","ра́дуйся, о́бразе нищети́ духо́вния.","Ра́дуйся, я́ко не себі́, но Єди́ному Бо́гу до́брі угоди́л єси́;","ра́дуйся, я́ко за Христа́ на многообра́зния сме́рті гото́в бил єси́.","Ра́дуйся, Гео́ргіє, вели́кий Побідоно́сче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́ші во тьмі ідолослуже́нія погиба́ющих, боголю́бче Гео́ргіє, ти, ревну́я, поревнова́л єси́, я́ко Ілия́ по Бо́зі: вшед бо во храм і́дольський, си́лою Бо́жиєю разгна́л єси́ бі́си, сокруши́л і́доли, посрами́л жреци́ і, я́ко побіди́тель, не с челові́ки, но со А́нгели піл єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіни́ бесчу́вственнєє окамене́нний се́рдцем мучи́тель твой, Гео́ргіє, не уразумі́ Бо́га, я́ві тобо́ю чудоде́йствующа, но до конця́ преби́л єси́, я́ко а́спід, затика́яй у́ші свої́. Сего́ ра́ди повелі́ усіщи́ тя на позо́рищі во главу́, я́ко злоді́я; ти же, болі́знуя о поги́белі душі́ єго́, ра́достно прия́л єси́ кончи́ну, за ню́же ми тя ублажа́єм любо́вію си́це:","Ра́дуйся, ві́ру, наде́жду і люби́ до конця́ сохрани́вий;","ра́дуйся, во успе́нії твоє́м мно́гія і вели́кия чудеса́ сотвори́вий.","Ра́дуйся, ору́жієм благоволе́нія Бо́жия вінча́нний на землі́;","ра́дуйся, сла́вою і велеле́пієм украше́нний на Небесі́.","Ра́дуйся, челові́че Бо́жий;","ра́дуйся, до́брий во́їне Христо́в.","Ра́дуйся, Гео́ргіє, вели́кий Побідоно́сче."]},{"h":"Кондак 11","ps":["Пі́ніє Пресвяті́й Тро́йце па́че іни́х возда́л єси́, святи́й великому́чениче Гео́ргіє, не сло́вом то́чію і умо́м, но живи́м всего́ себ'я́ в же́ртву принесе́нієм: подража́я бо расп'я́тому за ни непоро́чному А́гнцю Христу́, положи́л єси́ ду́шу свою́ за дру́ги своя́ во́лею. Ті́мже у́бо а́ще недово́льни єсьми́ к похвале́нію такови́я твоєя́ до́блести, бо́льше бо сея́ любве́ нікто́же і́мать, оба́че благода́рні су́ще, поє́м Ди́вному во святи́х: Аллилу́я."]},{"h":"Ікос 11","ps":["Светоприє́мний світи́льник і́стиннаго Сві́та су́щим на землі́ явля́єшися, богоізбра́нне Гео́ргіє, просвіща́єши бо сердца́ ві́рних і к ра́зуму Боже́ственному вся наставля́єши, поуча́я і нас ве́село взива́ти:","Ра́дуйся, я́ко в пресві́тлих а́нгельських черто́зіх вселя́єшися;","ра́дуйся, я́ко не в гада́нії, но лице́м к лицю́, Невече́рняго Тро́їчнаго Сві́та причаща́єшися.","Ра́дуйся, ни́щих пита́телю і оби́димих защи́тниче;","ра́дуйся, немощни́х врачу́ і царе́й побо́рниче.","Ра́дуйся, правосла́вним во́їном во бра́ніх спобо́рниче;","ра́дуйся, о спасе́нії грі́шников те́плий хода́таю.","Ра́дуйся, Гео́ргіє, вели́кий Побідоно́сче."]},{"h":"Кондак 12","ps":["Благода́ть, да́нную ті от Бо́га, ві́дуще, па́м'ять твою́ пра́зднуєм, великому́чениче Гео́ргіє, і с усе́рдним моле́нієм к чудотво́рному о́бразу твоєму́ притека́юще, твоє́ю всеси́льною о Го́споді по́мощію, я́ко необори́мою стіно́ю, огражда́ємся. Сего́ ра́ди восхваля́я тя, усе́рдно зове́м Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Сла́вную кончи́ну твою́ пою́ще, є́юже возвели́чился єси́, я́ко до́брий во́їн Христо́в, мо́лим тя, страстоте́рпче Гео́ргіє: бу́ди нам во всем ко бла́гу помо́щниче і усли́ши ни, усе́рдно взива́ющих ті:","Ра́дуйся, я́ко тобо́ю Це́рков ві́рних просвіща́ється;","ра́дуйся, я́ко і́м'я твоє́ і между́ неві́рними прославля́ється.","Ра́дуйся, ди́вная іспові́дников сла́во;","ра́дуйся, висо́кая му́чеников похвало́.","Ра́дуйся, тіле́с на́ших ціле́бниче;","ра́дуйся, о душа́х на́ших моли́твенниче.","Ра́дуйся, Гео́ргіє, вели́кий Побідоно́сче."]},{"h":"Кондак 13","ps":["О всеблаже́нний і святи́й великому́чениче Гео́ргіє, прийми́ сіє́ на́ше хвале́бноє пі́ніє і ізба́ви нас от вся́каго зла твої́м те́плим к Бо́гу хода́тайством, да с тобо́ю воспіва́єм: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і всея́ тва́рі Соді́тель, яви́вий тя Це́ркві Своє́й ві́ри побо́рника і за ві́ру непобіди́маго страстоте́рпця, внуша́єть нам за по́двиги страда́ній твої́х восхваля́ти тя, свя́те Гео́ргіє, си́це:","Ра́дуйся, до конця́ Ісу́са Си́на Бо́жия возлюби́вий;","ра́дуйся, за і́м'я Єго́ с любо́вію ду́шу свою́ положи́вий.","Ра́дуйся, іспові́дниче, от Бо́га призва́нний;","ра́дуйся, подви́жниче, Бо́жиєю благода́тію просла́вленний.","Ра́дуйся, А́нгелов сожи́телю;","ра́дуйся, проро́ков равностоя́телю.","Ра́дуйся, Гео́ргіє, вели́кий Побідоно́сче."]},{"h":"Кондак 1","ps":["Взбра́нному воєво́ді і Побідоно́сцю Гео́ргію соста́вим похвалу́, я́ко хода́таю на́шему і ско́рому помо́щнику: ти же, святи́й великому́чениче, я́ко імі́яй дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, да зове́м ті:","Ра́дуйся, Гео́ргіє, вели́кий Побідоно́сче."]},{"h":"Молитва перша","ps":["Святи́й, сла́вний і всехва́льний великому́чениче Гео́ргіє! Собра́ннії в хра́мі твоє́м і пред іко́ною твоє́ю свято́ю покланя́ющіїся лю́діє, мо́лим тя, ізві́стний жела́нія на́шего хода́таю, моли́ с на́ми і о нас умоля́ємаго от Своєго́ благоутро́бія Бо́га, да ми́лостивно усли́шить нас, прося́щих Єго́ благости́ню, і не оста́вить вся на́ша ко спасе́нію і житію́ ну́ждная проше́нія, і да́руєть страні́ на́шей побі́ду на сопроти́вния; і па́ки, припа́дающе, мо́лим тя, святи́й Побідоно́сче: укріпи́ да́нною тебі́ благода́тію во бра́ніх правосла́вноє во́їнство, разруши́ си́ли востаю́щих враго́в, да постидя́ться і посра́м'яться, і де́рзость їх да сокруши́ться, і да уві́дять, я́ко ми імі́єм Боже́ственную по́мощ, і всім, в ско́рбі і обстоя́нії су́щим, многомо́щноє яви́ своє́ заступле́ніє. Умоли́ Го́спода Бо́га, всея́ тва́рі Созда́теля, ізба́вити нас от ві́чнаго муче́нія, да прославля́єм Отця́, і Си́на, і Свята́го Ду́ха і твоє́ іспові́дуєм предста́тельство ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О всехва́льний, святи́й великому́чениче і чудотво́рче Гео́ргіє! При́зри на ни ско́рою твоє́ю по́мощію і умоли́ Человіколю́бця Бо́га, да не осу́дить нас, грі́шних, по беззако́ніям на́шим, но да сотвори́ть с на́ми по вели́цій Своє́й ми́лості. Не пре́зри моле́нія на́шего, но іспроси́ нам у Христа́ Бо́га на́шего ти́хоє і богоуго́дноє житіє́, здра́віє же душе́вноє і тіле́сноє, землі́ плодоро́діє і во всем ізоби́ліє, і да не во зло обрати́м да́руємая нам тобо́ю от Всеще́драго Бо́га, но во сла́ву свята́го І́мені Єго́ і в прославле́ніє крі́пкаго твоєго́ заступле́нія, да пода́сть Он страні́ на́шей і всему́ боголюби́вому во́їнству на супоста́ти одолі́ніє і да укріпи́ть непреміня́ємим ми́ром і благослове́нієм. Ізря́дніє же да огради́ть нас святи́х А́нгел Свої́х ополче́нієм, во є́же ізба́витися нам по ісхо́ді на́шем із житія́ сего́ от ко́зней лука́ваго і тя́жких возду́шних мита́рств єго́ і неосужде́нним предста́ти Престо́лу Го́спода сла́ви. Усли́ши нас, страстоте́рпче Христо́в Гео́ргіє, і моли́ за ни непреста́нно Триіпоста́снаго Влади́ку всіх Бо́га, да благода́тію Єго́ і человіколю́бієм, твоє́ю же по́мощію і заступле́нієм обря́щем ми́лость со А́нгели і Арха́нгели і всі́ми святи́ми одесну́ю Правосу́днаго Судії́ ста́ти і Того́ ви́ну сла́вити со Отце́м і Святи́м Ду́хом ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Я́ко плі́нних свободи́тель / і ни́щих защи́титель, / немощству́ющих врач, / царе́й побо́рниче, / побідоно́сче великому́чениче Гео́ргіє, // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Інший тропар, глас 4","ps":["По́двигом до́брим подвиза́лся єси́, страстоте́рпче Христо́в, / ві́рою, і мучи́телей обличи́л єси́ нече́стіє, / же́ртва же благоприя́тна Бо́гу прине́слся єси́, / ті́мже і віне́ць прия́л єси́ побі́ди, // і моли́твами, свя́те, твої́ми всім подає́ши прегріше́ній проще́ніє."]},{"h":"Кондак, глас 4","ps":["Возді́лан от Бо́га показа́лся єси́ благоче́стія ді́латель честні́йший, / доброді́телей рукоя́ті собра́в себі́, / сі́яв бо в слеза́х, весе́лієм жне́ши, / страда́льчествовав же кро́вію, Христа́ прия́л єси́, // і моли́твами, свя́те, твої́ми всім подає́ши прегріше́ній проще́ніє."]},{"h":"Інший кондак, глас 8","ps":["К возбра́нному і ско́рому заступле́нію твоєму́ прибі́гше ві́рнії, / мо́лим ізба́витися, страстоте́рпче Христо́в, от собла́зн вра́жиїх, / воспіва́ющим тя, і вся́ких бід і озлобле́ній, да зове́м: // ра́дуйся, му́чениче Гео́ргіє."]},{"h":"Величання","ps":["Велича́єм тя, страстоте́рпче святи́й великому́чениче і побідоно́сче Гео́ргіє, і чтим страда́нія твоя́, я́же за Христа́ претерпі́л єси́."]}],"notes":[]},{"u":"Акафіст святителю Миколаю Чудотворцю","e":"Akathist to St Nicholas the Wonderworker","secs":[{"h":"Кондак 1","ps":["Возбра́нний чудотво́рче, і ізря́дний уго́дниче Христо́в, ми́ру всему́ істоча́яй многоці́нноє ми́лости ми́ро, і неісчерпа́ємоє чуде́с мо́ре, восхваля́ю тя любо́вію, святи́телю Нико́лає; ти же я́ко імі́яй дерзнове́ніє ко Го́споду, от вся́ких м'я бід свободи́, да зову́ ті:","Ра́дуйся, Нико́лає, вели́кий чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгела о́бразом, земна́го су́ща єстество́м, яви́ тебі́ всея́ тва́рі Созда́тель: благопло́дную бо добро́ту душі́ твоєя́ прови́дів, преблаже́нне Нико́лає, научи́ всіх вопи́ти тебі́ си́це:","Ра́дуйся, от утро́би ма́тернія очище́нний;","Ра́дуйся, да́же до конця́ освяще́нний.","Ра́дуйся, рожде́нієм свої́м роди́телей удиви́вий;","Ра́дуйся, си́лу душе́вную а́біє по рождестві́ яви́вий.","Ра́дуйся, са́де землі́ обітова́нія;","Ра́дуйся, цві́те Боже́ственнаго сажде́нія.","Ра́дуйся, лозо́ доброді́тельная виногра́да Христо́ва;","Ра́дуйся, дре́во чудото́чноє рая́ Ісу́сова.","Ра́дуйся, кри́не ра́йськаго прозябе́нія;","Ра́дуйся, ми́ро Христо́ва благоуха́нія.","Ра́дуйся, я́ко тобо́ю отго́ниться рида́ніє;","Ра́дуйся, я́ко тобо́ю прино́ситься ра́дованіє.","Ра́дуйся, Нико́лає, вели́кий чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дяще твої́х мир ізлія́ніє, богому́дре, просвіща́ємся душа́ми і тілеси́, ди́внаго тя мирото́чця живоно́сна, Нико́лає, разумі́юще: чудеси́ бо, я́ко вода́ми, благода́тію Бо́жиєю ізлива́ющимися, напая́єши ві́рно вопію́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум неуразумі́нний вразумля́я о Святі́й Тро́йці, бил єси́ в Нике́ї со святи́ми отці́ побо́рник іспові́данія правосла́вния ві́ри: ра́вна бо Отцю́ Си́на іспові́дал єси́, соприсносу́щна і сопресто́льна, А́рія же безу́мнаго обличи́л єси́. Сего́ ра́ди ві́рнії научи́шася воспіва́ти тебі́:","Ра́дуйся, вели́кий благоче́стія сто́лпе;","Ра́дуйся, ві́рних прибі́жища гра́де.","Ра́дуйся, тве́рдоє Правосла́вія укріпле́ніє;","Ра́дуйся, честно́є Пресвяти́я Тро́йці носи́ло і похвале́ніє.","Ра́дуйся, Отцю́ равноче́стна Си́на пропові́давий;","Ра́дуйся, А́рія возбіси́вшагося от Собо́ра святи́х отгна́вий.","Ра́дуйся, о́тче, отце́в сла́вная красото́;","Ра́дуйся, всіх богому́дрих прему́драя добро́то.","Ра́дуйся, о́гненная словеса́ іспуща́яй;","Ра́дуйся, до́брі ста́до своє́ наставля́яй.","Ра́дуйся, я́ко тобо́ю ві́ра утвержда́ється;","Ра́дуйся, я́ко тобо́ю є́ресь низлага́ється.","Ра́дуйся, Нико́лає, вели́кий чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лою, да́нною ті сви́ше, сле́зу вся́ку от'я́л єси́ от лиця́ лю́ті стра́ждущих, богоно́се о́тче Нико́лає: а́лчущим бо яви́лся єси́ корми́тель, в пучи́ні морсті́й су́щим ізря́дний прави́тель, неду́гующим ісціле́ніє, і всім всяк помо́щник показа́лся єси́, вопію́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яше воі́стину, о́тче Нико́лає, с небесе́ піснь тебі́ воспіва́єма би́ти, а не от землі́: ка́ко бо кто от челові́к возмо́жеть твоєя́ святи́ні вели́чія пропові́дати; но ми, любо́вію твоє́ю побіжда́єми, вопіє́м ті си́це:","Ра́дуйся, о́бразе а́гнцев і па́стирей;","Ра́дуйся, свято́є очисти́лище нра́вов.","Ра́дуйся, доброді́телей вели́ких вмісти́лище;","Ра́дуйся, святи́ні чи́стоє і честно́є жили́ще.","Ра́дуйся, світи́льниче всесві́тлий і вселюби́мий;","Ра́дуйся, сві́те златоза́рний і непоро́чний.","Ра́дуйся, досто́йний А́нгелов собесі́дниче;","Ра́дуйся, до́брий челові́ков наста́вниче.","Ра́дуйся, пра́вило ві́ри благочести́вия;","Ра́дуйся, о́бразе кро́тости духо́вния.","Ра́дуйся, я́ко тобо́ю от страсте́й тіле́сних ізбавля́ємся;","Ра́дуйся, я́ко тобо́ю сла́достей духо́вних ісполня́ємся.","Ра́дуйся, Нико́лає, вели́кий чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́ря недоумі́нія смуща́єть мі ум, ка́ко досто́йно єсть пі́ти чудеса́ твоя́, блаже́нне Нико́лає: нікто́же бо мо́жеть я ісчести́, а́ще би і мно́гі язи́ки імі́л і глаго́лати восхоті́л; но ми ди́вно Бо́гу в тебі́ прославля́ющемуся дерза́єм воспіва́ти: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша, богому́дре Нико́лає, бли́жнії і да́льнії вели́чіє чуде́с твої́х, я́ко по возду́ху ле́гкими благода́тними крила́ми нави́кл єси́ су́щих в біда́х предваря́ти, ско́ро от тіх избавля́я всіх, вопію́щих к тебі́ такова́я:","Ра́дуйся, ізбавле́ніє от печа́лі;","Ра́дуйся, подая́ніє благода́ті.","Ра́дуйся, неча́ємих зол прогони́телю;","Ра́дуйся, жела́ємих благи́х насади́телю.","Ра́дуйся, ско́рий уті́шителю в біді́ су́щих;","Ра́дуйся, стра́шний наказа́телю оби́дящих.","Ра́дуйся, чуде́с пучи́но, Бо́гом ізлія́нная;","Ра́дуйся, зако́на Христо́ва скрижа́ли, Бо́гом пи́санния.","Ра́дуйся, крі́пкоє па́дающих возведе́ніє;","Ра́дуйся, пра́во стоя́щих утвержде́ніє.","Ра́дуйся, я́ко тобо́ю вся́кая лесть обнажа́ється;","Ра́дуйся, я́ко тобо́ю вся́кая і́стина сбива́ється.","Ра́дуйся, Нико́лає, вели́кий чудотво́рче."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́лся єси́, наставля́я по мо́рю пла́вающих лю́ті, і́мже смерть предстоя́ше вско́рі іногда́, а́ще не би ти предста́л єси́ призива́ющим тя в по́мощ, чудотво́рче святи́й Нико́лає: уже́ бо нести́дно бісо́м лета́ющим і погрузи́ти корабли́ хотя́щим запрети́в, отгна́л єси́ їх, ві́рния же научи́л єси́ спаса́ющему тобо́ю Бо́гу взива́ти: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша отрокови́ці, на брак скве́рний нищети́ ра́ди угото́ванния, вели́коє твоє́ к ни́щим милосе́рдіє, преблаже́нне о́тче Нико́лає, єгда́ ста́рцю роди́телю їх но́щію узельці́ три зла́та тая́ся по́дал єси́, самаго́ со дще́рми ізбавля́я от паде́нія гріхо́внаго. Того́ ра́ди сли́шиши от всіх си́це:","Ра́дуйся, ми́лости превели́кия сокро́вище;","Ра́дуйся, промишле́нія о лю́діх прия́телище.","Ра́дуйся, пи́ще і отра́до к тебі́ прибіга́ющих;","Ра́дуйся, хлі́бе несніда́ємий а́лчущих.","Ра́дуйся, бога́тство, бі́дні живу́щим на землі́ Бо́гом да́нноє;","Ра́дуйся, воздви́женіє ско́роє убо́гих.","Ра́дуйся, би́строє ни́щих усли́шаніє;","Ра́дуйся, скорб'я́щих прия́тноє попече́ніє.","Ра́дуйся, тріє́х дів непоро́чний невісти́телю;","Ра́дуйся, чистоти́ усе́рдний храни́телю.","Ра́дуйся, ненаде́жних наді́яніє;","Ра́дуйся, всего́ ми́ра наслажде́ніє.","Ра́дуйся, Нико́лає, вели́кий чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дуєть мир весь тебі́, преблаже́нне Нико́лає, ско́раго в біда́х засту́пника, я́ко мно́гажди во єди́ном часі́, по землі́ путеше́ствующим і по мо́рю пла́вающим, предваря́я посо́бствуєши, ку́пно всіх от злих сохраня́я, вопію́щих к Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ світ живо́тний, ізбавле́ніє нося́ воєво́дам, непра́ведную смерть прия́ти іму́щим, тебі́, до́брий па́стирю Нико́лає, призива́ющим, єгда́ вско́рі я́влься во сні царе́ві, устраши́л єси́ єго́, сих же неврежде́нних отпусти́ти повелі́л єси́. Сего́ ра́ди с ни́ми ку́пно і ми благода́рственно вопіє́м ті:","Ра́дуйся, усе́рдно призива́ющим тя помога́яй;","Ра́дуйся, от непра́веднаго убіє́нія ізбавля́яй.","Ра́дуйся, от ле́стния сохраня́яй клевети́;","Ра́дуйся, непра́ведния разруша́яй сові́ти.","Ра́дуйся, растерза́яй лжу, я́ко паучи́ну;","Ра́дуйся, возноша́яй сла́вно і́стину.","Ра́дуйся, непови́нних от уз разріше́ніє;","Ра́дуйся, і мертвеце́в оживле́ніє.","Ра́дуйся, прояви́телю пра́вди;","Ра́дуйся, помрачи́телю непра́вди.","Ра́дуйся, я́ко тобо́ю непови́ннії ізба́влени от меча́;","Ра́дуйся, я́ко тобо́ю наслади́шася сві́та.","Ра́дуйся, Нико́лає, вели́кий чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́ богоху́льноє єрети́чеськоє отгна́ти злосмра́діє, ми́ро воі́стину благово́нноє та́їнственноє яви́лся єси́, Нико́лає: лю́ди мире́йськия упа́сл єси́, і весь мир свої́м благода́тним ми́ром іспо́лнил єси́; і от нас у́бо богоме́рзькоє гріхо́вноє злосмра́діє отжени́, да благоприя́тно Бо́гу вопіє́м: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя Но́я, наста́вника ковче́га спаси́тельнаго разумі́єм, о́тче святи́й Нико́лає, бу́рю всіх лю́тих разгоня́ющаго направле́нієм свої́м, тишину́ же Боже́ственную принося́щаго вопію́щим такова́я:","Ра́дуйся, обурева́ємих ти́хоє приста́нище;","Ра́дуйся, утопа́ющих ізві́стноє храни́лище.","Ра́дуйся, пла́вающих посреді́ пучи́н до́брий ко́рмчий;","Ра́дуйся, треволне́нія морська́я уставля́ющий.","Ра́дуйся, превожде́ніє су́щих во ви́хріх;","Ра́дуйся, согрі́яніє су́щих во мра́зіх.","Ра́дуйся, сія́ніє, ско́рбний мрак разгоня́ющеє;","Ра́дуйся, світи́ло, вся конці́ землі́ просвіща́ющеє.","Ра́дуйся, от бе́здни гріхо́вния челові́ки ізбавля́яй;","Ра́дуйся, в бе́здну а́дськую сатану́ вверга́яй.","Ра́дуйся, я́ко тобо́ю дерзнове́нно бе́здну милосе́рдія Бо́жия призива́єм;","Ра́дуйся, я́ко тобо́ю от пото́па гні́ва ізба́вльшеся, мир с Бо́гом обріта́єм.","Ра́дуйся, Нико́лає, вели́кий чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до явля́ється притека́ющим к тебі́, блаже́нне Нико́лає, свяще́нная твоя́ це́рков: в ней бо і ма́лоє моле́ніє принося́ще, ве́ліїх неду́гов приє́млем ісціле́ніє, а́ще то́кмо по Бо́зі упова́ніє на тя возложи́м, ві́рно вопію́ще: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь єси́ всім воі́стину помо́щник, богоно́се Нико́лає, і собра́л єси́ вку́пі вся прибега́ющия к тебі́, я́ко свободи́тель, пита́тель і врач ско́рий всім земни́м, на похвалу́ всіх подвиза́я, вопи́ти к тебі́ си́це:","Ра́дуйся, вся́ких ісціле́ній істо́чниче;","Ра́дуйся, лю́ті стра́ждущим помо́щниче.","Ра́дуйся, заре́, сія́ющая в нощі́ гріхо́вній блужда́ющим;","Ра́дуйся, росо́ небото́чная в зно́ї трудо́в су́щим.","Ра́дуйся, подава́яй тре́бующим благостроє́ніє;","Ра́дуйся, уготовля́яй прося́щим ізоби́ліє.","Ра́дуйся, мно́гажди проше́ніє предваря́яй;","Ра́дуйся, ста́рим сіди́нам си́лу обновля́яй.","Ра́дуйся, мно́гих заблу́ждших от путі́ і́стиннаго обличи́телю;","Ра́дуйся, та́їн Бо́жиїх ві́рний служи́телю.","Ра́дуйся, я́ко тобо́ю за́висть попира́єм;","Ра́дуйся, я́ко тобо́ю благонра́вноє житіє́ ісправля́єм.","Ра́дуйся, Нико́лає, вели́кий чудотво́рче."]},{"h":"Кондак 9","ps":["Вся́кия утоли́ болі́зні, вели́кий наш засту́пниче Нико́лає, растворя́я благода́тная врачева́нія, услажда́ющая ду́ші на́ша, сердця́ же веселя́щая всіх усе́рдно к по́мощі твоє́й притека́ющих, Бо́гу же вопію́щих: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я суєму́дренния нечести́вих ви́дим тобо́ю посра́мленния, богому́дре о́тче Нико́лає: А́рія бо ху́льника, разділя́юща Божество́, і Саве́ллія, сміша́юща Святу́ю Тро́йцю, препрі́л, нас же во Правосла́вії укріпи́л єси́. Сего́ ра́ди вопіє́м ті си́це:","Ра́дуйся, щі́те, защища́яй благоче́стіє;","Ра́дуйся, мечу́, посіця́яй злоче́стіє.","Ра́дуйся, учи́телю Боже́ственних велі́ній;","Ра́дуйся, губи́телю богопроти́вних уче́ній.","Ра́дуйся, лі́ствице, Бо́гом утвержде́нная, є́юже восхо́дим к небесі́;","Ра́дуйся, покро́ве, Бо́гом зда́нний, і́мже покрива́ються мно́зі.","Ра́дуйся, нему́дрих умудри́вий твої́ми словеси́;","Ра́дуйся, ліни́вих подви́гнувий твої́ми нра́ви.","Ра́дуйся, сві́тлосте за́повідей Бо́жиїх неугаси́мая;","Ра́дуйся, луче́ оправда́ній Госпо́дніх пресві́тлая.","Ра́дуйся, я́ко уче́нієм твої́м сокруша́ються єрети́чеськия глави́;","Ра́дуйся, я́ко тобо́ю ві́рнії сподобля́ються сла́ви.","Ра́дуйся, Нико́лає, вели́кий чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́шу, плоть твою́ ду́хові покори́л єси́ воі́стину, о́тче наш Нико́лає: молча́ньми бо пре́жде і боре́ньми с по́мисли, дія́нію богоми́сліє приложи́л єси́, богоми́слієм же ра́зум соверше́н стяжа́л єси́, і́мже дерзнове́нно с Бо́гом і А́нгели бесі́довал єси́, всегда́ вопія́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ похваля́ющим, преблаже́нне, чудеса́ твоя́, і всім к заступле́нію твоєму́ прибега́ющим; ті́мже і нас, в доброді́телі убо́гих, от нищети́, напа́сти, неду́гов і нужд разли́чних свобожда́й, вопію́щих ті с любо́вію такова́я:","Ра́дуйся, от убо́жества ві́чнаго ізима́яй;","Ра́дуйся, бога́тство нетлі́нноє подава́яй.","Ра́дуйся, бра́шно неги́блющеє а́лчущим пра́вди;","Ра́дуйся, питіє́ неісчерпа́ємоє жа́ждущим жи́зні.","Ра́дуйся, от м'яте́жа і бра́ни соблюда́яй;","Ра́дуйся, от уз і пліне́нія свобожда́яй.","Ра́дуйся, пресла́вний в біда́х засту́пниче;","Ра́дуйся, превели́кий в напа́стіх защи́тниче.","Ра́дуйся, мно́гих от поги́белі ісхи́тивий;","Ра́дуйся, безчи́сленних неврежде́нно сохрани́вий.","Ра́дуйся, я́ко тобо́ю лю́тия сме́рті грі́шнії ізбіга́ють;","Ра́дуйся, я́ко тобо́ю жизнь ві́чную ка́ющіїся получа́ють.","Ра́дуйся, Нико́лає, вели́кий чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє Пресвяті́й Тро́йце па́че іни́х прине́сл єси́, преблаже́нне Нико́лає, умо́м, сло́вом і ді́лом: мно́гим бо іспита́нієм правові́рная повелі́нія уясни́л єси́, ві́рою, наде́ждою і любо́вію наставля́я нас в Тро́йці Єди́ному Бо́гу воспіва́ти: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рную лучу́, во мра́ці житія́ су́щим неугаси́мую, ви́дим тя, Бо́гом ізбра́нне о́тче Нико́лає: с невеще́ственними бо а́нгельськими сві́ти бесі́дуєши о несозда́нном Тро́їчеськом Сві́те, ві́рних же ду́ші просвіща́єши, вопію́щих ті такова́я:","Ра́дуйся, озаре́ніє Трисо́лнечнаго Сві́та;","Ра́дуйся, денни́це незаходи́маго Со́лнця.","Ра́дуйся, свіще́, Боже́ственним пла́менем возжже́нная;","Ра́дуйся, я́ко угаси́л єси́ бісо́вський пла́мень нече́стія.","Ра́дуйся, сві́тлоє правові́рія пропові́даніє;","Ра́дуйся, доброзра́чноє сві́та єва́нгельськаго сія́ніє.","Ра́дуйся, мо́лніє, є́ресі пожига́ющая;","Ра́дуйся, гро́ме, устраша́ющий соблазня́ющия.","Ра́дуйся, і́стиннаго научи́телю ра́зума;","Ра́дуйся, та́їнственнаго із'яви́телю ума́.","Ра́дуйся, я́ко тобо́ю попра́ся поклоне́ніє тва́рі;","Ра́дуйся, я́ко тобо́ю научи́хомся покланя́тися Творцю́ в Тро́йці.","Ра́дуйся, Нико́лає, вели́кий чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть да́нную ті от Бо́га сві́дущії, ра́дующеся твою́ па́м'ять пра́зднуєм по до́лгу, пресла́вний о́тче Нико́лає, і к чу́дному заступле́нію твоєму́ вседу́шно притека́єм; пресла́вних же твої́х дія́ній, я́ко песка́ морська́го і мно́жества зві́зднаго, ісчести́ не могу́ще, недоумі́нієм об'я́ти би́вше, вопіє́м к Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоя́ чудеса́, восхваля́єм тя, всехва́льне Нико́лає: в тебі́ бо Бог в Тро́йці прославля́ємий ди́вно просла́вися. Но а́ще і попремно́гу соста́вленния от душі́ псалми́ і пі́сні прино́сим ті, чудотво́рче святи́й, нічто́же твори́м ра́вно дарова́нію чуде́с твої́х, і́мже удивля́ющеся, вопіє́м к тебі́ такова́я:","Ра́дуйся, Царя́ ца́рствующих і Го́спода госпо́дствующих служи́телю;","Ра́дуйся, служи́телей Єго́ небе́сних сожи́телю.","Ра́дуйся, лю́дем ві́рним поможе́ніє;","Ра́дуйся, ро́да христия́нськаго возвише́ніє.","Ра́дуйся, побі́ди тезоимени́тий;","Ра́дуйся, вінцено́сче нарочи́тий.","Ра́дуйся, всіх доброді́телей зерца́ло;","Ра́дуйся, всіх притека́ющих к тебі́ крі́пкоє забра́ло.","Ра́дуйся, по Бо́зі і Богоро́дице все на́ше упова́ніє;","Ра́дуйся, тіле́с на́ших здра́віє і душ спасе́ніє.","Ра́дуйся, я́ко тобо́ю от ві́чния сме́рти свобожда́ємся;","Ра́дуйся, я́ко тобо́ю безконе́чния жи́зні сподобля́ємся.","Ра́дуйся, Нико́лає, вели́кий чудотво́рче."]},{"h":"Кондак 13","ps":["О пресвяти́й і пречу́дний о́тче Нико́лає, утіше́ніє всіх скорб'я́щих, ни́нішнєє на́ше прийми́ приноше́ніє, і от геє́нни ізба́витися нам Го́спода умоли́, богоприя́тним твої́м хода́тайством, да с тобо́ю воспіва́єм: Аллилу́я, аллилу́я, аллилу́я.","§Цей кондак промовляй тричі. Потім:"]},{"h":"Ікос 1","ps":["А́нгела о́бразом, земна́го су́ща єстество́м, яви́ тебі́ всея́ тва́рі Созда́тель: благопло́дную бо добро́ту душі́ твоєя́ прови́дів, преблаже́нне Нико́лає, научи́ всіх вопи́ти тебі́ си́це:","Ра́дуйся, от утро́би ма́тернія очище́нний;","Ра́дуйся, да́же до конця́ освяще́нний.","Ра́дуйся, рожде́нієм свої́м роди́телей удиви́вий;","Ра́дуйся, си́лу душе́вную а́біє по рождестві́ яви́вий.","Ра́дуйся, са́де землі́ обітова́нія;","Ра́дуйся, цві́те Боже́ственнаго сажде́нія.","Ра́дуйся, лозо́ доброді́тельная виногра́да Христо́ва;","Ра́дуйся, дре́во чудото́чноє рая́ Ісу́сова.","Ра́дуйся, кри́не ра́йськаго прозябе́нія;","Ра́дуйся, ми́ро Христо́ва благоуха́нія.","Ра́дуйся, я́ко тобо́ю отго́ниться рида́ніє;","Ра́дуйся, я́ко тобо́ю прино́ситься ра́дованіє.","Ра́дуйся, Нико́лає, вели́кий чудотво́рче."]},{"h":"Кондак 1","ps":["Возбра́нний чудотво́рче, і ізря́дний уго́дниче Христо́в, ми́ру всему́ істоча́яй многоці́нноє ми́лости ми́ро, і неісчерпа́ємоє чуде́с мо́ре, восхваля́ю тя любо́вію, святи́телю Нико́лає; ти же я́ко імі́яй дерзнове́ніє ко Го́споду, от вся́ких м'я бід свободи́, да зову́ ті:","Ра́дуйся, Нико́лає, вели́кий чудотво́рче."]},{"h":"Молитва","ps":["О всесвяти́й Нико́лає, уго́дниче преізря́дний Госпо́день, те́плий наш засту́пниче, і везді́ в ско́рбіх ско́рий помо́щниче! Помози́ мні, грі́шному і уни́лому, в настоя́щем сем житії́, умоли́ Го́спода Бо́га дарова́ти мі оставле́ніє всіх мої́х гріхо́в, єли́ко согріши́х от ю́ности моєя́, во всем житії́ моє́м, ді́лом, сло́вом, помишле́нієм і всі́ми мої́ми чу́встви; і во ісхо́ді душі́ моєя́ помози́ мі окая́нному, умоли́ Го́спода Бо́га, всея́ тва́рі Соді́теля, ізба́вити м'я возду́шних мита́рств і ві́чнаго муче́нія, да всегда́ прославля́ю Отця́, і Си́на, і Свята́го Ду́ха, і твоє́ ми́лостивноє предста́тельство, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Пра́вило ві́ри і о́браз кро́тости, / воздержа́нія учи́теля / яви́ тя ста́ду твоєму́, / я́же веще́й і́стина. / Сего́ ра́ди стяжа́л єси́ смире́нієм висо́кая, / нището́ю бога́тая, / о́тче священнонача́льниче Нико́лає / моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 3","ps":["В Ми́ріх свя́те священноді́йствитель показа́лся єси́, / Христо́во бо преподо́бне Єва́нгеліє іспо́лнив, / положи́л єси́ ду́шу твою́ о лю́діх твої́х, / і спасл єси́ непови́нния от сме́рти. / Сего́ ра́ди освяти́лся єси́, // я́ко вели́кий таї́нник Бо́жия благода́ті."]},{"h":"Величання","ps":["Велича́єм тя, святи́телю о́тче Нико́лає, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст преподобному Серафиму Саровському, чудотворцю","e":"Akathist to our Venerable Father Seraphim of Sarov, the Wonderworker","secs":[{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і преди́вний уго́дниче Христо́в, ско́рий помо́щниче і моли́твенниче наш, преподо́бне о́тче Серафи́ме! Велича́юще просла́вльшаго тя Го́спода, воспіва́єм ті похва́льная. Ти же, імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, зову́щих:","Ра́дуйся, преподо́бне Серафи́ме, Саро́вський чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць ізбра́ тя ізнача́ла, да просла́виши житіє́м твої́м пречу́дноє і́м'я Святи́я Тро́йці: яви́лся бо єси́ воі́стину а́нгел на землі́ і во пло́ті серафи́м; я́ко луч пресві́тлий Ві́чнаго Со́лнця Пра́вди, просвіти́ся житіє́ твоє́. Ми же, зря́ще прехва́льния труди́ твоя́, с благогові́нієм і ра́достію глаго́лем ті сицева́я:","Ра́дуйся, пра́вило ві́ри і благоче́стія;","ра́дуйся, о́бразе кро́тости і смире́нія.","Ра́дуйся, пресла́вноє ві́рних велича́ніє;","ра́дуйся, прети́хоє ско́рбним утіше́ніє.","Ра́дуйся, прелюби́моє і́ноков похвале́ніє;","ра́дуйся, живу́щим в ми́рі преди́вноє поможе́ніє.","Ра́дуйся, Россі́йськия держа́ви сла́во і огражде́ніє;","ра́дуйся, тамбо́вськия страни́ свяще́нноє украше́ніє.","Ра́дуйся, преподо́бне Серафи́ме, Саро́вський чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дящи ма́ти твоя́, преподо́бне о́тче Серафи́ме, те́плую любо́в твою́ ко і́ночеському житію́, позна́ святу́ю во́лю Госпо́дню о тебі́, і Бо́гу, я́ко дар соверше́н принося́щи, благослови́ тя на ті́сний путь і́ночеський святи́м кресто́м свої́м, єго́же до конця́ житія́ твоєго́ на пе́рсіх носи́л єси́, зна́менуя ве́лію любо́в твою́ к распе́ншемуся за ни Христу́ Бо́гу на́шему, Єму́же всі со умиле́нієм зове́м: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум небе́сний тебі́ дарова́ся, свя́тче Бо́жий: от ю́ности твоєя́ не престая́ помишля́ти о Небе́снім, оста́вил єси́ дом о́тчий Ца́рствія Бо́жия ра́ди і пра́вди Єго́. Сего́ ра́ди прийми́ от нас похвали́ сія́:","Ра́дуйся, гра́да Ку́рська ча́до богоізбра́нноє;","ра́дуйся, роди́телей благочести́вих о́трасль пречестна́я.","Ра́дуйся, доброді́телі ма́тере своєя́ унаслі́дивий;","ра́дуйся, благоче́стію і моли́тві є́ю науче́нний.","Ра́дуйся, на по́двиги от ма́тере кресто́м благослове́нний;","ра́дуйся, благослове́ніє сіє́ я́ко святи́ню до сме́рти соблюди́й.","Ра́дуйся, любве́ ра́ди Го́спода дом оте́чеський оста́вивий;","ра́дуйся, вся красна́я ми́ра сего́ ні во что же вміни́вий.","Ра́дуйся, преподо́бне Серафи́ме, Саро́вський чудотво́рче."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго от ю́ности твоєя́ воі́стину храня́ше тя, преподо́бне: с висоти́ бо хра́ма спа́дша сохрани́ тя Госпо́дь неврежде́нна, і стра́ждущу ті лю́ті Сама́ Влади́чиця ми́ра яви́ся, с Небе́с ісціле́ніє прине́сши, зане́ ізмла́да ві́рно служи́л єси́ Бо́гу, ви́ну взива́я Єму́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я тща́ніє о по́двизі і́ночеськаго равноа́нгельнаго житія́, во град святи́й Ки́єв поклоне́нія ра́ди преподо́бним Пече́рським прите́кл єси́, і от уст преподо́бнаго Досифе́я повелі́ніє приї́м в пусти́ню Саро́вськую путь свой упра́вити, ві́рою іздале́ча облобиза́л єси́ мі́сто свято́є сіє́, і та́мо всели́вся житіє́ твоє́ богоуго́дноє сконча́л єси́. Ми же, див'я́щеся таково́му о тебі́ Бо́жию промишле́нію, со умиле́нієм вопіє́м ті:","Ра́дуйся, мирськи́я суєти́ отріши́вийся;","ра́дуйся, Небе́снаго Оте́чества пла́менно возжелі́вий.","Ра́дуйся, Христа́ всім се́рдцем возлюби́вий;","ра́дуйся, благо́є і́го Христо́во на себі́ восприє́мий.","Ра́дуйся, соверше́ннаго послуша́нія іспо́лненний;","ра́дуйся, святи́х за́повідей Госпо́дніх блюсти́телю ві́рний.","Ра́дуйся, ум твой і се́рдце в Бо́зі моли́твенно утверди́вий;","ра́дуйся, сто́лпе благоче́стія непоколеби́мий.","Ра́дуйся, преподо́бне Серафи́ме, Саро́вський чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рю злих напа́стей утиша́я, проше́л єси́ весь путь ті́сний і ско́рбний по́двига і́ночеськаго, неси́й яре́м пусти́ннаго житія́, затво́ра і молча́нія, многоно́щнаго бді́нія, і та́ко, благода́тію Бо́жиєю восходя́ от си́ли в си́лу, от дія́нія к богови́дінію, пресели́лся єси́ во Оби́телі Го́рнія, іді́же со А́нгели поє́ши Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще і ви́дяще свято́є житіє́ твоє́, преподо́бне о́тче Серафи́ме, вся бра́тія твоя́ удивля́хуся тебі́ і, приходя́ще к тебі́, поуча́хуся о словесі́х твої́х і по́двизіх, сла́в'яще Го́спода, ди́внаго во святи́х Свої́х. І ми всі с ві́рою і любо́вію восхваля́єм тя, преподо́бне о́тче, і вопіє́м ті си́це:","Ра́дуйся, всего́ себе́ в же́ртву Го́сподеві принеси́й;","ра́дуйся, на висоту́ безстра́стія возше́дий.","Ра́дуйся, во́їне Христо́в добропобі́дний;","ра́дуйся, Небе́снаго Домовлади́ки ра́бе благи́й і ві́рний.","Ра́дуйся, предста́телю о нас пред Го́сподем непости́дний;","ра́дуйся, к Богоро́диці моли́твенниче наш неуси́пний.","Ра́дуйся, пречу́днаго благоуха́нія кри́не пусти́нний;","ра́дуйся, благода́ті Бо́жия сосу́де непоро́чний.","Ра́дуйся, преподо́бне Серафи́ме, Саро́вський чудотво́рче."]},{"h":"Кондак 5","ps":["Боже́ственний світ осія́ жили́ще твоє́, преподо́бне, єгда́ боля́щу ті і на одрі́ сме́ртнім лежа́щу, Сама́ Пречи́стая Ді́ва, прише́дши к тебі́ со святи́ми апо́столи Петро́м і Іоа́нном, рече́: «Сей єсть от ро́да на́шего», - і главі́ твоє́й косну́ся. А́біє же ісцілі́в, воспі́л єси́ благода́рні Го́сподеві: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя враг ро́да челові́ча чи́стоє і свято́є житіє́ твоє́, преподо́бне Серафи́ме, восхоті́ погуби́ти тя: наведе́ бо на тя лю́ди зли, і́же беззако́нно істяза́ху тя і є́ле жи́ва су́ща оста́виша; ти же, о́тче святи́й, я́ко а́гнець кро́ток, вся претерпі́л єси́, за оби́дящих тя Го́сподеві моля́ся. Ті́мже ми всі, таково́му твоєму́ незло́бію див'я́щеся, вопіє́м ті:","Ра́дуйся, в кро́тости і смире́нії твоє́м Христу́ Бо́гу подража́вий;","ра́дуйся, незло́бієм твої́м ду́ха зло́би побіди́вий.","Ра́дуйся, чистоти́ душе́вния і тіле́сния храни́телю усе́рдний;","ра́дуйся, пусти́нниче, дара́ми благода́тними преіспо́лненний.","Ра́дуйся, подви́жниче богопросла́вленний і прозорли́вий;","ра́дуйся, наста́вниче мона́хов преди́вний і богому́дрий.","Ра́дуйся, Святи́я Це́ркве похвало́ і ра́дованіє;","ра́дуйся, оби́телі Саро́вськия сла́во і удобре́ніє.","Ра́дуйся, преподо́бне Серафи́ме, Саро́вський чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дуєть пусти́ня Саро́вськая по́двиги і труди́ твоя́, богоно́сне уго́дниче Христо́в: де́бри бо і ліса́ єя́ моли́твою облагоуха́л єси́, проро́ку Бо́жию Ілії́ і Крести́телю Госпо́дню Іоа́нну подража́я, і яви́лся єси́ пусти́ні прозябе́ніє многопло́дноє дара́ми Ду́ха Свята́го, Єго́же ді́йствієм мно́гая і пресла́вная соверши́л єси́, подвиза́я ві́рних воспіва́ти благи́х Пода́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ в тебі́ но́вий богови́дець, Моїсе́ю подо́бний, Серафи́ме блаже́нне: непоро́чно бо служе́ніє олтарю́ Госпо́дню соверша́я, сподо́бился єси́ зрі́ти Христа́, во хра́мі со Безпло́тними Си́лами гряду́ща. Сему́ Бо́жию о тебі́ благоволе́нію див'я́щеся, воспіва́єм ті си́це:","Ра́дуйся, богови́дче пресла́вний;","ра́дуйся, Сві́том Трисія́нним озаре́нний.","Ра́дуйся, Пресвяти́я Тро́йці служи́телю ві́рний;","ра́дуйся, Ду́ха Свята́го жили́ще украше́нноє.","Ра́дуйся, Христа́ со А́нгели тіле́снима очи́ма лицезрі́вий;","ра́дуйся, в бре́ннім тілесі́ ра́йськую сла́дость предвкуси́вий.","Ра́дуйся, Хлі́бом Жи́зні насище́нний;","ра́дуйся, питіє́м безсме́ртія напоє́нний.","Ра́дуйся, преподо́бне Серафи́ме, Саро́вський чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́ Человіколю́бець Госпо́дь яви́ти в тебі́, преподо́бне, Своє́ неізрече́нноє к лю́дем милосе́рдіє, показа́ тя я́ко воі́стину світи́ло богосві́тлоє: ді́ли бо і словеси́ твої́ми всіх приводи́л єси́ ко благоче́стію і любві́ Бо́жієй. Ті́мже сія́нієм по́двигов твої́х просвіще́ни і хлі́бом уче́нія твоєго́ насище́ни, тебі́ усе́рдно велича́єм і просла́вльшему тя Христу́ вопіє́м: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго ви́дяще тя ізбра́нника Бо́жия, іздале́ча притека́ху к тебі́ ві́рнії в ско́рбіх і болі́зніх; і сих, біда́ми отягче́нних, не отри́нул єси́, істоча́я ціле́нія, да́руя утіше́ніє, предста́тельствуя в моли́твах. Ті́мже ісхожда́ше во всю зе́млю Россі́йськую віща́ніє чуде́с твої́х, і си́це тя сла́вляху духо́вная ча́да твоя́:","Ра́дуйся, па́стирю наш до́брий;","ра́дуйся, о́тче ми́лостивий і кро́ткий.","Ра́дуйся, врачу́ наш ско́рий і благода́тний;","ра́дуйся, не́мощей на́ших ціли́телю милосе́рдий.","Ра́дуйся, в біда́х і обстоя́ніїх помо́щниче ско́рий;","ра́дуйся, душ см'яте́нних умири́телю пресла́достний.","Ра́дуйся, гряду́щая я́ко настоя́щая прови́дівий;","ра́дуйся, прегріше́ній сокрове́нних обличи́телю прозорли́вий.","Ра́дуйся, преподо́бне Серафи́ме, Саро́вський чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до ви́дим на тебі́, преподо́бне: я́ко ста́рець сий немощни́й і притру́дний, ти́сящу дній і ти́сящу но́щий на ка́мені в моли́тві пребива́л єси́. Кто дово́лен ізрещи́ болі́зні і боре́нія твоя́, блаже́нне о́тче, я́же претерпі́л єси́, возді́я преподо́бнії ру́ці твої́ к Бо́гу, Амали́ка ми́сленнаго побіжда́я і Го́сподеві поя́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь єси́ жела́ніє, весь сла́дость, Сладча́йший Ісу́се! — та́ко в моли́твах взива́л єси́, о́тче, в пусти́ннім безмо́лвії твоє́м. Ми же, суєто́ю помраче́ннії і во грісі́х все житіє́ іжди́вшії, восхваля́юще любо́в твою́ ко Го́споду, си́це вопіє́м ті:","Ра́дуйся, лю́б'ящим і чту́щим тя хода́таю спасе́нія;","ра́дуйся, приводя́й грі́шников ко ісправле́нію.","Ра́дуйся, молча́льниче і затво́рниче преди́вний;","ра́дуйся, моли́твенниче о нас усе́рдний.","Ра́дуйся, пла́менную любо́в ко Го́споду показа́вий;","ра́дуйся, огне́м моли́тви стрі́ли вра́жія попали́вий.","Ра́дуйся, свіще́ неугаси́мая, моли́твою в пусти́ні пламені́ющая;","ра́дуйся, світи́льниче, горя́й і світя́й дарова́нії духо́вними.","Ра́дуйся, преподо́бне Серафи́ме, Саро́вський чудотво́рче."]},{"h":"Кондак 9","ps":["Все єстество́ а́нгельськоє удиви́ся стра́нному зрі́нію: ста́рцю бо, су́щу в затво́рі, Небесе́ і землі́ Цари́ця яви́ся, повеліва́ющи, да откри́єть затво́р свой і да не возбрани́ть лю́дем правосла́вним вни́ти к себі́, но да всіх пі́ти научи́ть Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії не возмо́гуть ізрещи́ крі́пость любве́ твоєя́, блаже́нне: пре́дал бо єси́ себе́ на служе́ніє всім приходя́щим к тебі́, повелі́ніє Богома́тере ісполня́я, і бил єси́ недоумева́ющим сові́тник благи́й, унива́ющим уті́шитель, заблужда́ющихся кро́ткоє вразумле́ніє, боля́щих врач і ціли́тель. Сего́ ра́ди вопіє́м ті:","Ра́дуйся, от ми́ра в пусти́ню всели́вийся, да доброді́телі приобря́щеши;","ра́дуйся, із пусти́ні во оби́тель возврати́вийся, во є́же доброді́телі сі́мена сі́яти.","Ра́дуйся, Ду́ха Свята́го благода́тію осія́нний;","ра́дуйся, кро́тосте і смире́нія іспо́лненний.","Ра́дуйся, притека́вшим к тебі́ оте́ць чадолюби́вий;","ра́дуйся, в словесі́х любве́ ободре́ніє і утіше́ніє їм подава́вий.","Ра́дуйся, приходя́щия к тебі́ ра́достію і сокро́вищем іменова́вий;","ра́дуйся, за любо́в твою́ святу́ю ра́достей Небе́снаго Ца́рствія сподо́бивийся.","Ра́дуйся, преподо́бне Серафи́ме, Саро́вський чудотво́рче."]},{"h":"Кондак 10","ps":["Спаси́тельнаго твоєго́ по́двига, преподо́бне, дости́г сконча́нія, на моли́тві колінопреклоне́нно святу́ю ду́шу твою́ в ру́ці Бо́жії пре́дал єси́, ю́же А́нгели святі́ї вознесо́ша Го́ре ко Престо́лу Вседержи́теля, да со всі́ми святи́ми предстої́ши во сла́ві невече́рней, воспіва́я піснь хвале́бную святи́х Святі́йшему Сло́ву: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ всім святи́м і і́ноком отра́да, Пресвята́я Ді́ва пред кончи́ною твоє́ю яви́ся ті, провозвісти́вши бли́зькоє твоє́ к Бо́гу отше́ствіє. Ми же, див'я́щеся таково́му посіще́нію Богома́тере, вопіє́м ті:","Ра́дуйся, Небесі́ і землі́ Цари́цю лицезрі́вий;","ра́дуйся, явле́нієм Бо́жия Ма́тере обра́дованний.","Ра́дуйся, вість от Нея́ преселе́нію Небе́сному приє́мий;","ра́дуйся, пра́ведною кончи́ною свя́тость житія́ твоєго́ показа́вий.","Ра́дуйся, в моли́тві пред іко́ною Богома́тере умиле́нний дух твой Бо́гу преда́вий;","ра́дуйся, неболі́зненним ісхо́дом прорече́нія твоя́ іспо́лнивий.","Ра́дуйся, вінце́м безсме́ртія от руки́ Вседержи́теля увінча́нний;","ра́дуйся, блаже́нство ра́йськоє со всі́ми святи́ми, унаслі́довавий.","Ра́дуйся, преподо́бне Серафи́ме, Саро́вський чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє непреста́нноє Пресвяті́й Тро́йце вознося́, преподо́бне, всім житіє́м твої́м подви́жник вели́кий благоче́стія яви́лся єси́, заблу́ждшим на вразумле́ніє, боля́щим душе́ю і ті́лом на ісціле́ніє. Ми же, благода́рні су́ще Го́сподеві за такову́ю ми́лость Єго́ к нам, ви́ну зове́м Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світопода́тельний світи́льник бив в житії́, богоблаже́нне о́тче, і по сме́рті твоє́й возсія́л єси́ я́ко світоза́рноє світи́ло Россі́йськия землі́: істоча́єши бо от честни́х моще́й твої́х то́ки чуде́с всім, с ві́рою і любо́вію к тебі́ притека́ющим. Ті́мже ми, я́ко моли́твеннику о нас те́плому і чудотво́рцю, вопіє́м ті:","Ра́дуйся, мно́жеством чуде́с от Го́спода просла́вленний;","ра́дуйся, любо́вію твоє́ю всему́ ми́ру возсія́вий.","Ра́дуйся, любве́ Христо́ви ві́рний послі́дователю;","ра́дуйся, утіше́ніє всім тре́бующим твоєя́ по́мощі.","Ра́дуйся, істо́чниче чуде́с неоскудіва́ємий;","ра́дуйся, боля́щих і неду́жних ісціли́телю.","Ра́дуйся, води́ многоціле́бния кла́дязю неісчерпа́ємий;","ра́дуйся, я́ко вся конці́ землі́ на́шея любо́вію твоє́ю об'я́л єси́.","Ра́дуйся, преподо́бне Серафи́ме, Саро́вський чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть і ве́ліє твоє́ дерзнове́ніє пред Бо́гом ві́дуще, тебі́, преподо́бне о́тче, мо́лимся: моли́ся те́плі ко Го́споду, да храни́ть Це́рков Свою́ Святу́ю от неві́рія і раско́ла, от бід і напа́стей, да поє́м тобо́ю благоді́ющему нам Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́ прославле́ніє, ублажа́єм тя, преподо́бне, я́ко многомо́щна моли́твенника о нас пред Го́сподом, уті́шителя і засту́пника, і с любо́вію возглаша́єм ті си́це:","Ра́дуйся, Це́ркве Правосла́вния похвало́;","ра́дуйся, Оте́честву на́шему щит і огражде́ніє.","Ра́дуйся, путеводи́телю, всіх к Небесі́ направля́яй;","ра́дуйся, защи́тниче наш і покрови́телю.","Ра́дуйся, си́лою Бо́жиєю мно́гая чудеса́ соді́явий;","ра́дуйся, ри́зою твоє́ю мно́гія неду́жния ісціли́вий.","Ра́дуйся, вся ко́зні дия́вольськия побіди́вий;","ра́дуйся, зві́ри ди́кия кро́тостію твоє́ю покори́вий.","Ра́дуйся, преподо́бне Серафи́ме, Саро́вський чудотво́рче."]},{"h":"Кондак 13","ps":["О преди́вний уго́дниче і вели́кий чудотво́рче, преподо́бне о́тче Серафи́ме, прийми́ ма́лоє сіє́ моле́ніє на́ше, в похвалу́ тебі́ возноси́моє, і, предстоя́ ни́ні Престо́лу Царя́ ца́рствующих, Го́спода на́шего Ісу́са Христа́, моли́ся о всіх нас, да обря́щем милосе́рдіє Єго́ в День Су́дний, в ра́дості пою́ще Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць ізбра́ тя ізнача́ла, да просла́виши житіє́м твої́м пречу́дноє і́м'я Святи́я Тро́йці: яви́лся бо єси́ воі́стину а́нгел на землі́ і во пло́ті серафи́м; я́ко луч пресві́тлий Ві́чнаго Со́лнця Пра́вди, просвіти́ся житіє́ твоє́. Ми же, зря́ще прехва́льния труди́ твоя́, с благогові́нієм і ра́достію глаго́лем ті сицева́я:","Ра́дуйся, пра́вило ві́ри і благоче́стія;","ра́дуйся, о́бразе кро́тости і смире́нія.","Ра́дуйся, пресла́вноє ві́рних велича́ніє;","ра́дуйся, прети́хоє ско́рбним утіше́ніє.","Ра́дуйся, прелюби́моє і́ноков похвале́ніє;","ра́дуйся, живу́щим в ми́рі преди́вноє поможе́ніє.","Ра́дуйся, Россі́йськия держа́ви сла́во і огражде́ніє;","ра́дуйся, тамбо́вськия страни́ свяще́нноє украше́ніє.","Ра́дуйся, преподо́бне Серафи́ме, Саро́вський чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і преди́вний уго́дниче Христо́в, ско́рий помо́щниче і моли́твенниче наш, преподо́бне о́тче Серафи́ме! Велича́юще просла́вльшаго тя Го́спода, воспіва́єм ті похва́льная. Ти же, імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, зову́щих:","Ра́дуйся, преподо́бне Серафи́ме, Саро́вський чудотво́рче."]},{"h":"Молитва","ps":["О пречу́дний о́тче Серафи́ме, вели́кий Саро́вський чудотво́рче, всім прибега́ющим к тебі́ скоропослу́шний помо́щниче! Во дні земна́го житія́ твоєго́ нікто́же от тебе́ тощ і неуті́шен оти́де, но всім в сла́дость бисть ви́дініє ли́ка твоєго́ і благоуві́тливий глас слове́с твої́х. К сим же і дар ісціле́ній, дар прозрі́нія, дар немощни́х душ врачева́нія оби́лен в тебі́ яви́ся. Єгда́ же призва́ тя Бог от земни́х трудо́в к небе́сному упокоє́нію, ніколи́же люби́ твоя́ преста́ от нас, і невозмо́жно єсть ісчи́слити чудеса́ твоя́, умно́жившаяся, я́ко зві́зди небе́сния: се бо по всім конце́м землі́ на́шея лю́дем Бо́жиїм явля́єшися і да́руєши їм ісціле́нія. Тім же і ми вопіє́м ті: о прети́хий і кро́ткий уго́дниче Бо́жий, дерзнове́нний к Нему́ моли́твенниче, ніколи́же призива́ющия тя отріва́яй! Вознеси́ о нас благомо́щную твою́ моли́тву ко Го́споду сил, да да́руєть нам вся благопотре́бная в жи́зні сей і вся к душе́вному спасе́нію поле́зная, да огради́ть нас от паде́ній гріхо́вних і і́стинному покая́нію да научи́ть нас, во є́же беспреткнове́нно вни́ти нам во ві́чноє Небе́сноє Ца́рство, іді́же ти ни́ні в незаходи́мій сія́єши сла́ві, і та́мо воспіва́ти со всі́ми святи́ми Живонача́льную Тро́йцю во ві́ки віко́в. Амі́нь."]},{"h":"Тропар на преставлення, глас 4","ps":["От ю́ности Христа́ возлюби́л єси́, блаже́нне, / і Тому́ Єди́ному рабо́тати пла́менні вожделі́в, / непреста́нною моли́твою і трудо́м в пусти́ні подвиза́лся єси́, / умиле́нним же се́рдцем любо́в Христо́ву стяжа́в, / ізбра́нник возлю́блен Бо́жия Ма́тере яви́лся єси́. / Сего́ ра́ди вопіє́м ті: // спаса́й нас моли́твами твої́ми, Серафи́ме, преподо́бне о́тче наш."]},{"h":"Інший тропар на прославлення, глас 4","ps":["От ю́ности Христа́ возлюби́л єси́, преподо́бне, / і Тому́ Єди́ному порабо́тати пла́менні вожделі́л єси́, / в пу́стиннім житії́ твоє́м непреста́нною моли́твою і трудо́м подвиза́лся єси́, / умиле́нним се́рдцем любо́в Христо́ву стяжа́в, / Небе́сним Серафи́мом в пісносло́вії спобо́рниче, / в любві́ притека́ющим к тебі́ Христу́ подража́телю, / ті́мже ізбра́нник возлю́блен Бо́жия Ма́тере яви́лся єси́, / сего́ ра́ди вопіє́м ті: / спаса́й нас моли́твами твої́ми, ра́досте на́ша, / те́плий пред Бо́гом засту́пниче, // Серафи́ме блаже́нне."]},{"h":"Кондак, глас 2","ps":["Ми́ра красоту́ і я́же в нем тлі́нная оста́вив, преподо́бне, / в Саро́вськую оби́тель всели́лся єси́, / і та́мо а́нгельськи пожи́в, / мно́гим путь бил єси́ ко спасе́нію, / сего́ ра́ди і Христо́с тебі́, о́тче Серафи́ме, просла́ви / і да́ром ісціле́ній і чуде́с обогати́. / Ті́мже вопіє́м ті: // ра́дуйся, Серафи́ме, преподо́бне о́тче наш."]},{"h":"Величання","ps":["Ублажа́єм тя, преподо́бне о́тче Серафи́ме, і чтим святу́ю па́м'ять твою́, наста́вниче мона́хов і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст святому праведному Іоанну, пресвітеру Кронштадтському, чудотворцю","e":"Akathist to the Holy Righteous John, Priest of Kronstadt, the Wonderworker","secs":[{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче і пресла́вний чудотво́рче, о́тче пра́ведний Іоа́нне, гра́да Кроншта́дта пресла́вноє украше́ніє! Ти, от младе́нства Христу́ послі́дуя, сорасп'я́тися Єму́ возжелі́л єси́ і, жизнь твою́ в Нем утверди́в, дар чуде́с от Бо́га прия́л єси́ і сло́вом живоно́сним всіх напита́л єси́. Ми же, недосто́йнії, благода́рні вопіє́м ті:","Ра́дуйся, Іоа́нне, землі́ Россі́йськия моли́твенниче преди́вний."]},{"h":"Ікос 1","ps":["А́нгела сві́тла, єще́ о́трок сий, я́ві узрі́л єси́, о́тче Іоа́нне, і́же і рече́ ті, я́ко повелі́нієм Госпо́днім приста́влен храни́ти тя во всіх путеіх твої́х. Ті́мже я́ко ізбра́нника Бо́жия ві́дуще тя, взива́єм си́це:","Ра́дуйся, благода́ті Бо́жия сосу́де ізбра́нний;","ра́дуйся, сло́вом Бо́жиїм ізмла́да наста́вленний.","Ра́дуйся, во о́трочестві явле́нія А́нгела Храни́теля сподо́бивийся;","ра́дуйся, от ю́ности води́тельству Ду́ха Свята́го преда́вийся.","Ра́дуйся, роди́телей боголюби́вих благоче́стіє восприє́мий;","ра́дуйся, цілому́дрієм і чистото́ю себі́ огради́вий.","Ра́дуйся, духо́вним наста́вником твої́м всім се́рдцем внима́вий;","ра́дуйся, почита́нієм роди́телей благоволе́ніє Бо́жиє стяжа́вий.","Ра́дуйся, Іоа́нне, землі́ Россі́йськия моли́твенниче преди́вний."]},{"h":"Кондак 2","ps":["Прови́дя, богоно́сне о́тче Іоа́нне, я́ко мно́гия біди́ і собла́зни гряду́ть на Це́рков Ру́ськую і ча́да Бо́жия гони́ма бу́дуть, увіща́л єси́ лю́ди, глаго́ля: пока́йтеся, сто́йте во ві́рі Правосла́вній, кріпі́теся і сла́віте Го́спода, взива́юще Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом Боже́ственним наставля́єм, всеблаже́нне о́тче Іоа́нне, сві́том і́стиннаго Богопозна́нія всіх, приходя́щих к тебі́, просвіща́л єси́. Ми же, писа́ньми твої́ми науча́ємі, вопіє́м ті такова́я:","Ра́дуйся, єва́нгельськия І́стини пла́менний служи́телю;","ра́дуйся, глаго́лов жи́зні ві́чния немо́лчний возвісти́телю.","Ра́дуйся, пра́ведним житіє́м твої́м Бо́гу угоди́вий;","ра́дуйся, Це́рков Бо́жию писа́нії твої́ми просла́вивий.","Ра́дуйся, Крест Христо́в пред очи́ма твої́ма ви́ну созерца́вий;","ра́дуйся, сорасп'я́тися Христу́ вседу́шні возжела́вий.","Ра́дуйся, Бо́га і бли́жніх всім се́рдцем возлюби́вий;","ра́дуйся, лю́дем, в ско́рбіх і печа́ліх су́щим, утіше́ніє подава́вий.","Ра́дуйся, Іоа́нне, землі́ Россі́йськия моли́твенниче преди́вний."]},{"h":"Кондак 3","ps":["Си́лою Боже́ственния благода́ті, я́ко світи́льник многосві́тлий Правосла́вния Це́ркве, во гра́ді Кроншта́дте просія́л єси́, пра́ведне Іоа́нне, і лю́ди, во тьмі гріхо́вній сідя́щия і собла́зном богобо́рчества смуща́ємия, просвіти́в, наставля́л єси́ пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я любо́в па́стирськую, пра́ведне о́тче Іоа́нне, поте́кл єси́ к лю́дем, не іму́щим кро́ва і хлі́ба насу́щнаго і во отча́янії погиба́ющим, і сих любо́вію і милосе́рдієм Христу́ приобрі́л єси́. Ми же благода́рні взива́єм ті си́це:","Ра́дуйся, в хра́мі Бо́жиї дерзнове́нний о лю́діх моли́твенниче;","ра́дуйся, си́рим і вдови́цям ми́лостивий помо́щниче.","Ра́дуйся, окамене́нния се́рдцем к покая́нію побужда́яй;","ра́дуйся, неве́дущия Бо́га Боже́ственною прему́дростію просвіща́яй.","Ра́дуйся, стропо́тних і злонра́вних ти́хоє ісправле́ніє;","ра́дуйся, ліни́вих і малове́рних ре́вностноє обличе́ніє.","Ра́дуйся, Ца́рствія Бо́жия і пра́вди єго́ пропові́дниче неустраши́мий;","ра́дуйся, проти́ву ко́зней духо́в зло́би поднебе́сних воі́телю неуста́нний.","Ра́дуйся, Іоа́нне, землі́ Россі́йськия моли́твенниче преди́вний."]},{"h":"Кондак 4","ps":["Бу́рю злоче́стія, воздвиза́єму на Це́рков на́шу святу́ю, прови́дя, о́тче Іоа́нне, я́ко ві́рний страж до́му Госпо́дня, поуча́л єси́ ча́да Бо́жия бді́ти, во і́стинній ві́рі пра́во ходи́ти і в за́повідіх Госпо́дніх непоро́чно пребива́ти, да спасе́ть Госпо́дь лю́ди Своя́, в покая́нії Єму́ зову́щия: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще лю́діє Бо́жії, я́ко ти єси́, о́тче Іоа́нне, сосу́д ізбра́нний і благода́тних даро́в преіспо́лненний, не то́кмо от Кроншта́дта, но і от всіх конце́в землі́ к тебі́ притека́ху, я́ко да ісціле́нія і по́мощ улуча́ть. С ни́ми же і ми, я́ко хода́таю пред Бо́гом те́плу, уми́льно зове́м ті:","Ра́дуйся, сі́ятелю пра́вди, а́лчущия жи́зні ві́чния напита́вий;","ра́дуйся, обличи́телю непра́вди, ві́рния от пре́лести гріхо́вния огражда́вий.","Ра́дуйся, заблу́ждшим і неразу́мним путь к Бо́гу указу́яй;","ра́дуйся, писа́ньми твої́ми ча́да Бо́жия наставля́яй.","Ра́дуйся, скорб'я́щих і обремене́нних при́сноє упова́ніє;","ра́дуйся, боля́щих і стра́ждущих благода́тноє врачева́ніє.","Ра́дуйся, сосу́де ізбра́нний, да́ри Ду́ха Свята́го ди́вно украше́нний;","ра́дуйся, світи́льниче всесві́тлий, на сві́щниці церко́внім Бо́гом поста́вленний.","Ра́дуйся, Іоа́нне, землі́ Россі́йськия моли́твенниче преди́вний."]},{"h":"Кондак 5","ps":["Я́ко звізда́ многосві́тлая, священноле́пним житіє́м твої́м просія́л єси́, па́стирю Христо́в Іоа́нне! Ти бо ста́до, Бо́гом вруче́нноє тебі́, от волко́в, губ'я́щих є, огражда́л єси́, взива́я: пока́йтеся і жи́ви бу́дете, отимі́те лука́вство от душ ва́ших, да чи́стим се́рдцем Бо́га у́зріте і воспоє́те Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ві́дая мно́жество люде́й, утіше́нія ча́ющих, я́ко апо́стол Христо́в, обходи́л єси́ гра́ди і ве́сі Россі́йськия, чудотво́рче ізя́щні, сі́я сло́во Бо́жиє, ісціля́я неду́жния і малові́рния ісправля́я, бив всім вся, да вся́ко ні́кия спасе́ши. Ми же болі́зні і труди́ твоя́ почита́юще, вопіє́м ті си́це:","Ра́дуйся, я́ко си́лою благода́ті немощни́я укріпля́л єси́;","ра́дуйся, я́ко моли́твами твої́ми грі́шния к покая́нію приводи́л єси́.","Ра́дуйся, а́лчущия і жа́ждущия по за́повіді Госпо́дні насища́вий;","ра́дуйся, благові́стієм Христо́вим лю́ди к пра́вді Бо́жієй приводи́вий.","Ра́дуйся, моли́твами твої́ми малові́рния во ві́рі укрепля́вий;","ра́дуйся, си́лою Бо́жиєю немощни́м здра́віє подава́вий.","Ра́дуйся, зе́млю на́шу благогові́йно с про́повідію обходи́вий;","ра́дуйся, мир сей, я́ко прему́дроє творе́ніє Бо́жиє, воспева́вий.","Ра́дуйся, Іоа́нне, землі́ Россі́йськия моли́твенниче преди́вний."]},{"h":"Кондак 6","ps":["Пропові́дници чу́дних дія́ній твої́х, блаже́нне Іоа́нне, яви́шася мно́зі: бога́тії і ни́щії, ста́рці і ю́ноши, ти бо всім любо́в твою́ ізлива́л єси́ бога́тно. Ті́мже не то́кмо правосла́внії, но і інові́рнії си́лою моли́тв твої́х ми́лость Бо́жию обріта́ху, пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ житіє́м твої́м в Це́ркві Правосла́вній па́че сія́нія сі́вернаго, блаже́нне Іоа́нне, путь пра́вий лю́дем указу́я. Ті́мже моли́ Го́спода Сил, да любо́в свята́я утверди́ться в сердця́х на́ших, да ні скорб, ні тіснота́, ні смерть, ні бла́га ми́ра сего́ возмо́гуть разлучи́ти нас от любве́ Бо́жия, благода́рні тебі́ вопію́щих:","Ра́дуйся, ві́ру Правосла́вную в чистоті́ храни́ти завеща́вий;","ра́дуйся, ті́сним путе́м за́повідей Христо́вих ходи́ти поуча́вий.","Ра́дуйся, в ско́рбіх і печа́ліх су́щим ра́дость подава́вий;","ра́дуйся, к і́стинному покая́нію грі́шники призива́вий.","Ра́дуйся, Бо́жиїм смотре́нієм гряду́щая нам возвеща́вий;","ра́дуйся, от сіте́й вра́жиїх оте́чество на́ше огражда́вий.","Ра́дуйся, мир с Бо́гом свя́то храни́ти запові́давий;","ра́дуйся, сло́вом і́стини і любо́вію ві́рним лю́дем послужи́вий.","Ра́дуйся, Іоа́нне, землі́ Россі́йськия моли́твенниче преди́вний."]},{"h":"Кондак 7","ps":["Хотя́ Всеблаги́й Госпо́дь спасти́ лю́ди землі́ на́шея і угото́вати я к же́ртвенному служе́нію, іспо́лни тя, всеблаже́нне Іоа́нне, ду́ха проро́чества, прему́дрості і ра́зума, я́ко да, сло́вом твої́м наста́влени, во дні гряду́щих іспита́ній непоколеби́мо вопію́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго ізбра́нника Бо́жия, всеблаже́нне Іоа́нне, ві́дуще тя боголюби́вії лю́діє, на всяк день Же́ртву безкро́вную принося́ща і со дерзнове́нієм за всіх Христу́ моля́щася, с ві́рою к тебі́ притека́ху і ісціля́хуся. Ті́мже і ми, іспо́лненнії твої́х благодія́ній, с любо́вію воспіва́єм ті сицева́я:","Ра́дуйся, у Престо́ла Бо́жия приле́жний о нас моли́твенниче;","ра́дуйся, і́стиннаго покая́нія усе́рдний пропові́дниче.","Ра́дуйся, я́ко нелі́ностно рабо́тати Христу́ Бо́гу нас наставля́єши;","ра́дуйся, я́ко стоя́ти на боже́ственній стра́жі нас призива́єши.","Ра́дуйся, о́браз воздержа́нія і цілому́дрія ві́рним яви́вий;","ра́дуйся, па́ству твою́ от єресе́й і раско́ла му́дре защити́вий.","Ра́дуйся, су́щих во тьмі неві́дінія ре́вностний просвіти́телю;","ра́дуйся, душ челові́чеських от суєти́ жите́йськія ди́вний огради́телю.","Ра́дуйся, Іоа́нне, землі́ Россі́йськия моли́твенниче преди́вний."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до ви́дим, явле́нноє тебі́, преди́вний па́стирю Христо́в Іоа́нне! Тя бо і лю́ди ві́рния Сама́ Пречи́стая Ма́ти Бо́жия я́ко миле́йшая ча́да Отця́ Небе́снаго нарече́. Сего́ ра́ди ми, си́ми словеси́ утіша́ємі, вопіє́м Царю́ віко́в: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь жела́нієм Боже́ственним распаля́єм, любве́ Христо́ви преіспо́лнился єси́, па́стирю до́брий! Ми же, неради́вії, сокро́вищ єя́ не стяжа́вше, мно́гих скорбе́й і печа́лей досто́йні яви́хомся. Оба́че, ві́дуще тя помо́щника неуси́пна, со упова́нієм взива́єм ті си́це:","Ра́дуйся, любве́ Христо́ви сосу́де ізбра́нний;","ра́дуйся, явле́нія Бо́жия Ма́тере удосто́єнний.","Ра́дуйся, Це́ркве Христо́ви неугаса́ющий світи́льниче;","ра́дуйся, о всем ми́рі хода́таю і печа́льниче.","Ра́дуйся, ми́ра і пра́вди Бо́жия ревни́телю;","ра́дуйся, благоче́стія і добронра́вія насади́телю.","Ра́дуйся, Россі́йськия Це́ркве похвало́ і украше́ніє;","ра́дуйся, землі́ на́шея благода́тноє утвержде́ніє.","Ра́дуйся, Іоа́нне, землі́ Россі́йськия моли́твенниче преди́вний."]},{"h":"Кондак 9","ps":["Всім лю́дем, в неві́дінії, ско́рбіх і печа́ліх су́щим, воздви́же тя Госпо́дь па́стиря і чудотво́рця преди́вна, о́тче Іоа́нне, є́же грі́шния на путь пра́вий наста́вити, неві́рния к Бо́гу обрати́ти і боля́щия ісціли́ти, да согла́сно воспою́ть всі спаси́тельную піснь: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́ї многовеща́нії безгла́сни би́ша о благода́ті, да́нній тебі́, Іоа́нне преди́вне, єгда́ сло́вом єди́нім лю́ди от гріха́ к покая́нію приводи́л єси́, неду́жния от одра́ болі́зні воздвиза́л єси́, бі́си ізгоня́л єси́. Ми же я́ко чудотво́рця і уго́дника Бо́жия прославля́єм тя си́це:","Ра́дуйся, страстьми́ одержи́мих ди́вний врачева́телю;","ра́дуйся, в долгонеду́жії су́щих безме́здний ціли́телю.","Ра́дуйся, отпа́дшия к Бо́гу приводи́вий;","ра́дуйся, безбо́жния гро́зно облича́вий.","Ра́дуйся, ка́ющихся кро́ткий наказа́телю;","ра́дуйся, ми́лостині ще́дрий пода́телю.","Ра́дуйся, христия́нськаго просвіще́нія і благоче́стія ре́вностний насади́телю;","ра́дуйся, ю́них по стезя́м пра́вди му́дрий путеводи́телю.","Ра́дуйся, Іоа́нне, землі́ Россі́йськия моли́твенниче преди́вний."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ лю́ди Россі́йськия, єресьми́ і неві́рієм соблазня́ємия, о́тче Іоа́нне, ко́зні бісо́вськия обличи́л єси́ і правосла́вноє іспові́даніє ві́ри тве́рдо яви́л єси́. Сего́ ра́ди Ца́рствія Небе́снаго дости́гл єси́, іді́же со А́нгели і ли́ки святи́х непреста́нно о нас мо́лиши Бо́га і поє́ши Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ тве́рда яви́лся єси́ лю́дем стра́ждущим, от всіх конце́в землі́ Россі́йськия к тебі́ приходя́щим, богоно́сне о́тче Іоа́нне. Ті́мже і нас, бі́дствующих і немощству́ющих душе́ю і ті́лом, укріпи́ моли́твами твої́ми, і́миже огражда́єми, прино́сим ті похвали́ сія́:","Ра́дуйся, світи́льниче неугаси́мий, огне́м Ду́ха Свята́го возжже́нний;","ра́дуйся, кри́не благоуха́яй, росо́ю благода́ті Бо́жия напоє́нний.","Ра́дуйся, лозо́ многопло́дная, благода́тними да́ри ві́рних пита́ющая;","ра́дуйся со́ле землі́, от гріхо́внаго тлі́нія нас сохраня́ющая.","Ра́дуйся, в мо́рі жите́йстім обурева́ємим ти́хоє приста́нище;","ра́дуйся, душе́вні і тіле́сні ізнемога́ющим благо́є вспоможе́ніє.","Ра́дуйся, сердцеві́дче прему́дрий, ві́рния лю́ди от мудрова́нія ми́ра сего́ огражда́яй;","ра́дуйся, сі́ятелю Христо́в, сі́янієм єва́нгельським сердца́ мно́гих увеселя́яй.","Ра́дуйся, Іоа́нне, землі́ Россі́йськия моли́твенниче преди́вний."]},{"h":"Кондак 11","ps":["Піснь достохва́льную прино́сим ті, о́тче Іоа́нне, всім житіє́м твої́м Бо́га просла́вльшему. І я́коже на землі́ за всіх і за вся Влади́ку ми́ра умоля́л єси́, си́це і ни́ні на Небесі́ вознеси́ моли́тви твоя́, да во оте́чествії на́шем при́сно воспіва́ється Бо́гу побі́дная піснь: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рную свіщу́ ві́ми тя, Бо́гом ізбра́нне о́тче Іоа́нне, ти бо і по отше́ствії от земни́х к Небе́сним у Престо́ла Бо́жия в со́нмі святи́х і Сил а́нгельських о нас при́сно хода́тайствуєши. Сего́ ра́ди благода́рственно взива́єм ті си́це:","Ра́дуйся, я́ко в по́двизі твоє́м І́м'я Пресвяти́я Тро́йці ди́вно просла́вися;","ра́дуйся, я́ко благоче́стієм і ві́рою твоє́ю Це́рков Христо́ва украси́ся.","Ра́дуйся, па́стирей богому́дрий наста́вниче;","ра́дуйся, і́нокинь до́брий учи́телю.","Ра́дуйся, супру́ги соу́з бра́чний свя́то храни́ти поуча́вий;","ра́дуйся, ча́да почита́ти роди́телі своя́ увещава́вий.","Ра́дуйся, я́ко сострада́нієм твої́м к бли́жнім ско́рби і печа́лі утоля́ються;","ра́дуйся, я́ко моли́твами твої́ми грі́шници на путь спасе́нія обраща́ються.","Ра́дуйся, Іоа́нне, землі́ Россі́йськия моли́твенниче преди́вний."]},{"h":"Кондак 12","ps":["Благода́тних даро́в Ду́ха Свята́го іспо́лни тя Госпо́дь, о́тче наш Іоа́нне, і́миже ре́вностно послужи́л єси́ наро́ду Бо́жию. Вознеси́ моли́тву к Бо́гу і о нас, да ві́ри, наде́жди і любве́ дости́гше, прича́стници жи́зні во Христі́ бу́дем і сподо́бимся воспіва́ти благода́рственную піснь: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́ достохва́льноє житіє́ на землі́ і сла́ву, ю́же стяжа́л єси́ на Небесі́, о́тче Іоа́нне, притека́єм во оби́тель тобо́ю созда́нную і припа́даєм ко гробни́ці твоє́й, от нея́же ісціле́нія і по́мощ улуча́юще, возглаша́єм ті сицева́я:","Ра́дуйся, пропові́дниче ізря́дний, проро́ком і апо́столом до́брі поревнова́вий;","ра́дуйся, па́стирю землі́ Россі́йськия, Бо́гом ізбра́нний і просла́вленний.","Ра́дуйся, оби́тель преподо́бнаго покрови́теля твоєго́ Іоа́нна Ри́льськаго ди́вно устро́ївий;","ра́дуйся, оби́телію се́ю град свята́го Петра́ сла́вно украси́вий.","Ра́дуйся, во возсозда́нную оби́тель і́нокини собира́яй;","Ра́дуйся, я́ко оте́ць чадолюби́вий, при́сноє попече́ніє о них імі́яй.","Ра́дуйся, всім притека́ющим к тебі́ ско́роє вспоможе́ніє подава́яй;","ра́дуйся, о́браз до́браго па́стиря сло́вом, житіє́м і ві́рою нам яви́вий.","Ра́дуйся, Іоа́нне, землі́ Россі́йськия моли́твенниче преди́вний."]},{"h":"Кондак 13","ps":["О святи́й пра́ведний о́тче Іоа́нне, всероссі́йський світи́льниче і преди́вний чудотво́рче! Прийми́ хвале́бноє сіє́ пі́ніє на́ше і умоли́ Христа́ Бо́га Це́рков Святу́ю в благоче́стії утверди́ти, єди́нство в сою́зі ми́ра і любве́ Христо́ви соблюсти́, да і ми воспоє́м с тобо́ю Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела сві́тла, єще́ о́трок сий, я́ві узрі́л єси́, о́тче Іоа́нне, і́же і рече́ ті, я́ко повелі́нієм Госпо́днім приста́влен храни́ти тя во всіх путеіх твої́х. Ті́мже я́ко ізбра́нника Бо́жия ві́дуще тя, взива́єм си́це:","Ра́дуйся, благода́ті Бо́жия сосу́де ізбра́нний;","ра́дуйся, сло́вом Бо́жиїм ізмла́да наста́вленний.","Ра́дуйся, во о́трочестві явле́нія А́нгела Храни́теля сподо́бивийся;","ра́дуйся, от ю́ности води́тельству Ду́ха Свята́го преда́вийся.","Ра́дуйся, роди́телей боголюби́вих благоче́стіє восприє́мий;","ра́дуйся, цілому́дрієм і чистото́ю себі́ огради́вий.","Ра́дуйся, духо́вним наста́вником твої́м всім се́рдцем внима́вий;","ра́дуйся, почита́нієм роди́телей благоволе́ніє Бо́жиє стяжа́вий.","Ра́дуйся, Іоа́нне, землі́ Россі́йськия моли́твенниче преди́вний."]},{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче і пресла́вний чудотво́рче, о́тче пра́ведний Іоа́нне, гра́да Кроншта́дта пресла́вноє украше́ніє! Ти, от младе́нства Христу́ послі́дуя, сорасп'я́тися Єму́ возжелі́л єси́ і, жизнь твою́ в Нем утверди́в, дар чуде́с от Бо́га прия́л єси́ і сло́вом живоно́сним всіх напита́л єси́. Ми же, недосто́йнії, благода́рні вопіє́м ті:","Ра́дуйся, Іоа́нне, землі́ Россі́йськия моли́твенниче преди́вний."]},{"h":"Молитва","ps":["О вели́кий чудотво́рче і преди́вний уго́дниче Бо́жий, богоно́сне о́тче Іоа́нне! При́зри на нас і внемли́ благосе́рдно моле́нію на́шему, я́ко вели́ких дарова́ній сподо́би тя Госпо́дь, да хода́тай і при́сний моли́твенник за нас бу́деши. Се бо, страстьми́ гріхо́вними обурева́ємі і зло́бою сніда́єми, за́повіді Бо́жия пренебрего́хом, покая́нія серде́чнаго і слез воздиха́нія не принесо́хом, сего́ ра́ди мно́гим ско́рбем і печа́лем досто́йні яви́хомся. Ти же, о́тче пра́ведне, ве́ліє дерзнове́ніє ко Го́споду і сострада́ніє к бли́жнім свої́м імі́я, умоли́ Всеще́драго Влади́ку ми́ра, да проба́вить ми́лость Свою́ на нас і потерпи́ть непра́вдам на́шим, не погуби́ть нас гріх ра́ди на́ших, но вре́м'я на покая́ніє ми́лостивно нам да́руєть. О свя́тче Бо́жий, помози́ нам ві́ру правосла́вную непоро́чно соблюсти́ і за́повіді Бо́жия благоче́стно сохрани́ти, да не облада́єть на́ми вся́коє беззако́ніє, ніже́ посрами́ться пра́вда Бо́жія в непра́вдах на́ших, но да сподо́бимся дости́гнути кончи́ни христия́нськия, безболе́зненния, непости́дния, ми́рния і Та́їн Бо́жиїх прича́стния. Єще́ мо́лим тя, о́тче пра́ведне, о є́же Це́ркві на́шей Святі́й до сконча́нія ві́ка утвержде́нней би́ти, Оте́честву же на́шему мир і пребива́ніє в пра́вді Бо́жієй іспроси́ і от всіх зол сохрани́, да та́ко наро́ди на́ші, Бо́гом храни́мі, в єдиноми́слії ві́ри і во вся́ком благоче́стії і чистоті́, в лі́поті духо́внаго бра́тства, трезве́нії і согла́сії свиді́тельствують: я́ко с на́ми Бог! В Не́мже живе́м, і дви́жемся, і єсьми́, і пребу́дем во ві́ки. Амі́нь."]},{"h":"Молитва","ps":["О святи́й пра́ведний о́тче Іоа́нне, всероссі́йський світи́льниче і преди́вний чудотво́рче! Ти от младе́нчеських літ Бо́гом ізбра́н бил єси́ і, ду́хом пламені́я, я́ко і́стинний па́стир, житіє́м, сло́вом, любо́вію, ві́рою, чистото́ю лю́дем послужи́л єси́. Сего́ ра́ди мо́лим тя, пра́ведний о́тче: моли́ Человіколю́бця Бо́га Це́рков Святу́ю ми́ром і тишино́ю огради́ти, зе́млю Россі́йськую во благоде́нствії сохрани́ти, па́стирі благода́ті і і́стини преізоби́льно іспо́лнити, вла́сті умудри́ти, правосла́вноє во́їнство укріпи́ти, немощни́я ісціли́ти, развраще́нния іспра́вити, ю́ния воспита́ти, ста́рці і вдови́ці уті́шити і нам всім во Ца́рствії Небе́снім сподо́битися со всі́ми святи́ми прославля́ти Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Правосла́вния ві́ри побо́рниче, / землі́ Россі́йськия печа́льниче, / па́стирем пра́вило і о́бразе ві́рним, / покая́нія і жи́зні во Христі́ пропові́дниче, / Боже́ственних Та́їн благогові́йний служи́телю / і дерзнове́нний о лю́діх моли́твенниче, / о́тче пра́ведний Іоа́нне, / ціли́телю і преди́вний чудотво́рче, / гра́ду Кроншта́дту похвало́ / і Це́ркві на́шея украше́ніє, / моли́ всеблага́го Бо́га // умири́ти мир і спасти́ ду́ші на́ша."]},{"h":"Інший тропар, глас 4","ps":["Россі́йськия землі́ па́стир до́брий показа́лся єси́, / в служе́нії пресви́терстім жизнь во Христі́ стяжа́в, богому́дре о́тче Іоа́нне. / Благода́ть ізоби́льную от Влади́ки Христа́ прия́л єси́: / неду́ги отгоня́ти, / малоду́шния утіша́ти, / в Та́йні Пречи́стаго Ті́ла і Кро́ве ві́рния со Христо́м соєдиня́ти. / Сего́ ра́ди восхваля́єм тя, // я́ко моли́твенника о душа́х на́ших."]},{"h":"Інший тропар, глас 4","ps":["Со апо́столи ізи́де віща́ніє твоє́ в конці́ вселе́нния, / с іспові́дники стра́данія за Христа́ претерпі́л єси́, / святи́телем уподо́бился єси́ Сло́ва пропові́данієм, / с преподо́бними во благода́ті Бо́жієй просія́л єси́. / Сего́ ра́ди вознесе́ Госпо́дь бе́здну смире́нія твоєго́ преви́ше небе́с, / і дарова́ нам і́м'я твоє́ во істо́чник преди́вних чуде́с. / Ті́мже во Христі́ во ві́ки живи́й, чудотво́рче, / любо́вію ми́луй су́щия в біда́х, / сли́ши ча́да твоя́, ві́рою тя призива́ющия, / Іоа́нне пра́ведне, // возлю́бленний па́стирю наш."]},{"h":"Кондак, глас 3","ps":["Днесь па́стир Кроншта́дтський / предстої́ть Престо́лу Бо́жию / і усе́рдно мо́лить о ві́рних / Христа́ Пастиренача́льника, / обітова́ніє да́вшаго: / сози́жду Це́рков Мою́ / і врата́ а́дова // не одолі́ють єй."]},{"h":"Інший кондак, глас 6","ps":["Пропові́дником і́стини, богоно́сним отце́м подра́жая, / всего́ себе́ на служе́ніє Бо́гу і бли́жнім вдал єси́, / і сан свяще́нства нося́, поко́я не ві́дал єси́, / слу́жби Бо́жія в хра́мі при́сно соверша́я, / і в домі́х ві́рних моле́бния пі́нія воспіва́я, / нужда́ющимся ще́дро благотворя́, / та́ко найменова́ніє благотво́рця і безсре́бренника стяжа́л єси́, Іоа́нне. / Ті́мже і по успе́нії твоє́м россі́йськия лю́діє прославля́ють і́м'я твоє́, / і ві́чную па́м'ять тебі́ возглаша́юще, // пою́ть Бо́гу: аллилу́я."]},{"h":"Величання","ps":["Велича́єм тя, святи́й пра́ведний о́тче Іоа́нне, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святому великомученику і цілителю Пантелеймону","e":"Akathist to the Holy Great Martyr and Healer Panteleimon","secs":[{"h":"Кондак 1","ps":["Ізбра́нний страстоте́рпче Христо́в і врачу́ благода́тний, ту́не подая́й неду́гующим ісціле́нія, пі́сньми восхваля́єм тя, засту́пника на́шего. Ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, от вся́ких бід і болі́зней свобожда́й нас, любо́вію тебі́ зову́щих:","Ра́дуйся, великому́чениче і ціли́телю Пантелеї́моне."]},{"h":"Ікос 1","ps":["А́нгела земна́го і небе́снаго челові́ка ві́ми тя, сла́вний Пантелеї́моне: а́нгельською бо непоро́чностію і му́ченичеством укра́шен, пресели́лся єси́ от землі́ на Не́бо, іді́же со А́нгели і всі́ми святи́ми предстоя́ Престо́лу Го́спода сла́ви, моли́ся о нас, земни́х, почита́ющих тя зва́нії си́ми:","Ра́дуйся, сві́тлосте благоче́стія;","ра́дуйся, пресла́вний світи́льниче Це́ркве.","Ра́дуйся, му́чеников пречестни́х украше́ніє;","ра́дуйся, ві́рних в непоколеби́мом терпі́нії утвержде́ніє.","Ра́дуйся, ю́ности преізря́дная похвало́;","ра́дуйся, побо́рниче Христо́в, в му́жестві неодолі́нний.","Ра́дуйся, проізра́стший в ми́рі, преми́рен яви́вийся;","ра́дуйся, а́нгеле во пло́ті, превосходя́й сме́ртних.","Ра́дуйся, небожи́телю всеблаже́нний;","ра́дуйся, Боже́ственнаго ра́зума вмісти́лище.","Ра́дуйся, і́мже ві́ра возви́сися;","ра́дуйся, і́мже пре́лесть низложи́ся.","Ра́дуйся, великому́чениче і ціли́телю Пантелеї́моне."]},{"h":"Кондак 2","ps":["Ви́дя тя Влади́ка сосу́д ізбра́н, возлюби́ ду́ші твоє́й добро́ту. Ти бо земну́ю вся́кую сла́дость і сла́ву презрі́в, вінце́м му́ченичеським возжелі́л єси́ украси́тися, уя́звлен Боже́ственною любо́вію, і вдохнове́нно поя́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум богодухнове́н імі́я, о до́блій воі́телю Пантелеї́моне, ізуми́л єси́ царя́ Максимія́на му́жеством ду́ші твоєя́ і словеси́, і́миже дерзнове́нно пропові́дал єси́ Христа́. Ті́мже похваля́юще дерзнове́ніє твоє́, глаго́лем ті си́це:","Ра́дуйся, угро́зи Максимія́на презрі́вий;","ра́дуйся, сові́том нечести́вих не покори́вийся.","Ра́дуйся, насажде́ніє і́стиннаго богопочита́нія;","ра́дуйся, іскорене́ніє де́монського служе́нія.","Ра́дуйся, неі́стовства мучи́телей ізобличи́телю;","ра́дуйся, і́дольськия пре́лести низложи́телю.","Ра́дуйся, разгна́вий нечести́вих собо́рища;","ра́дуйся, преміни́вий тлі́нная на небе́сная.","Ра́дуйся, собесі́дниче невеще́ственних А́нгелов;","ра́дуйся, сликовствова́телю многострада́льних святи́х.","Ра́дуйся, і́мже сатана́ посрами́ся;","ра́дуйся, і́мже Христо́с просла́вися.","Ра́дуйся, великому́чениче і ціли́телю Пантелеї́моне."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго, дарова́нною тебі́, і крі́пким терпі́нієм твої́м обезси́лил єси́ мучи́телеву де́рзость, му́жественний побідоно́сче: огня́, звіре́й, колеса́ не убоя́вся і мече́м усіче́н во главу́, віне́ць побі́ди прия́л єси́ от Христа́ Бо́га, взива́я Єму́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи оби́тель твоя́ вседрагу́ю главу́ твою́, богому́дрий страстоте́рпче, я́ко превели́коє сокро́вище, ра́дости ісполня́ється о сем і, любо́вію воспіва́ющи да́нную тебі́ от Бо́га благода́ть ісціле́ній, благода́рно зове́ть ті:","Ра́дуйся, Никомиді́ї світи́льниче всесві́тлий;","ра́дуйся, чту́щей тя оби́телі стра́же неуси́пний.","Ра́дуйся, і́мже охладе́ безбо́жіє;","ра́дуйся, і́мже возрасте́ богопозна́ніє.","Ра́дуйся, сві́тлая страстоте́рпцев сла́во;","ра́дуйся, ра́достноє правосла́вних сли́шаніє.","Ра́дуйся, ісціле́ній благода́тний істо́чниче;","ра́дуйся, дарова́ній вели́ких вмісти́лище.","Ра́дуйся, благово́нноє ми́ро, облагоуха́ющеє ду́ші;","ра́дуйся, я́ко помога́єши призива́ющим тя.","Ра́дуйся, сліпи́м зрі́ніє дарова́вий;","ра́дуйся, хроми́м благоше́ствіє устро́ївий.","Ра́дуйся, великому́чениче і ціли́телю Пантелеї́моне."]},{"h":"Кондак 4","ps":["Бу́рею помишле́ній многобо́жія одержи́м, нечести́вий цар смути́ся, уві́дів от зави́ствовавших тебі́ враче́в, я́ко вся́кия неісці́льния неду́ги ціли́ши ти і́менем Христа́. Ми же, с весе́лієм сла́в'яще ди́внаго в тебі́ Бо́га, вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше нікомиди́йстії лю́діє о вели́ком сострада́нії твоє́м к стра́ждущим і о безме́здном врачева́нії от вся́ких болі́зней, устреми́шася всі к тебі́, с ві́рою во врачу́ющую благода́ть, в тебі́ су́щую, і, приє́млюще ско́рая ісціле́нія от вся́ких болі́зней, прославля́ху Бо́га і тебі́ велича́ху, всеми́лостиваго ціли́теля своєго́, зову́ще ті:","Ра́дуйся, пома́занний ми́ром благода́ті;","ра́дуйся, хра́мі Бо́га освяще́нний.","Ра́дуйся, вели́кая благочести́вих сла́во;","ра́дуйся, тве́рдая озлобля́ємих стіно́.","Ра́дуйся, му́дрих превосходя́й ра́зумом;","ра́дуйся, ві́рних осіява́яй ми́слі.","Ра́дуйся, Боже́ственних даро́в прия́телище і многообра́зних нам ми́лостей Госпо́дніх істо́чниче;","ра́дуйся, ско́рий помо́щниче стра́ждущим.","Ра́дуйся, обурева́ємих приста́нище;","ра́дуйся, заблу́ждших наста́вниче.","Ра́дуйся, боля́щих ту́не врачу́яй;","ра́дуйся, оби́льно ісціле́нія істоча́яй.","Ра́дуйся, великому́чениче і ціли́телю Пантелеї́моне."]},{"h":"Кондак 5","ps":["Чу́до пресла́вноє сотвори́ тобо́ю Госпо́дь, єгда́ чрез служи́теля Своєго́ Ермола́я призва́ тя в чу́дний Свой світ. Єхи́дною бо ве́лією угризе́нно уме́ршеє отроча́ по моли́тві твоє́й ко Христу́ а́біє оживе́ і воста́ здра́во. Позна́в у́бо Жизнода́вця всіх І́стиннаго Бо́га, с тве́рдою ві́рою воззва́л єси́ Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Узрі́ світ сліпи́й, єму́же с призива́нієм іме́не Христо́ва прикосну́лся єси́ ти, сла́вне. Ермола́єм бо пресви́тером просвіще́н, отри́нув оте́чеськоє многобо́жіє, восприя́л єси́ ма́тернєє благоче́стіє, і́мже і отця́ просвіти́л єси́. Сего́ ра́ди тебе́, сла́вному уго́днику Бо́жию і чу́дному врачу́, взива́єм:","Ра́дуйся, к Бо́гу ве́ліє раче́ніє імі́яй;","ра́дуйся, присногоря́щий огню́ боже́ственния любве́.","Ра́дуйся, ді́ятельний послу́шателю свяще́нних поуче́ній Ермола́я;","ра́дуйся, послі́довавий сове́там ма́тере твоє́й Євву́ли.","Ра́дуйся, я́ко вся разда́л єси́, да Христа́ приобря́щеши;","ра́дуйся, любо́в к ми́ру любо́вію Бо́жиєю побіди́вий.","Ра́дуйся, я́ко вмі́сто сла́дких ми́ра за Христа́ лю́тая страда́нія прия́л єси́;","ра́дуйся, я́ко о́бщник сотвори́лся єси́ Страсте́м Христо́вим.","Ра́дуйся, восторжествова́вий над всі́ми страстьми́;","ра́дуйся, украси́вийся благода́тним безстра́стієм.","Ра́дуйся, ісполня́яй ра́дости притека́ющия к тебі́;","ра́дуйся, ту́не ісціля́яй всіх благода́тію Христо́вою.","Ра́дуйся, великому́чениче і ціли́телю Пантелеї́моне."]},{"h":"Кондак 6","ps":["Пропові́дник і́стини яви́ся просвіще́нний тобо́ю тіле́сні і душе́вні сліпе́ць: подо́бно бо єва́нгельському сліпцю́, дерзнове́нно пред всі́ми іспові́да Сві́та І́стиннаго, Христа́, просвіща́юща вся́каго челові́ка, нечести́ваго же царя́ і бо́ги язи́чеськия укори́в, чрез ме́чноє усіче́ніє взи́де к немерца́ющему сві́ту на Небесі́ пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["С сві́тлим лице́м предста́в суди́лищу царе́ву, дерзнове́нно взива́л єси́, преблаже́нне, во усли́шаніє всіх: всецеле́бная си́ла моя́ і сла́ва Христо́с єсть, І́стинний Бог, Влади́ка всіх, ме́ртвия воскреша́яй і всяк неду́г отгоня́яй. За таково́є іспові́даніє ублажа́юще тя, глаго́лем:","Ра́дуйся, уста́ громогла́сная Божества́ Христо́ва;","ра́дуйся, язи́че медото́чний, віща́яй Єго́ домострої́тельство.","Ра́дуйся, виті́є преви́сшаго богосло́вія;","ра́дуйся, сі́ятелю му́дрий благоче́стія.","Ра́дуйся, сладкозву́чная ві́ри свирі́ль;","ра́дуйся, сла́вний пропові́дниче Правосла́вія.","Ра́дуйся, пре́жде сме́рти яви́вий ди́вная;","ра́дуйся, по сме́рті соверша́яй чу́дная.","Ра́дуйся, зри́телю сла́ви Христо́вой;","ра́дуйся, послу́шателю моля́щихся тебі́.","Ра́дуйся, пода́телю ми́лости тоя́ тре́бующим;","ра́дуйся, хода́таю благ почита́ющим па́м'ять твою́.","Ра́дуйся, великому́чениче і ціли́телю Пантелеї́моне."]},{"h":"Кондак 7","ps":["Ми́ро ізлія́ся на ду́шу твою́, богому́дрий ціле́бниче, от Уті́шителя Ду́ха; ті́мже по сме́рті честни́я мо́щі твоя́, благоуха́нієм свої́м страсте́й злосмра́діє отгоня́я, ісціле́ніє подаю́ть вопію́щим ві́рою Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Єгда́ узрі́ша і́дольстії чти́телі многолі́тна разсла́бленна, моли́твою твоє́ю, свя́те, воздви́гнута і ходя́ща, мно́зі уві́роваша во Христа́; жреци́ же бісо́встії, за́вистію сніда́єми, подвиго́ша царя́ на я́рость. Тебе́ у́бо неща́дно за Христа́ стру́жему і опаля́єму би́вшу, со умиле́нієм зове́м:","Ра́дуйся, наслажде́нія земна́я презрі́вий;","ра́дуйся, благ веще́ственних преви́сший.","Ра́дуйся, я́ко вся красна́я ми́ра сего́ ні во что же вміни́л єси́;","ра́дуйся, я́ко сла́ву скоротеку́щую с себі́ отря́сл єси́.","Ра́дуйся, неулови́м преби́вий ловле́нії Велія́ра;","ра́дуйся, побіди́вий мучи́телей кова́рства.","Ра́дуйся, не пощади́вий за Христа́ жи́зні своє́й;","ра́дуйся, враг яви́вийся вражде́бния пло́ті.","Ра́дуйся, многобо́жія широту́ утесни́вий;","ра́дуйся, боже́ственною си́лою і́доли попра́вий.","Ра́дуйся, остре́йшая стрело́, язвя́щая враги́;","ра́дуйся, предста́телю, заступа́яй ве́рующия.","Ра́дуйся, великому́чениче і ціли́телю Пантелеї́моне."]},{"h":"Кондак 8","ps":["Страннолі́пно явля́шеся тебі́ Госпо́дь, ободря́я і соблюда́я в муче́ніїх за і́м'я Єго́: во о́бразі бо пресви́тера Ермола́я, клоко́чущеє оло́во, в не́же вве́ржен бил єси́, охлади́, і в мо́рі отріши́во ве́лій ка́мень от ви́ї твоє́й, ізведе́ неврежде́нна на зе́млю. Ти же, па́ки предста́в пред царя́, торже́ственне піл єси́ Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь у́мні на Небесі́ водворя́яся, і ни́зу на землі́ су́щих не оставля́єши, сопребива́я с на́ми всечестно́ю главо́ю твоє́ю, вели́кий страстоте́рпче Христо́в, приє́мля от Го́спода і подая́ просвіще́ніє і освяще́ніє вопію́щим тебі́ такова́я:","Ра́дуйся, прему́дросте боже́ственния іспо́лненний;","ра́дуйся, промишле́нія Бо́жия о нас таї́нниче.","Ра́дуйся, богому́дренних умо́в услажде́ніє;","ра́дуйся, боголюби́вих душ увеселе́ніє.","Ра́дуйся, пресві́тлий Христо́в би́сере;","ра́дуйся, освяще́нний душе́ю і ті́лом.","Ра́дуйся, во дво́ріх перворожде́нних на Небесі́ всели́вийся;","ра́дуйся, в присноблаже́нних обита́яй черто́зіх.","Ра́дуйся, сві́та Тро́їчеськаго зри́телю;","ра́дуйся, в моли́твах к Бо́гу те́плий о нас предста́телю.","Ра́дуйся, просвіще́ніє душа́м подава́яй;","ра́дуйся, скорб'я́щим утіше́ніє низпосила́яй.","Ра́дуйся, великому́чениче і ціли́телю Пантелеї́моне."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ удиви́ся, Пантелеї́моне, сія́нію в тебі́ благода́ті і бога́тству доброді́телей: ангелоподо́бней чистоті́ твоє́й, вели́кому му́жеству в лю́тих страда́ніях, кре́пкой любве́ ко Христу́ і мно́гому сострада́нію к лю́дем, в ни́хже твори́ши пресла́вная, во є́же пі́ти: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я многовіща́нния не возмо́гуть по достоя́нію восхвали́ти боре́нія твоя́, сла́вний добропобе́дниче, ка́ко непобіди́мою си́лою Бо́жиєю ю́ний лі́ти побіди́ дре́вняго іско́ннаго врага́ і посрами́ і́дольськую пре́лесть. Ми же, удивле́нія іспо́лненнії, зове́м ті:","Ра́дуйся, ра́достноє зрі́лище А́нгелов;","ра́дуйся, благогові́йноє удивле́ніє челові́ков.","Ра́дуйся, кров за Христа́ ізлія́вий і в сме́рті мле́ко істочи́вий;","ра́дуйся, ті́ло за Него́ му́ченичеськой сме́рті преда́вий.","Ра́дуйся, іспові́дничества пра́вило;","ра́дуйся, до́блій во́їне Царя́ царе́й.","Ра́дуйся, тьми держа́вця побіди́вий;","ра́дуйся, побі́дою твоє́ю небе́сних і земни́х обвесели́вий.","Ра́дуйся, Го́рняго ми́ра обита́телю блаже́нний;","ра́дуйся, до́льняго ми́ра му́дрий стра́нниче.","Ра́дуйся, дре́во, украше́нноє плода́ми благода́тних дарова́ній;","ра́дуйся, нося́й добропобі́дния ві́тві.","Ра́дуйся, великому́чениче і ціли́телю Пантелеї́моне."]},{"h":"Кондак 10","ps":["Сострада́нія іспо́лнен, я́ко і́стинний подража́тель Пода́теля ми́лости Го́спода, честни́й страда́льче, Пантелеї́моном (сі єсть, всеми́лостивим) от Него́ преймено́ван єси́, на вся притека́ющия к тебі́ ми́лость ізлива́я, ю́же і нам неоску́дно істоча́й, о тебі́ вопію́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ну тя тве́рду обрі́т мучи́тель, ники́їми же му́ками победи́му, покуси́ся сокруши́ти крі́пость твою́ зуби́ звіре́й і острія́ми мучи́лищнаго колеса́, оба́че і в сем нічто́же у́спе: си́ла бо Христо́ва лю́тость звіре́й укроти́, а стра́шноє ко́ло, на не́мже обраща́ємо бі ті́ло твоє́, а́біє сокруши́ся. Тебе́ у́бо непобіди́мому страстоте́рпцю зове́м:","Ра́дуйся, честно́є Христо́во ізбра́ніє;","ра́дуйся, непоро́чноє Бо́гові благоуха́ніє.","Ра́дуйся, тве́рдий адама́нте Це́ркве;","ра́дуйся, непоколеби́мий сто́лпе, досяза́яй до Небесе́.","Ра́дуйся, зві́ри ви́димия укроща́яй;","ра́дуйся, драко́нов неви́димих сокруша́яй.","Ра́дуйся, обагре́нний твоє́ю за Христа́ кро́вію, срастворе́нною млеко́м;","ра́дуйся, неув'яда́ємия приє́мий вінці́.","Ра́дуйся, ра́дость причини́вий А́нгелом і челові́ком;","ра́дуйся, просла́вленний Бо́гом на Небесі́ і на землі́.","Ра́дуйся, небожи́телю, ликовству́яй с му́ченики;","ра́дуйся, насища́яйся лицезрі́нієм Христа́ пресла́дким.","Ра́дуйся, великому́чениче і ціли́телю Пантелеї́моне."]},{"h":"Кондак 11","ps":["Піснь ісхо́дную прино́сим твоєму́ за Христа́ заколе́нію свяще́нному, в не́мже вмі́сті с кро́вію млеко́ істече́ от тебе́, великому́чениче, і ма́слиничина, под не́юже усіче́н бил єси́, іспо́лнися ціли́тельних плодо́в. Ті́мже Христу́, ди́вно прославля́ющему сла́в'ящия Єго́, те́плі вопіє́м: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рная луча́ бил єси́, богому́дре, во тьмі многобо́жія сідя́щим, путеводя́щая к Со́лнцю Пра́вди Христу́ Бо́гу, Єму́же моли́ся, во сві́ті за́повідей Єго́ при́сно пребива́ти і нам, сицева́я ра́достная тебі́ принося́щим:","Ра́дуйся, пресві́тлая звіздо́, на ми́сленній тве́рди блиста́ющая;","ра́дуйся, луче́, христоімени́тим лю́дем світя́щий.","Ра́дуйся, та́їнственно облистава́ємий от Со́лнця Христа́;","ра́дуйся, у́мні зе́млю обтека́яй.","Ра́дуйся, селе́ніє кра́сноє Пресвята́го Ду́ха;","ра́дуйся, сосу́де пречестни́й, ізлива́яй ісціле́нія.","Ра́дуйся, чистоти́ сокро́вище;","ра́дуйся, ми́лости тезоімені́те.","Ра́дуйся, Ца́рствія Небе́снаго наслі́дниче;","ра́дуйся, ві́чния сла́ви соприча́стниче.","Ра́дуйся, предста́телю бе́дствующим в мо́рі жите́йстім;","ра́дуйся, безсре́брениче, помога́яй призива́ющим тя с ві́рою.","Ра́дуйся, великому́чениче і ціли́телю Пантелеї́моне."]},{"h":"Кондак 12","ps":["Благода́ті оби́ліє прия́л єси́, треблаже́нне, по оби́лію любве́ твоєя́ ко Христу́ Бо́гу, І́же і яви́ тя многоціле́бним істо́чником, безме́здно врачу́ющим душе́вния і тіле́сния болі́зні притека́ющих к тебі́ с ві́рою і Бо́гу вопію́щих: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще многострада́льния по́двиги твоя́ за Христа́, сла́вний страстоте́рпче, хва́лим долготерпі́ніє твоє́, ублажа́єм му́ченичеськую кончи́ну, почита́єм і свяще́нную па́м'ять твою́, засту́пниче наш і ціли́телю, і в похвалу́ сицева́я тебі́ зове́м:","Ра́дуйся, благоче́стія трубо́ бла́гозву́чная;","ра́дуйся, мечу́, посіка́яй нече́стіє.","Ра́дуйся, строга́нний на дре́ві за Распросте́ршаго ру́ці Свої́ на дре́ві Кре́стнім;","ра́дуйся, я́ко опаля́єм за Него́, пре́лести пещ погаси́л єси́.","Ра́дуйся, я́звами твої́ми враги́ уязви́вий;","ра́дуйся, кро́вію твоє́ю то́ки і́дольськия кро́ве ізсуши́вий.","Ра́дуйся, в кип'я́щеє о́лово вве́рженний за Христа́;","ра́дуйся, погруже́нний за і́м'я Єго́ во вода́х морськи́х.","Ра́дуйся, промишле́нієм Бо́жиїм неврежде́н в сих преби́вий;","ра́дуйся, я́ко чрез огнь і во́ду муче́ній вшел єси́ в поко́й Небе́сний.","Ра́дуйся, ізлива́яй неізсяка́ємия струй ми́лости ві́рним;","ра́дуйся, благосострада́тельний врачу́, ісціле́нія благода́ть подава́яй.","Ра́дуйся, великому́чениче і ціли́телю Пантелеї́моне."]},{"h":"Кондак 13","ps":["О многострада́льний і преди́вний страстоте́рпче Христо́в і ціли́телю наш Пантелеї́моне! Ми́лостиво приє́м сіє́ ма́лоє от нас приноше́ніє, от многообра́зних неду́гов ісціли́ ни і предста́тельством твої́м сохрани́ от враг ви́димих і неви́димих і ві́чнаго муче́нія ізба́виться нам Го́спода умоли́, да во Ца́рствії Єго́ ви́ну воспіва́єм: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела земна́го і небе́снаго челові́ка ві́ми тя, сла́вний Пантелеї́моне: а́нгельською бо непоро́чностію і му́ченичеством украше́н, пресели́лся єси́ от землі́ на Не́бо, іді́же со А́нгели і всі́ми святи́ми предстоя́ Престо́лу Го́спода сла́ви, моли́ся о нас, земни́х, почита́ющих тя зва́нії си́ми:","Ра́дуйся, сві́тлосте благоче́стія;","ра́дуйся, пресла́вний світи́льниче Це́ркве.","Ра́дуйся, му́чеников пречестни́х украше́ніє;","ра́дуйся, ві́рних в непоколеби́мом терпі́нії утвержде́ніє.","Ра́дуйся, ю́ности преізря́дная похвало́;","ра́дуйся, побо́рниче Христо́в, в му́жестві неодолі́нний.","Ра́дуйся, проізра́стший в ми́рі, преми́рен яви́вийся;","ра́дуйся, а́нгеле во пло́ті, превосходя́й сме́ртних.","Ра́дуйся, небожи́телю всеблаже́нний;","ра́дуйся, Боже́ственнаго ра́зума вмісти́лище.","Ра́дуйся, і́мже ві́ра возви́сися;","ра́дуйся, і́мже пре́лесть низложи́ся.","Ра́дуйся, великому́чениче і ціли́телю Пантелеї́моне."]},{"h":"Кондак 1","ps":["Ізбра́нний страстоте́рпче Христо́в і врачу́ благода́тний, ту́не подая́й неду́гующим ісціле́нія, пі́сньми восхваля́єм тя, засту́пника на́шего. Ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, от вся́ких бід і болі́зней свобожда́й нас, любо́вію тебі́ зову́щих:","Ра́дуйся, великому́чениче і ціли́телю Пантелеї́моне."]},{"h":"Молитва","ps":["О вели́кий Христо́в уго́дниче і пресла́вний ціле́бниче, великому́чениче Пантелеї́моне! Душе́ю на Небесі́ Престо́лу Бо́жию предстоя́й і трийпоста́сния Єго́ сла́ви наслажда́яйся, ті́лом же і ли́ком святи́м на землі́ в боже́ственних хра́міх почива́яй і да́нною ті сви́ше благода́тію разли́чная чудеса́ істоча́яй, при́зри ми́лостивним твої́м о́ком на предстоя́щия лю́ди, честні́й твоє́й іко́ні уми́льно моля́щіяся і прося́щия от тебе́ ціле́бния по́мощі і заступле́нія: простри́ ко Го́споду Бо́гу на́шему те́плия твоя́ моли́тви і іспроси́ душа́м на́шим оставле́ніє согріше́ній. Се бо ми, за беззако́нія на́ша не смі́юще возвісти́ очеса́ на́ша к висоті́ Небе́сній, ніже́ вознести́ глас моле́бний к Єго́ в Божестві́ непристу́пній сла́ві, се́рдцем сокруше́нним і ду́хом смире́нним тебі́, хода́тая ми́лостива ко Влади́ці і моли́твенника за ни, грі́шния, призива́єм, я́ко ти прия́л єси́ благода́ть от Него́ неду́ги отгоня́ти і стра́сті ісціля́ти. Тебе́ у́бо про́сим: не пре́зри нас, недосто́йних, моля́щихся тебі́ і твоєя́ по́мощі тре́бующих. Бу́ди нам в печа́ліх уті́шитель, в неду́зіх лю́тих стра́ждущим врач, напа́ствуємим ско́рий покрови́тель, очесе́м неду́гующим прозрі́нія да́тель, ссу́щим і младе́нцем в болі́зніх гото́війший предста́тель і ісціли́тель: ісхода́тайствуй всім вся, я́же ко спасе́нію поле́зная, я́ко да твої́ми ко Го́споду Бо́гу моли́твами получи́вше благода́ть і ми́лость, просла́вим всіх благи́х Істо́чника і Даропода́теля Бо́га, Єди́наго в Тро́йці Святі́й сла́вимаго Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Страстоте́рпче святи́й і ціле́бниче Пантелеї́моне, / моли́ Ми́лостиваго Бо́га, / да прегріше́ній оставле́ніє // пода́сть душа́м на́шим."]},{"h":"Кондак, глас 5","ps":["Подража́тель сий Ми́лостиваго, / і ісціле́ній благода́ть от Него́ приє́м, / страстоте́рпче і му́чениче Христа́ Бо́га, / моли́твами твої́ми душе́вния на́ша неду́ги ісціли́, / отгоня́ при́сно борця́ собла́зни от вопію́щих ві́рно: // спаси́ ни, Го́споди."]},{"h":"Величання","ps":["Велича́єм тя, / страстоте́рпче святи́й, великому́чениче і ціле́бниче Пантелеї́моне, / і чтим честна́я страда́нія твоя́, / я́же за Христа́ // претерпі́л єси́."]}],"notes":[]},{"u":"Акафіст преподобній Марії Єгипетській","e":"Akathist to our Venerable Mother Mary of Egypt","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от Го́спода во о́браз спасе́нія всім грі́шним і отча́янним, із глубини́ гріха́ восте́кшей на висоту́ безстра́стія, похва́льная пі́нія прино́сим ті, ма́ти преподо́бная, ти же, я́ко іму́щи дерзнове́ніє к Ще́дрому Бо́гу, моли́твами твої́ми наста́ви на стезю́ покая́нія любо́вію тебі́ зову́щих:","Ра́дуйся, чу́до милосе́рдія Бо́жия, Марі́є равноа́нгельная."]},{"h":"Ікос 1","ps":["А́нгела во пло́ті узрі́в тя в пусти́ні Іорда́нськой вели́кий Зоси́ма, на возду́сі стоя́щую і о ми́рі моля́щуюся, со удивле́нієм і у́жасом одержи́м весь тре́петом бив, со слеза́ми вопія́ше тебі́ такова́я:","Ра́дуйся, благода́ті і сві́та іспо́лненная;","ра́дуйся, прозрі́нія да́ром украше́нная.","Ра́дуйся, в моли́тві твоє́й на возду́сі стоя́щая;","ра́дуйся, пусти́нноє сокро́вище, от ми́ра утає́нноє.","Ра́дуйся, безпло́тних собесі́днице;","ра́дуйся, Ду́ха Свята́го селе́ніє.","Ра́дуйся, чу́до милосе́рдія Бо́жия, Марі́є равноа́нгельная."]},{"h":"Кондак 2","ps":["Ви́дящи ста́рця благогові́йнаго, у́жаса іспо́лнена, ти́хим гла́сом рекла́ єси́ тому́, преподо́бная: «Не бо́йся, а́вво Зоси́мо, нісьм дух, но земля́, прах і пе́пел, і вся́чеськи плоть, нічто́же духо́вноє когда́ поми́слившая і ні єди́ния доброді́телі іму́щая. Жена́ єсьм грі́шниця, недосто́йная взира́ти на не́бо, і со стра́хом грі́шними усти́ зову́ Бо́гу: Аллилу́я»."]},{"h":"Ікос 2","ps":["Разумі́ти іща́ ди́вную та́йну, в тебі́ сокрове́нную, ста́рець паде́ пред нога́ма твої́ма, глаго́ля: «Заклина́ю тя і́менем Го́спода на́шего Ісу́са Христа́, Єго́же ра́ди наготу́ но́сиши сію́, не скрий от мене́ житія́ твоєго́, да вели́чія Бо́жия я́ві сотвори́ши». С ни́мже і ми дерза́єм ублажа́ти тя си́це:","Ра́дуйся, смире́нія сві́тлая висото́;","ра́дуйся, дарова́ній духо́вних бога́тство неісчерпа́ємоє.","Ра́дуйся, любве́ ра́ди Бо́жия ті́ло своє́ умерщвля́вшая;","ра́дуйся, в пусти́ні непрохо́дній єди́на с єди́ним Бо́гом пребива́вшая.","Ра́дуйся, ра́йською красото́ю сія́ющая;","ра́дуйся, безстра́стія сві́том озаре́нная.","Ра́дуйся, чу́до милосе́рдія Бо́жия, Марі́є равноа́нгельная."]},{"h":"Кондак 3","ps":["«Си́лою Ви́шняго укріпля́єма, іспові́м ті, челові́че Бо́жий, гріхи́ і беззако́нія моя́, — отвіща́ла єси́ Зоси́мі, — стижду́ся, о́тче, прости́ м'я, но поне́же ті́ло моє́ на́го ви́діл єси́, обнажу́ ті і діла́ моя́, оба́че молю́ тя пе́рвіє: не біжи́ от мене́, не терп'я́ сли́шати безмі́стная, я́же аз содія́х; но, милосе́рдствуя о мні, моли́ся за м'я, блу́дную, і Бо́гу, не возгнуша́вшемуся мно́ю, зови́: Аллилу́я»."]},{"h":"Ікос 3","ps":["«Імі́я милосе́рдіє неізрече́нноє, с митарі́ і грі́шники вечеря́вий, Той і мні, во глубину́ поги́белі па́дшей, простре́ ру́ку Свою́ Боже́ственную, єгда́ бо возжела́х аз вни́ти в храм Госпо́день, ні́кая си́ла возбра́ни мі вход, се́рдця же моєго́ косну́вийся світ ра́зума, показа́ мі ти́ну діл мої́х; і нача́х пла́катися о грісі́х, в пе́рси бію́щи і го́рко рида́ющи», — си́це рекла́ єси́, Марі́є, ми же, покая́нію твоєму́ див'я́щеся, пі́ніє прино́сим ті таково́є:","Ра́дуйся, я́ко но́щі преше́дшей возсія́ ті заря́ спасе́нія;","ра́дуйся, я́ко глас Христо́в призва́ овча́ заблу́ждшеє от де́брей гріха́.","Ра́дуйся, я́ко сле́зними то́ки оми́ла єси́ вся твоя́ скве́рни;","ра́дуйся, я́ко слеза́ми твої́ми очи́стила єси́ одія́ніє душі́ твоєя́.","Ра́дуйся, я́ко Оте́ць щедро́т об'я́тія Своєя́ любве́ тебі́ отве́рзе;","ра́дуйся, я́ко Ві́дий твоя́ та́йная рукописа́нія гріхо́в твої́х раздра́.","Ра́дуйся, чу́до милосе́рдія Бо́жия, Марі́є равноа́нгельная."]},{"h":"Кондак 4","ps":["Бу́рею ско́рбних помисло́в одержи́ма, узрі́ла єси́ іко́ну Пречи́стия Богома́тері і, стеня́щи, воззва́ла єси́ к Ней: «Повели́, о Влади́чице, да і мні, недосто́йней, отве́рзуться боже́ственнії вхо́ди, і бу́ди мі Пору́чниця, да узрі́вши Крест Си́на Твоєго́, ми́ра і я́же в ми́рі всего́ отве́ргуся і ізи́ду, а́може повели́ши мні, зову́щи Бо́гу: Аллилу́я»."]},{"h":"Ікос 4","ps":["Сли́шавши глас, іздале́ча глаго́лющ: «А́ще Іорда́н пре́йдеши, добр поко́й обря́щеши», на колі́на па́дши пред Присноді́вою, рекла́ єси́: «О Влади́чице! Не гнуша́ється ді́вственная чистота́ Твоя́ моєя́ недосто́йния моли́тви, бу́ди мі спасе́нія Учи́тельниця, руково́дствующая на путь покая́нія!» Ті́мже у́бо А́нгели Бо́жії, напису́юще іспові́даніє твоє́, возглаша́ху тебі́ в той час сицева́я:","Ра́дуйся, от тьми гріха́ к чи́стому сві́ту покая́нія преше́дшая;","ра́дуйся, неі́стовство страсте́й і нечистоту́ плотську́ю отри́нувшая.","Ра́дуйся, тя́жкоє бре́м'я сту́дния рабо́ти дия́воли отве́ргшая;","ра́дуйся, благо́є і ле́гкоє і́го Христо́во под'є́мшая.","Ра́дуйся, от сме́рти гріхо́вния к ві́чному животу́ возста́вшая;","ра́дуйся, от врат поги́белі ко врато́м рая́ восше́дшая.","Ра́дуйся, чу́до милосе́рдія Бо́жия, Марі́є равноа́нгельная."]},{"h":"Кондак 5","ps":["Богосві́тлими луча́ми благода́ті просвіща́єть тя Пресвята́я Ді́ва, Та бо Спору́чниця грі́шних к Бо́гу су́щи, отверза́єть тебі́ две́рі милосе́рдія Бо́жия і врата́ хра́ма свята́го, во́ньже вше́дши, со мно́гими слеза́ми поклони́лася єси́ Живоно́сному Дре́ву, і́мже мир спасе́н бисть, і распе́ншемуся Го́споду, Кров Свою́ за твоє́ ізбавле́ніє ізлія́вшему, благода́рственно воспі́ла єси́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівши та́йни Бо́жия і ка́ко Той гото́в єсть прийма́ти ка́ющихся, всехва́льная Марі́є, воззва́ла єси́ всім се́рдцем: «Влади́чице Богоро́дице! Не оста́ви мене́!» — і устреми́лася єси́ в пусти́ню об он пол Іорда́на, ми же, почита́юще бі́гство твоє́, сріта́єм тя пі́нії си́ми:","Ра́дуйся, я́ко всепроща́ющею любо́вію Спа́са ура́нися се́рдце твоє́;","ра́дуйся, я́ко сокро́вище благода́ті, тобо́ю прия́тоє, потща́лася єси́ сокри́ти в пусти́ні.","Ра́дуйся, я́ко ми́ра гріхо́вния сла́дости скороте́чно отбі́гла єси́;","ра́дуйся, я́ко невозвра́тноє ше́ствіє твоє́ к небе́сним на всяк день ускоря́ла єси́.","Ра́дуйся, я́ко ре́вностний ісхо́д твой де́мони опали́;","ра́дуйся, я́ко вселе́ніє твоє́ в ско́рбную пусти́ню Небеса́ возвесели́.","Ра́дуйся, чу́до милосе́рдія Бо́жия, Марі́є равноа́нгельная."]},{"h":"Кондак 6","ps":["Пропові́дуєши всім па́дшим і отча́янним, всечестна́я, Бо́жиє человіколю́біє, і явля́єши си́лу покая́нія, я́же грі́шную ду́шу омива́єть, очища́єть, светли́ть, і возво́дить горе́, і весе́ліє твори́ть А́нгелом Бо́жиїм, с ни́миже і ми бре́нними усти́ зове́м: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ ми́рові от пусти́ні Іорда́нськия світ вели́ких по́двигов твої́х, Марі́є присносла́вная, мно́гая бо лі́та, а́ки адама́нт тверд і столп непоколеби́м пребила́ єси́, я́ко со звірми́ лю́тими, с похотьми́ твої́ми борю́щися і ору́жієм Креста́ отража́ющи разжже́нния стрі́ли лука́ваго. Сего́ ра́ди див'я́щеся преєсте́ственному терпі́нію твоєму́, любо́вію зове́м ті:","Ра́дуйся, я́ко злострада́нія труд в пусти́ні чети́редесять і осм літ понесла́ єси́;","ра́дуйся, я́ко опале́ніє со́лнечноє і мраз нощни́й в наготі́ долготерпе́ла єси́.","Ра́дуйся, гла́дом і жа́ждею ізможда́ємая;","ра́дуйся, покро́вом Богоро́диці от сме́рти охраня́ємая.","Ра́дуйся, я́ко в борбі́ со гріхо́м, в тебі́ живу́щим, до кро́ве подвиза́лася єси́.","Ра́дуйся, я́ко вся́коє пожела́ніє пло́ті коне́чні умертви́ла єси́.","Ра́дуйся, чу́до милосе́рдія Бо́жия, Марі́є равноа́нгельная."]},{"h":"Кондак 7","ps":["Хотя́ преп'я́тіє сотвори́ти твоєму́ сві́тлому к Небесі́ ше́ствію, всеблаже́нная, іско́нний враг ро́да челові́чеськаго не престая́ше влага́ти ті по́мисли нечи́стия, огнь гріхо́вний в удесі́х твої́х разжиза́я і приводя́ тебі́ на па́м'ять о́брази пре́жняго житія́ твоєго́. Ти же, многострада́льная, поверга́лася єси́ на зе́млю, слеза́ми ороша́ющи ю і призива́ющи в по́мощ Присноді́ву, і не востава́ла єси́ от землі́, до́ндеже сла́дкий світ осіява́ше тя, воздвиза́я благода́рственно пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вий челові́к, по Бо́зі созда́нний, яви́лася єси́, преподо́бная, умертви́вши бо всеконе́чні ве́тхаго челові́ка, во Христа́ облекла́ся єси́, всечу́дная, за седмна́десять літ безчи́сленния біди́ постра́давши. О сем у́бо Зоси́мі рекла́ єси́: «Отто́лі же і до днесь си́ла Бо́жия грі́шную мою́ ду́шу і ті́ло смире́нноє соблюде́». Прийми́ у́бо і от нас, недосто́йних, похвали́ сицеви́я:","Ра́дуйся, я́ко умертви́ла єси́ страсте́й взигра́нія;","ра́дуйся, я́ко побіди́ла єси́ і са́моє єстество́.","Ра́дуйся, я́ко очи́стила єси́ ду́шу і плоть твою́ от вся́каго гріха́;","ра́дуйся, я́ко в хра́мині всели́ся Госпо́дь.","Ра́дуйся, я́ко облекла́ся єси́ в оде́жду весе́лія духо́внаго;","ра́дуйся, я́ко вошла́ єси́ во ві́чний поко́й Си́на Бо́жия.","Ра́дуйся, чу́до милосе́рдія Бо́жия, Марі́є равноа́нгельная."]},{"h":"Кондак 8","ps":["Стра́нноє і пресла́вноє ізмі́неніє твоє́, преподо́бная, ви́дяще, де́монов те́мния полці́ го́рко рида́ху, вся же Си́ли Небе́сния ра́достію ігра́юще, піснь Христу́ воспіва́ху, прославля́юще Бо́жиє милосе́рдіє, гріхми́ людськи́ми неодоли́моє, ве́ліїм гла́сом зову́ще: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся била́ єси́ в Бо́зі, Марі́є всебога́тая, єгда́ Зоси́ма, обходя́ пусти́ню, ви́діти тя сподо́бися. «Заклина́ю тя, о́тче, Спаси́телем Бо́гом, да нікому́же рече́ши, я́же сли́шал єси́ от мене́, до́ндеже Бог от землі́ во́зьметь м'я, — запові́дала єси́ тому́. — Ни́ні с ми́ром отиди́, в пості́ же гряду́щаго лі́та причасти́ м'я Святи́х Христо́вих Та́їн на бре́зі Іорда́нстім». Сія́ ре́кши, а́ки го́рлиця пустиннолюби́вая і неудержи́мая, от о́чію ста́рця скри́лася єси́, той же поклони́ся до землі́ і, облоби́зав мі́сто, іді́же стоя́сте но́зі твої́, воззва́ такова́я:","Ра́дуйся, я́ко студа́ гріхо́внаго обнажи́лася єси́;","ра́дуйся, я́ко па́че сні́га убели́лася єси́;","Ра́дуйся, я́ко омраче́ніє стра́стноє препобеди́ла єси́;","ра́дуйся, я́ко па́че луче́й со́лнечних просвіти́лася єси́.","Ра́дуйся, пе́рвіє блудни́ця, ни́ні же неві́ста Христо́ва;","ра́дуйся, я́ко всі гріси́ твої́ проще́ни суть у Бо́га.","Ра́дуйся, чу́до милосе́рдія Бо́жия, Марі́є равноа́нгельная."]},{"h":"Кондак 9","ps":["«Всяк по́мисл і ум ужаса́ють болі́зні твоя́, всехва́льная, ка́ко труд пусти́ні любве́ ра́ди Бо́жия прете́рпіла єси́, — взива́ше превели́кий во отці́х Зоси́ма, рида́я. — О, ма́ти духо́вная! Ти Бо́гу прибли́зилася єси́, хоті́л бих, а́ще би мо́щно мі би́ло, во слід тебе́ ходи́ти, і зрі́ти честно́є лице́ твоє́, і ку́пно с тобо́ю немо́лчно пі́ти: Аллилу́я»."]},{"h":"Ікос 9","ps":["Вети́йство земноро́дних не довлі́єть к досто́йному похвале́нію твої́х по́двигов, всечестна́я. Кто же дово́лен ізрещи́ сле́зния то́ки, я́же пролія́ла єси́ в моли́твах к Бо́гу, кто болі́зні твоя́ ізочте́ть, кто іспові́сть всено́щная бді́нія, боре́нія і тісноту́ житія́ твоєго́? Пусти́ню всю чудеси́ просвіти́вши, я́ко со́лнце, просія́ла єси́, всечу́дная, тім у́бо мо́лим тя: озари́ луча́ми сві́та твоєго́ сердця́ на́ша і іспроси́ оставле́ніє гріхо́во всім вопію́щим тебі́ такова́я:","Ра́дуйся, помраче́нний о́браз Бо́жий в сві́тлости вели́цій в себі́ возобрази́вшая;","ра́дуйся, смра́да гріха́ ізбі́гши, небе́сними арома́ти благоуха́ющая.","Ра́дуйся, звізда́ми чуде́с украше́нная;","ра́дуйся, луча́ми доброді́телей сія́ющая.","Ра́дуйся, вели́чія Бо́жия всім конце́м землі́ благовеству́ющая;","ра́дуйся, не́бо і зе́млю к пі́нію сла́ви Го́спода твоєго́ призива́ющая.","Ра́дуйся, чу́до милосе́рдія Бо́жия, Марі́є равноа́нгельная."]},{"h":"Кондак 10","ps":["Спаси́теля Бо́га Животворя́щия Ті́ло і Кров взем, в день та́їнственния Христо́ви Ве́чері а́вва Зоси́ма по завіща́нію твоєму́, преподо́бная ма́ти, во ве́чер зіло́ по́зден ізи́де на брег Іорда́на, неукло́нно в пусти́ню лу́нним сві́том осіява́ємую, зря і моля́ся к Бо́гу, глаго́лаше: «Покажи́ мі, Го́споди, сокро́вище Твоє́, є́же в пусти́ні сокри́л єси́! Покажи́ мі а́нгела во пло́ті, да не оти́ду тощ, нося́ моя́ гріхи́ на обличе́ніє, но да ра́дуяся, зову́ Тебі́: Аллилу́я»."]},{"h":"Ікос 10","ps":["Сті́ну непрохо́дну ми́сляше ста́рець би́ти Іорда́н ре́ку между́ ним і тобо́ю, преподо́бная; оба́че ти, ста́вши на бре́зі да́льнем, зна́менієм кре́стним Іорда́н осени́ла єси́ і с моли́твою пошла́ єси́ по воді́, а́ки по су́ху. Зоси́ма же, ви́дів тя, гряду́щу по вода́м Іорда́нським, ужасе́ся і ра́достні вопія́ше тебі́:","Ра́дуйся, го́рняго рая́ Бо́жия обита́тельнице;","ра́дуйся, я́ко твар повину́ється велі́нію твоєму́.","Ра́дуйся, я́ко Іорда́н тебі́ слу́жить;","ра́дуйся, я́ко луна́ і зві́зди див'я́ться святи́не твоє́й.","Ра́дуйся, си́ли Бо́жия ди́вноє проявле́ніє;","ра́дуйся, Бо́га Жива́го хра́мі одушевле́нний.","Ра́дуйся, чу́до милосе́рдія Бо́жия, Марі́є равноа́нгельная."]},{"h":"Кондак 11","ps":["«Пі́ніє подоба́єть тебі́ приноси́ти Всемогу́щему Бо́гу, а́вво, — рекла́ єси́ тому́, по воді́ ше́ствующи. — Что твори́ши, свяще́нник сий, ка́ко хо́щеши кла́нятися мні, убо́зей, сам нося́й стра́шния Та́йни Христа́ Бо́га! І́мже ві́рою і лю́бовію покланя́ющися, прах і земля́ су́щи, со стра́хом зову́: Аллилу́я»."]},{"h":"Ікос 11","ps":["Сві́том небе́сним блистающи́ся, причасти́лася єси́ Боже́ственних Та́їн і ра́дости преми́рния іспо́лнившися і на не́бо ру́ці возді́вши, рекла́ єси́: «Ни́ні отпуща́єши рабу́ Твою́, Влади́ко!» Обра́щшися же к ста́рцю, віща́ла єси́: «О, а́вво Зоси́мо! В гряду́щеє лі́то у́зриши м'я па́ки в пусти́ні, я́коже хо́щеть Госпо́дь. Моли́ Єго́ о мні, о́тче мой, моли́, помина́я всегда́ моє́ окая́нство». І па́ки Іорда́н зна́менавши, прешла́ єси́ верху́ води́, ста́рець же, не смі́я надо́лзі держа́ти тя, стеня́ і рида́я, взива́ше во слід тебі́ такова́я:","Ра́дуйся, ме́ртвость Го́спода Ісу́са в ті́лі нося́щая;","ра́дуйся, Воскресе́нія Єго́ сла́вою сія́ющая.","Ра́дуйся, благода́тію, я́ко ри́зою сві́та, облече́нная;","ра́дуйся, світоза́рная оби́тель Всесвяти́я Тро́йці.","Ра́дуйся, я́ко си́ли а́дови ужаса́ються і тре́пещуть сла́ви твоєя́;","ра́дуйся, я́ко А́нгели Бо́жії див'я́ться чистоті́ твоє́й.","Ра́дуйся, чу́до милосе́рдія Бо́жия, Марі́є равноа́нгельная."]},{"h":"Кондак 12","ps":["Благода́тію Боже́ственною окриля́єма, во єди́н час долготу́ пусти́ні прешла́ єси́ і в нощ спаси́тельния Христо́ви Стра́сті, по причаще́нії Боже́ственния Та́йния Ве́чері, сном святи́м усну́ла єси́, о ми́рі моля́щися, і дух твой Го́споду предала́ єси́, Єму́же со а́нгели в неісповіди́мій ра́дости зове́ши ни́ні: Аллилу́я."]},{"h":"Ікос 12","ps":["Поя́ надгро́бноє пі́ніє, богому́дрий Зоси́ма но́зі твої́ честні́ї слеза́ми омива́ше, і мно́го моли́вся, покри́ ті́ло твоє́ земле́ю, на́го су́щеє і нічто́же іму́щеє, то́чію ве́тхую ма́нтію, ю́же іспе́рва тебі́ даде́, ра́достію і стра́хом мно́гим одержи́м, вели́чію Бо́жию див'я́ся, стоя́ше, зови́й к тебі́ такова́я:","Ра́дуйся, я́ко, ча́до сві́та су́щи, прешла́ єси́ к Сві́ту невече́рнему;","ра́дуйся, я́ко дух твой с весе́лієм прия́ша со́нми святи́х.","Ра́дуйся, я́ко ті́ло твоє́ упоко́їся во во гро́бі, і́же лев от пусти́ні тебі́ іскопа́;","ра́дуйся, я́ко тобо́ю показа́ нам Госпо́дь, коли́ко отстої́м от мі́ри соверше́нства.","Ра́дуйся, по́стников висото́ і преподо́бних сла́во;","ра́дуйся, о всем ми́рі к Бо́гу хода́тайце.","Ра́дуйся, чу́до милосе́рдія Бо́жия, Марі́є равноа́нгельная."]},{"h":"Кондак 13","ps":["О, преподо́бная ма́ти, богоблаже́нная Марі́є! Прийми́ от нас ни́ні приноси́моє тебі́ моле́ніє і, Сві́ту непристу́пному предстоя́щи, моли́ся Всеще́дрому Бо́гу, да по вели́цій ми́лості Своє́й, низпо́слеть світоза́рную благода́ть покая́нія всім нам, заблу́ждшим ча́дом Небе́снаго Отця́, да, от гріха́ к оте́чеському до́му восте́кше, в ра́йських селе́ніїх сподо́бимся вку́пі с тобо́ю во ві́ки благода́рственно пі́ти Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела во пло́ті узрі́в тя в пусти́ні Іорда́нськой вели́кий Зоси́ма, на возду́сі стоя́щую і о ми́рі моля́щуюся, со удивле́нієм і у́жасом одержи́м весь тре́петом бив, со слеза́ми вопія́ше тебі́ такова́я:","Ра́дуйся, благода́ті і сві́та іспо́лненная;","ра́дуйся, прозрі́нія да́ром украше́нная.","Ра́дуйся, в моли́тві твоє́й на возду́сі стоя́щая;","ра́дуйся, пусти́нноє сокро́вище, от ми́ра утає́нноє.","Ра́дуйся, безпло́тних собесі́днице;","ра́дуйся, Ду́ха Свята́го селе́ніє.","Ра́дуйся, чу́до милосе́рдія Бо́жия, Марі́є равноа́нгельная."]},{"h":"Кондак 1","ps":["Ізбра́нній от Го́спода во о́браз спасе́нія всім грі́шним і отча́янним, із глубини́ гріха́ восте́кшей на висоту́ безстра́стія, похва́льная пі́нія прино́сим ті, ма́ти преподо́бная, ти же, я́ко іму́щи дерзнове́ніє к Ще́дрому Бо́гу, моли́твами твої́ми наста́ви на стезю́ покая́нія любо́вію тебі́ зову́щих:","Ра́дуйся, чу́до милосе́рдія Бо́жия, Марі́є равноа́нгельная."]},{"h":"Молитва","ps":["О, вели́кая Христо́ва уго́днице, преподо́бная ма́ти Марі́є! На Небесі́ Престо́лу Бо́жию предстоя́щи, на землі́ же ду́хом любве́ с на́ми пребива́ющи, іму́щи дерзнове́ніє ко Го́споду, моли́ спасти́ раби́ Єго́, к тебі́ с любо́вію притека́ющия. Іспроси́ нам у Многоми́лостиваго Влади́ки і Го́спода на́шего ві́ри непоро́чноє соблюде́ніє, градо́в і ве́сей на́ших утвержде́ніє, от гла́да і па́губи ізбавле́ніє, скорб'я́щим утіше́ніє, неду́гующим ісціле́ніє, па́дшим возста́ніє, заблу́ждшим вразумле́ніє, в ді́ліх благи́х преспі́яніє і благослове́ніє, сирота́м і вдови́цям заступле́ніє і отше́дшим от сего́ житія́ ві́чноє упокоє́ніє. Бу́ди крі́пкая хода́тайця, ди́вная ма́ти Марі́є, во є́же всім нам в день Стра́шнаго Суда́ десни́я страни́ о́бщники би́ти і блаже́нний глас Судії́ ми́ра усли́шати: прийді́те, благослове́ннії Отця́ Моєго́, наслі́дуйте угото́ванноє вам Ца́рствіє от сложе́нія ми́ра. Амі́нь."]},{"h":"Тропар, глас 8","ps":["В тебі́, ма́ти, ізві́стно спасе́ся, є́же по о́бразу, / приї́мши бо крест, послі́довала єси́ Христу́ / і, ді́ющи учи́ла єси́ презира́ти у́бо плоть, прехо́дить бо, / приліжа́ти же о душі́ ве́щі безсме́ртній. // Ті́мже і со А́нгели сра́дується, преподо́бная Марі́є, дух твой."]},{"h":"Кондак, глас 4","ps":["Гріха́ мгли ізбіжа́вши, / покая́нія сві́том озари́вши твоє́ се́рдце, сла́вная, / пришла́ єси́ ко Христу́, / Сего́ Всенепоро́чную і святу́ю Ма́тер / Моли́твенницю ми́лостивную принесла́ єси́. / Отону́дуже і прегріше́ній обріла́ єси́ оставле́ніє, // і со А́нгели при́сно сра́дуєшися."]},{"h":"Інший кондак, глас 3","ps":["Блуда́ми пе́рвіє преіспо́лнена вся́чеськими, / Христо́ва неві́ста днесь покая́нієм яви́ся, / а́нгельськоє жи́тельство подража́ющи, / де́мона креста́ ору́жієм погубля́єть. // Сего́ ра́ди Ца́рствія неві́ста яви́лася єси́, Марі́є пресла́вная."]},{"h":"Величання","ps":["Велича́єм тя, преподо́бная ма́ти Марі́є, і чтим святу́ю па́м'ять твою́, наста́внице мона́хов і собесі́днице А́нгелов."]}],"notes":[]},{"u":"Акафіст великомученику Дмитрію Солунському","e":"Akathist to the Great Martyr Demetrius of Thessalonica","secs":[{"h":"Кондак 1","ps":["Ди́вний воєво́до гра́да Солу́ня, вели́кий уго́дниче Христо́в і сла́вний страстоте́рпче, святи́й Дими́тріє, істоча́яй ми́рові ми́лости ми́ро, похва́льная воспису́єм ті, чту́щії святу́ю па́м'ять твою́. Ти же імі́яй дерзнове́ніє ко Го́споду, от вся́ких бід ізбавля́й нас, ві́рно зову́щих ті:","Ра́дуйся, святи́й Дими́тріє, сла́вний великому́чениче і чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і Госпо́дь Сил яви́ тя, досточу́дне, а́нгела во пло́ті, му́ченика тве́рда і си́льнаго предста́теля ві́рних. Прибіга́юще у́бо к заступле́нію твоєму́, сицева́я ра́достная тебі́ прино́сим:","Ра́дуйся, звіздо́ блиста́ющая на тве́рди церко́вній;","ра́дуйся, світи́льниче, чудеси́ мир озаря́яй.","Ра́дуйся ві́ри непоколеби́мий сто́лпе;","ра́дуйся, христия́н несокруши́мий щі́те.","Ра́дуйся, Фесса́лії сві́тлоє украше́ніє;","ра́дуйся, Солу́ня похвало́ пресла́вная.","Ра́дуйся, апо́столов сограждани́не;","ра́дуйся, му́чеников совсе́льниче.","Ра́дуйся, моля́щихся к тебі́ проше́нія приє́мляй;","ра́дуйся, о всіх нас Бо́гу моля́йся.","Ра́дуйся, святи́й Дими́тріє, сла́вний великому́чениче і чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дяще себі́ безча́дна, благочести́вая роди́теля твоя́ прилі́жно моля́ста Бо́га о дарова́нії ча́да. Приє́м же Всеви́шній моли́тви єю́, і пом'яну́в ми́лостині, я́же творя́ста убо́гим, дарова́ їм тебі́, блаже́нне. Сего́ ра́ди с весе́лієм возопи́ста Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум боже́ственний імі́я, я́ко отроча́ богодарова́нноє, возгнуша́лся єси́ язи́чеськия пре́лести, му́дре. Роди́тельськоє же благоче́стіє возлю́бль, доброді́тельми а́ки лі́ствицею от си́ли в си́лу восходя́й, благода́ть Бо́жию приобрі́л єси́, ю́же іспроси́ получи́ти і нам, почита́ющим тя зва́нії си́ми:","Ра́дуйся, благочести́вим роди́телем моли́твенноє прозябе́ніє;","ра́дуйся, благоче́стія їх наслі́дниче.","Ра́дуйся, рожде́нієм свої́м возвесели́вий мно́гих;","ра́дуйся, от утро́би ма́тернія благода́тію сви́ше осіне́нний.","Ра́дуйся, благоуха́нний кри́не ді́вства і нетлі́нія;","ра́дуйся, освяще́нний душе́ю же і ті́лом.","Ра́дуйся, вмісти́лище дарова́ній Бо́жиїх;","ра́дуйся от ю́ности ідолослуже́ніє презрі́вий.","Ра́дуйся, і́стинноє богопочита́ніє да́же до сме́рти возлюби́вий;","ра́дуйся, я́ко благоче́стієм твої́м угоди́л єси́ Христу́.","Ра́дуйся, я́ко благода́тію Єго́ мног плод сотвори́л єси́.","Ра́дуйся, святи́й Дими́тріє, сла́вний великому́чениче і чудотво́рче."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго сотвори́ тя, Дими́тріє, хра́бра во бра́ніх, враго́м стра́шна, всім лю́дем імени́та. Ті́мже і злочести́вий цар Максимія́н вручи́ тебі́ град Солу́нь, повеліва́я, я́ко суєму́дрий, гна́ти Христия́ни, пою́щия Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй благоприя́тную по благоче́стію ре́вность, я́ві пред неві́рними іспові́дал єси́ Христа́, прехва́льне, і тіх ві́ровати і покланя́тися Тому́ научи́л єси́, і я́ко втори́й Па́вел бил єси́ солу́няном, с ни́миже вопіє́м ті:","Ра́дуйся, Це́ркві Христо́вой драги́й би́сере;","ра́дуйся, гра́да твоєго́ украше́ніє.","Ра́дуйся, боже́ственную ре́вность в се́рдці своє́м носи́вий;","ра́дуйся, мучи́телей кова́рства побіди́вий.","Ра́дуйся, і́дольськия пре́лести обличи́телю;","ра́дуйся, і́дольськоє те́рніє посіця́яй.","Ра́дуйся, благоче́стія учи́телю;","ра́дуйся, на стезі́ спасе́нія наста́вителю.","Ра́дуйся, враго́м ви́димим і неви́димим непристу́пне;","ра́дуйся, во́їне Христо́в непобіди́ме.","Ра́дуйся, святи́й Дими́тріє, сла́вний великому́чениче і чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рею одержи́м помишле́ній зло́бних, нечести́вий цар см'яте́ся, уві́дів тя, всече́стне, ві́рнаго би́ти раба́ Христо́ва, к ві́рі в Того́ приводя́ща і і́доли низлага́юща, солу́нян же науча́юща сла́вити трисвято́є і́м'я Бо́жиє і пі́ти Тому́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша, я́ко ди́шащий на тя, Дими́тріє, я́ростію Максимія́н гряде́ть в Солу́нь, моли́твою і поще́нії предугото́вил єси́ себе́ к муче́нію, повеліва́я Лу́ппу, ві́рному ті рабу́, вся імі́нія твоя́ і бога́тства привре́менная расточи́ти убо́гим. Ті́мже, восхваля́юще тя, с любо́вію зове́м:","Ра́дуйся, преще́нія мучи́телева не убоя́вийся;","ра́дуйся, да Христа́ приобря́щеши, вся расточи́вий.","Ра́дуйся, су́єтную сла́ву ми́ра сего́ во уме́ти вміни́вий;","ра́дуйся, небе́сную сла́ву у Христа́ Бо́га на́шего получи́вий.","Ра́дуйся, я́ко состра́ждеши всім тре́бующим от тебе́ по́мощі;","ра́дуйся, су́щим в ну́ждах ско́рий засту́пниче.","Ра́дуйся, ни́щих обогати́телю;","ра́дуйся, си́рих предста́телю.","Ра́дуйся, убо́гим помо́щниче;","ра́дуйся, а́лчущим пита́телю.","Ра́дуйся, святи́й Дими́тріє, сла́вний великому́чениче і чудотво́рче."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ уподо́блься, Дими́тріє, дерзнове́нно Со́лнце Пра́вди пропові́дал єси́ тьмо́ю одержи́мому царю́. В темни́ці же їм заключе́нний, славосло́вил єси́ в ней, я́ко в черто́зі сві́тлі, Христа́ Бо́га на́шего, с весе́лієм поя́ Тому́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя добра́ ненави́стник дия́вол тече́ніє, достоблаже́нне, сконча́тися іму́щеє, за́вистію сніда́єм, устреми́ся на тя во о́бразі ско́рпії. Ти же, попра́в того́, узрі́л єси́ во сві́тлості вели́цій а́нгела Госпо́дня, укріпля́юща тя і віне́ць ра́йський тебі́ подаю́ща, прийми́ у́бо і от нас земни́х ма́лий віне́ць похвали́ сицеви́я:","Ра́дуйся, трубо́, неві́рним Христа́ Бо́га возвісти́вшая;","ра́дуйся, свире́ле, услажда́ющая сли́шаніє ві́рним.","Ра́дуйся, я́ко му́жеством твої́м небожи́тели возвесели́л єси́;","ра́дуйся, в темни́ці мра́чній святи́м а́нгелом уті́шенний.","Ра́дуйся, пресві́тлий на небесі́х черто́г, я́ко му́ченик, унаслі́довавий;","ра́дуйся, во пло́ті безпло́тния враги́ побіди́вий.","Ра́дуйся, ко́зні їх, а́ки паучи́ну разори́вий;","ра́дуйся, сві́тлий коне́ць побі́ди приє́мий.","Ра́дуйся, вінце́м от Царя́ сла́ви вінча́нний;","ра́дуйся, сугу́бия благода́ті от Него́ сподо́бивийся.","Ра́дуйся, ве́ліє дерзнове́ніє к Нему́ стяжа́вий.","Ра́дуйся, святи́й Дими́тріє, сла́вний великому́чениче і чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дник злоче́стія Максимія́н ра́довашеся, я́ко прекрі́пкий боре́ць єго́ Лий убива́ше Христия́ни. Блаже́нний же Не́стор не терп'я́ того́ безчелові́чія, у тебе́, му́чениче, благослове́ніє іспроси́, і шед низве́рже того́ на ко́пія, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вий в Солу́ні просвіще́ніє і́стини, свя́те, предпосла́л єси́ ко Го́споду Не́стора, чрез посіче́ніє от нечести́вих. Та́же і сам, повелі́нієм царе́вим, ко́піями ізбоде́н бил єси́ за Христа́, пред Ни́мже пом'яни́ і нас, помина́ющих страда́нія твоя́ і вопію́щих ті:","Ра́дуйся, на Ли́єво низложе́ніє Не́стора моли́твами твої́ми укріпи́вий;","ра́дуйся, я́ко по умерщвле́нії Лі́я, смерть му́ченичеськую ку́пно с Не́стором прия́л єси́.","Ра́дуйся, я́ко за Прободе́ннаго на Кресті́ нас ра́ди ко́піями ізбоде́н бил єси́;","ра́дуйся, со сла́вою на небеса́ по сме́рті от а́нгел провожде́нний.","Ра́дуйся, в немерца́ющем сві́те душе́ю пребива́яй;","ра́дуйся, с му́ченики і со всі́ми святи́ми ликовству́яй.","Ра́дуйся, покро́ве пісносло́в'ящих тя;","ра́дуйся, моли́твенниче о чту́щих святу́ю па́м'ять твою́.","Ра́дуйся, святи́й Дими́тріє, сла́вний великому́чениче і чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́ блаже́нний Лупп благослове́ніє от тебе́, страстоте́рпче Христо́в, получи́ти, взя по кончи́ні твоє́й пе́рстень твой і ри́зу, кро́вію твоє́ю омоче́нную, і мно́га чудеса́ і ісціле́нія ті́ми сотвори́в, усі́чен бисть во главу́, да поє́ть ку́пно с тобо́ю і Не́стором в Тро́йці сла́вимому Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вий храм созида́я тебі́, досточу́дне, ісцеле́нний тобо́ю Лео́нтій, обрі́те в землі́ святи́я мо́щі твоя́, істоча́ющая ми́ро, єго́же благоуха́нія іспо́лнися весь град і мно́жество боля́щих ісцілі́. Ті́мже уврачу́й і облагоуха́й і нас, вопію́щих ті си́це:","Ра́дуйся, благоуха́ніє доброді́телей от ю́ности возлюби́вий;","ра́дуйся, нрав а́нгельський от младе́нчества стяжа́вий.","Ра́дуйся, сосу́де благода́ті; ра́дуйся, хра́мі непоро́чности і чистоти́.","Ра́дуйся, я́ко Госпо́дь оби́тель в тебі́ сотвори́ со Отце́м і Ду́хом;","ра́дуйся, я́ко Той просла́ви мо́щі твоя́ нетлі́нієм благода́ті.","Ра́дуйся, благово́нноє Ми́ро от тіх істоча́яй;","ра́дуйся, освяще́ніє і цільби́ ті́ми подава́яй.","Ра́дуйся, я́ко па́че на́рда і сми́рни благоуха́єши;","ра́дуйся, я́ко благоуха́нієм твої́м злово́ніє страсте́й отгоня́єши.","Ра́дуйся, зе́млю і оде́жди твоя́ кро́вію твоє́ю освяти́вий;","ра́дуйся, я́звами свої́ми на́ша я́зви душе́вния і тіле́сния врачу́яй.","Ра́дуйся, святи́й Дими́тріє, сла́вний великому́чениче і чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нноє і ди́вноє чу́до сотвори́л єси́, пречу́дне, возвраща́вшемуся во своя́ сі храмозда́телю твоєму́, приї́м бо той плащани́цю от святи́х твої́х моще́й, волну́ющуюся і многово́дную реку́ немо́кренно пре́йде. Ті́мже прославля́ємому в тебі́ Бо́гу се́рдцем і усти́ воспіва́ше: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь горя́ любо́вію і усе́рдієм к тебі́ Лео́нтій втори́й в честь твою́, свя́те, созда́ храм во Іллирі́ї, оте́честві своє́м, і та́мо, я́коже і в Солу́ні, мно́жество боля́щих і стра́ждущих от дух нечи́стих, моли́твами твої́ми ісцеля́шеся, і і́на мно́га соверша́хуся чудеса́. І́мже ми, див'я́шеся тебі́, вопіє́м:","Ра́дуйся, любо́вію прославля́ющим тя крі́пкий засту́пниче;","ра́дуйся, созида́ющим во і́м'я твоє́ хра́ми чу́дний покро́ве.","Ра́дуйся, здра́вія пода́телю;","ра́дуйся, неду́гов врачева́телю.","Ра́дуйся, то́ки кро́ві уставля́яй;","ра́дуйся, єпа́рха Мари́на от стру́пов і гно́я свободи́вий.","Ра́дуйся, оде́ждою твоє́ю, я́коже Па́вел убру́сцями, чудоді́йствуяй;","ра́дуйся, іме́вшему ю Лео́нтію немо́кренний на ріці́ путь показа́вий.","Ра́дуйся, я́ко повину́ються тебі́ бистрини́ рі́чния;","ра́дуйся, я́ко ду́си зло́би бі́гають от призива́ющих і́м'я твоє́.","Ра́дуйся, я́ко предста́тельством твої́м і ми упова́єм от наві́тов вра́жиїх сохрани́тися;","ра́дуйся, я́ко заступле́нієм твої́м і ми ві́руєм от пото́па іни́х бід ізба́витися.","Ра́дуйся, святи́й Дими́тріє, сла́вний великому́чениче і чудотво́рче."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє удиви́ся, Дими́тріє святи́й, вели́каго твоєго́ дерзнове́нія ді́лу. Хотя́щу бо Го́споду враго́м преда́ти Солу́нь, і явле́нієм а́нгельським, повелі́вшу ті оста́вити град, не оста́вил єси́ того́, сла́вне. Ті́мже сподо́бивийся ужа́снаго виді́нія і сли́шанія, Іллю́стрій с тре́петом возглаша́ше: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́нния не возмо́гуть разумі́ти, как пліне́нния іногда́ ді́ви, о́браз твой, свя́те, пліни́вшему їх кня́зю шве́нієм угото́вавшия, внеза́пу восхище́ні би́ша тобо́ю, і у гро́ба твоєго́ поста́влени, бді́нію на па́м'ять твою́ соверша́ющуся, благослов'я́ще у́бо о тебі́ Го́спода, со умиле́нієм зове́м ті:","Ра́дуйся, за і́стину на землі́, да́же до кро́ві пострада́вий;","ра́дуйся, на небесі́ со дерзнове́нієм престо́лу Бо́жию предстоя́й.","Ра́дуйся, благопотре́бная отту́ду ві́рним посила́яй;","ра́дуйся, от бід призива́ющия тя свобожда́яй.","Ра́дуйся, я́ко во озлобле́нії су́щим ско́ро помога́єши;","ра́дуйся, я́ко Госпо́дь моли́твам твої́м благоутро́бно вне́млеть.","Ра́дуйся, чуде́с неісчерпа́ємий кла́дезю;","ра́дуйся, зна́меній неоскудіва́ємий істо́чниче.","Ра́дуйся, пліне́нних свободи́телю;","ра́дуйся, ва́рварськия де́рзости укроти́телю.","Ра́дуйся, печа́льним утіше́ніє посила́яй;","ра́дуйся, скорб'я́щим ра́дость подава́яй.","Ра́дуйся, святи́й Дими́тріє, сла́вний великому́чениче і чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ град твой от гла́да, явля́лся єси́, Дими́тріє, во приста́нищіх морськи́х і ото́ціх, повеліва́я іму́щим пшени́цю пли́ти с то́ю в Солу́нь. Ті́мже тобо́ю от сме́рти ізба́вленнії, благода́рственні поя́ху о тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ яви́лся єси́ гра́ду твоєму́ несокруши́мая, богому́дре, і необори́мий защи́тник всім призива́ющим тя, зане́ та́ко благоволи́ о тебі́ небесе́ і землі́ Творе́ць. Ті́мже і нас научи́ приглаша́ти тебі́:","Ра́дуйся, милосе́рдія вели́кий люби́телю;","ра́дуйся, о бі́дствующих сострада́тельний попечи́телю.","Ра́дуйся, от гла́да ві́рния спаса́яй;","ра́дуйся, от наше́ствія язи́ков тіх ізима́яй.","Ра́дуйся, мно́жицею ізба́вивий солу́нян от уз рабо́ти го́ркия;","ра́дуйся, губи́тельную я́зву і і́ний вред от них удали́вий.","Ра́дуйся, воєво́до, ники́мже в му́жестві одоли́мий;","ра́дуйся, ратобо́рче, ніколи́же в си́лі оскудева́ющий.","Ра́дуйся, вся на град твой устремля́ющіяся, я́ко Моїсей Амали́ка, низлага́яй;","ра́дуйся, я́ко Сампсо́н, іноплеме́нники прогоня́яй.","Ра́дуйся, царе́м ві́рним на враги́ одолі́ніє подава́яй;","ра́дуйся, христолюби́вим во́їном на бра́ні помога́яй.","Ра́дуйся, святи́й Дими́тріє, сла́вний великому́чениче і чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє вся́коє побіжда́ється, прехва́льне, пред сія́нієм сла́ви твоєя́ і вели́чієм чуде́с. Єгда́ бо Іустинія́н цар, возжелі́ імі́ти в Софи́йстем хра́мі часть моще́й твої́х, огнь ізи́де от гро́ба твоєго́ на посла́нниі от него́, возбраня́юще прикаса́тися ра́ці твоє́й. Ті́мже удивле́ннії со стра́хом возопи́ша Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рную звізду́, су́щим во тьмі неразу́мія, зрим тя, свя́те. Служа́щу бо у гро́ба твоєго́ Ониси́фору тьмо́ю святота́тства держи́му, двукра́тним явле́нієм твої́м возбрани́л єму́ похища́ти свіщи́, возжига́ємия ві́рними у моще́й твої́х. Сего́ ра́ди со благогові́нієм зове́м ті:","Ра́дуйся, пре́жде му́ченичеськия кончи́ни свя́то пожи́вий;","ра́дуйся, по кончи́ні чудеси́ просла́вивийся.","Ра́дуйся, я́ко жив во гра́ді мощми́ твої́ми почива́єши;","ра́дуйся, я́ко присноживи́й чудеса́ ті́ми содіва́єши.","Ра́дуйся, я́ко пра́вду ми́лостію растворя́єши;","ра́дуйся, я́ко огне́м ре́вности по сла́ві Бо́жієй гори́ши.","Ра́дуйся, святи́я мо́щі твоя́ неприкоснове́нни імі́яй;","ра́дуйся, каса́тися їм дерза́ющия, я́ко мо́лнія опаля́яй.","Ра́дуйся, согріша́ющих вразуми́телю;","ра́дуйся, святота́тцев наказа́телю.","Ра́дуйся, освяще́ніє подава́яй благогове́ющим к тебі́ усе́рдно;","ра́дуйся, ми́ром облагоуха́яй чту́щих тя ві́рно.","Ра́дуйся, святи́й Дими́тріє, сла́вний великому́чениче і чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть прия́л єси́, Дими́тріє, ціли́ти всяк неду́г і вся́ку я́зю в лю́діх. Пода́ждь у́бо і на́шим душа́м і тілесе́м ісціле́ніє, да Бо́гу, дарова́вшему нам тебе́, помо́щника і врачева́теля, благода́рственні воспої́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоя́ чудеса́, ублажа́єм тя, досточу́дне, пред нечести́вими Христа́ Бо́га дерзнове́нно іспові́давша, прославля́єм му́ченичеськую кончи́ну твою́, почита́єм па́м'ять твою́, і сицева́я ра́достная тебі́ прино́сим:","Ра́дуйся, стопа́м Христа́ Спаси́теля всіх ре́вностний послі́дователю;","ра́дуйся, страсте́м єго́ му́жественний подража́телю.","Ра́дуйся, с небе́сними си́лами прославля́яй Бо́га;","ра́дуйся, с Цари́цею небесе́ і землі́ моля́йся о ми́рі.","Ра́дуйся, многоціле́бнаго ми́ра сподобля́яй ві́рних;","ра́дуйся, разсла́бленния ті́лом і ду́хом ісціля́яй.","Ра́дуйся, святи́й Дими́тріє, сла́вний великому́чениче і чудотво́рче."]},{"h":"Кондак 13","ps":["О, святи́й великому́чениче і ві́рний уго́дниче Христо́в, Дими́тріє мироточи́ве, ма́лоє сіє́ пісносло́віє от нас приє́мше, моли́ Христа́ Бо́га на́шего, да вселя́ється і благоуха́єть в сердця́х на́ших святи́ня правосла́вной ві́ри, да умножа́ється в житії́ на́шем єле́й благи́х діл, да не уга́снуть світи́льники на́ші в полу́нощний час срі́тенія Небе́снаго Жениха́, і да сподо́бимся вмі́сті с тобо́ю воспіва́ти Єму́ во ві́чном Ца́рствії: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і Госпо́дь Сил яви́ тя, досточу́дне, а́нгела во пло́ті, му́ченика тве́рда і си́льнаго предста́теля ві́рних. Прибіга́юще у́бо к заступле́нію твоєму́, сицева́я ра́достная тебі́ прино́сим:","Ра́дуйся, звіздо́ блиста́ющая на тве́рди церко́вній;","ра́дуйся, світи́льниче, чудеси́ мир озаря́яй.","Ра́дуйся ві́ри непоколеби́мий сто́лпе;","ра́дуйся, христия́н несокруши́мий щі́те.","Ра́дуйся, Фесса́лії сві́тлоє украше́ніє;","ра́дуйся, Солу́ня похвало́ пресла́вная.","Ра́дуйся, апо́столов сограждани́не;","ра́дуйся, му́чеников совсе́льниче.","Ра́дуйся, моля́щихся к тебі́ проше́нія приє́мляй;","ра́дуйся, о всіх нас Бо́гу моля́йся.","Ра́дуйся, святи́й Дими́тріє, сла́вний великому́чениче і чудотво́рче."]},{"h":"Кондак 1","ps":["Ди́вний воєво́до гра́да Солу́ня, вели́кий уго́дниче Христо́в і сла́вний страстоте́рпче, святи́й Дими́тріє, істоча́яй ми́рові ми́лости ми́ро, похва́льная воспису́єм ті, чту́щії святу́ю па́м'ять твою́. Ти же імі́яй дерзнове́ніє ко Го́споду, от вся́ких бід ізбавля́й нас, ві́рно зову́щих ті:","Ра́дуйся, святи́й Дими́тріє, сла́вний великому́чениче і чудотво́рче."]},{"h":"Молитва","ps":["Святи́й і сла́вний великому́чениче Христо́в Дими́тріє, ско́рий помо́щниче і те́плий засту́пниче с ві́рою притека́ющих к тебі́! Предстоя́ с дерзнове́нієм Небе́сному Царю́, іспроси́ у Него́ проще́ніє согріше́ній на́ших і о є́же ізба́витися нам от всегуби́тельния я́зви, тру́са, пото́па, огня́, меча́ і ві́чния ка́зні. Моли́ бла́гость Єго́, є́же уще́дрити град сей, оби́тель сію́ і вся́кую страну́ христия́нськую. Ісхода́тайствуй у Царя́ Ца́рствующих на враги́ побі́ду і одолі́ніє правосла́вним христия́нам, всей держа́ві правосла́вной мир, тишину́, тве́рдость во ві́рі і преспі́яніє во благоче́стії; нам же, чту́щим честну́ю па́м'ять твою́, іспроси́ благода́тноє укріпле́ніє на діла́ блага́я, да благоутро́бноє Влади́ці на́шему Христу́ Бо́гу зді творя́ще, сподо́бимся моли́твами твої́ми наслі́довати Ца́рствіє Небе́сноє для ві́чнаго прославле́нія Єго́ со Отце́м і Святи́м Ду́хом. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Вели́ка обрі́те в біда́х / тя побо́рника вселе́нная, страстоте́рпче, / язи́ки побіжда́юща. / Я́коже у́бо Ли́єву низложи́л єси́ горди́ню, / і на по́двиг дерзнове́нна сотвори́в Не́стора, / та́ко, свя́те Дими́тріє, / Христу́ Бо́гу моли́ся // дарова́ти нам ве́лію ми́лость."]},{"h":"Кондак, глас 2","ps":["Крове́й твої́х струя́ми, Дими́тріє, / Це́рков Бог обагри́, / да́вий тебі́ крі́пость непобіди́мую, / і соблюда́я град твой невреди́м: // того́ бо єси́ утвержде́ніє."]},{"h":"Величання","ps":["Велича́єм тя, страстоте́рпче святи́й Дими́тріє, і чтим честна́я страда́нія твоя́, я́же за Христа́ претерпі́л єси́."]}],"notes":[]},{"u":"Акафіст святителю Іуліану Кеноманійському","e":"Akathist to St Julian of Le Mans","secs":[{"ps":["§Святителя Іуліана благають про покровительство дітям і при тяжких хворобах немовлят."]},{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Бо́жий і чудотво́рче, пресві́тлий землі́ Кеноманійськия світи́льниче, святи́телю о́тче Іулія́не, велича́я просла́вльшаго тя Го́спода, похва́льноє пі́ніє прино́сим ті. Ти же, предстоя́ пред Престо́лом Всеви́шняго, моли́ся ізба́витися нам от вся́кия біди́, ско́рби і печа́лі, со умиле́нієм зовущим:","Ра́дуйся, святи́телю Іулія́не, те́плий о нас моли́твенниче і пресла́вний чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгела земна́го і челові́ка небе́снаго ві́ми тя, свя́те Іулія́не, о́браз і́стиннаго благоче́стія собо́ю нам яви́вшаго. Ми же, Про́мислу Бо́жию, на тебі́ явле́нному, чудя́щеся, прославля́єм ве́ліє благоутро́біє Бо́жиє і с любо́вію зове́м ті:","Ра́дуйся, Ду́хом Святи́м просвіще́нний.","Ра́дуйся, святи́м Креще́нієм духо́вно обновленний.","Ра́дуйся, Це́ркві Правосла́вния украше́ніє.","Ра́дуйся, Галлії свято́є сокро́вище.","Ра́дуйся, Єва́нгелія Христо́ва усе́рдний послі́дователю.","Ра́дуйся, за́повідей Госпо́дніх ві́рний блюсти́телю.","Ра́дуйся, А́нгелов преди́вноє чу́до.","Ра́дуйся, челові́ков пресла́вноє удивле́ніє.","Ра́дуйся, святи́телю Іулія́не, те́плий о нас моли́твенниче і пресла́вний чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дя Сердцеві́дець Госпо́дь благо́є душі́ твоєя́ проізволе́ніє, є́же рабо́тати Єму́ усе́рдно во вся дні живота́ твоєго́, чрез первоверхо́внаго Апо́стола Петра́ во єпи́скопа тя поста́ви і на про́повідь сло́ва Бо́жия в Галлію стопи́ твоя́ напра́ви, да научи́ши люде́й землі́ тоя́ пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Богопросвіще́н імі́я, святи́телю Іулія́не, неуста́нно пропові́дал єси́ уче́ніє Христо́во лю́дем гра́да Кеноманійськаго; они́ же, зря́ще чудеса́, тобо́ю всеси́льним і́менем Христо́вим соверша́ємая, і́стиннаго Бо́га в се́рдця своя́ прийма́ху і святи́м Креще́нієм просвіща́хуся, вопію́ще ті:","Ра́дуйся, Бо́жия ра́зума іспо́лненний.","Ра́дуйся, Христа́ в се́рдці своє́м ви́ну імі́вий.","Ра́дуйся, враго́во ви́димих і неви́димих прогони́телю.","Ра́дуйся, неду́гов душе́вних і тіле́сних ціли́телю.","Ра́дуйся, о́чі сліпи́м отверза́яй.","Ра́дуйся, на путь і́стини наставля́яй.","Ра́дуйся, ни́щих і сиро́т пита́телю.","Ра́дуйся, млади́х му́дрий воспита́телю.","Ра́дуйся, святи́телю Іулія́не, те́плий о нас моли́твенниче і пресла́вний чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго укрепленний і благода́тію Бо́жиєю іспо́лненний, па́ству твою́, Го́сподем тебі́ вві́ренную, уче́нієм Христо́вим, я́ко пи́щею небе́сною, пита́л єси́, прокаже́нния і неду́жния ісціля́я, сліпи́м тіле́сния і духо́вния очеса́ отверза́я, ме́ртвия воскреша́я, бі́си ізгоня́я, і та́ко всім ми́лостивий і лю́б'ящий оте́ць бил єси́, вопію́щим о тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще тя вели́каго моли́твенника і ско́раго в напа́стіх засту́пника, на по́мощ тя призива́єм, святи́телю о́тче Іулія́не, і, помина́я по́двиги і труди́ твоя́, во сла́ву Бо́га Ви́шняго под'ятия, сія́ в похвалу́ тебі́ уми́льно вопіє́м:","Ра́дуйся, єди́наго і́стиннаго Бо́га пропові́дниче.","Ра́дуйся, ісціле́ній благода́тний істо́чниче.","Ра́дуйся, ка́меню ві́ри, на основа́нії за́повідей Госпо́дніх утвержде́нний.","Ра́дуйся, доброді́тельми і світлостьми́ душе́вними украше́нний.","Ра́дуйся, ві́рою твоє́ю і чудеси́ ко Христу́ неві́рния обраща́яй.","Ра́дуйся, си́лою моли́тви твоєя́ стра́ждущим ісціле́нія да́руяй.","Ра́дуйся, і́дольськия пре́лести низложителю.","Ра́дуйся, неі́стовства бісо́вськаго ізобличителю.","Ра́дуйся, святи́телю Іулія́не, те́плий о нас моли́твенниче і пресла́вний чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рею напа́стей одолеваємі, ка́ко возмо́жем досто́йно восхвали́ти чудеса́ твоя́, блаже́нне Іулія́не: ти бо моли́твою своє́ю бі́днаго о́трока от змі́я, обвившаго крі́пко єго́, ізба́вил єси́, і із бесноватих і́менем Христо́вим ду́ха нечи́стаго ізгна́л єси́, і мно́гія умершія воскреси́л єси́. Ті́мже любо́вію те́плою к тебі́ воздвиза́ємі, благодарі́м Го́спода, дарова́вшаго нам такова́го засту́пника і хода́тая о проще́нії гріхо́в на́ших, вопію́щих Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще ди́вная наставле́нія твоя́, я́же не то́чію в словесі́х, но і в по́двизіх твої́х явля́л єси́, достоблаже́нне святи́телю, притека́ху к тебі́ жа́ждущії спасе́нія, і та́ко Це́рков Кеноманійськая укріпля́шеся. Ми же, ви́дя таково́є твоє́ усе́рдноє попече́ніє о спасе́нії душ челові́чеських, восхваля́єм тя:","Ра́дуйся, моли́твенниче ско́рий і те́плий.","Ра́дуйся, предста́телю благи́й і ві́рний.","Ра́дуйся, Апо́столов сла́во і украше́ніє.","Ра́дуйся, святи́телей Христо́вих красото́ і удобре́ніє.","Ра́дуйся, к со́нму святи́х сопричтенний.","Ра́дуйся, вінце́м нетлі́нним Го́сподем увінча́нний.","Ра́дуйся, за ста́до Христо́во ду́шу свою́ положи́вий.","Ра́дуйся, любві́ Христо́ви о́браз в себі́ яви́вий.","Ра́дуйся, святи́телю Іулія́не, те́плий о нас моли́твенниче і пресла́вний чудотво́рче."]},{"h":"Кондак 5","ps":["Боготе́чною звіздо́ю бил єси́ в житії́ твоє́м, Іулія́не всехва́льне, указу́я всім путь в Ца́рствіє Небе́сноє, єго́же і сам стяжа́л єси́, день і нощ Го́сподеві пла́менною любо́вію рабо́тающе і ви́ну Єму́ вопію́ще: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще, я́ко лю́діє, к тебі́ приходя́щії, жа́ждею тіле́сною томими бива́ють: мі́сто бо, іді́же житіє́ твоє́ проводи́л єси́, безво́дно бя́ше, но́воє чу́до сотвори́л єси́, святи́телю ми́лостивий, і, водрузи́в жезл свой в зе́млю, дерзнове́нно Бо́гу помоли́лся єси́: і повелі́ Госпо́дь на мі́сті том істо́чнику води́ откри́тися, в не́мже і крести́л єси́ всіх уві́ровавших во Всемогу́щаго Бо́га, возопивших тебі́ такова́я:","Ра́дуйся, со дерзнове́нієм Бо́гу моли́вийся.","Ра́дуйся, ско́раго услишанія моли́тви твоєя́ удосто́ївийся.","Ра́дуйся, істо́чник води́ приходящим к тебі́ дарова́вий.","Ра́дуйся, чу́дом сим во ві́рі їх укріпи́вий.","Ра́дуйся, вода́ми Креще́нія мно́гія просвіти́вий.","Ра́дуйся, от поги́белі ві́чния сих ізба́вивий.","Ра́дуйся, я́ко ві́рния па́че во ві́рі укріпи́л єси́.","Ра́дуйся, я́ко неві́рния к ві́рі в Бо́га і́стиннаго обрати́л єси́.","Ра́дуйся, святи́телю Іулія́не, те́плий о нас моли́твенниче і пресла́вний чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дник сло́вом і ді́лом і́стини Христо́ви яви́лся єси́, свя́те Іулія́не, єгда́ пригласи́ тя князь Дефенсор, честь тебі́ воздаю́ще; но́воє бо чу́до сотвори́л єси́: сліпцю́, у врат до́ма князева сидящему, крестним зна́менієм о́чі єго́ осіни́в, і́менем Христо́вим зрі́ніє єму́ дарова́л єси́. Всі же, ви́дящії чу́до сіє́, возра́довашася зіло́ і воспі́ша Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, я́ко світи́ло світоза́рноє, просвіща́ющеє сві́том і́стинним во тьмі неві́рія су́щих, да позна́ють і́стиннаго Бо́га, Єго́же си́лою і благода́тію ди́вная ісціле́нія і чудотворе́нія соверша́л єси́, святи́телю Іулія́не. Прийми́ же от нас похвали́ сицеви́я:","Ра́дуйся, моли́тви ко Го́споду кади́ло благово́нноє.","Ра́дуйся, Це́ркві Правосла́вния украше́ніє многоці́нноє.","Ра́дуйся, себі́ самаго́ в храм Ду́ха Свята́го угото́вавий.","Ра́дуйся, мно́гія на путь спасе́нія наста́вивий.","Ра́дуйся, дар ісціле́нія от Го́спода прия́вий.","Ра́дуйся, неду́жния і́менем Христо́вим ісцелявий.","Ра́дуйся, житіє́м благочести́вим примі́р ві́рним би́вий.","Ра́дуйся, ду́шу твою́ в цілому́дрії сохрани́вий.","Ра́дуйся, святи́телю Іулія́не, те́плий о нас моли́твенниче і пресла́вний чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́ще спасе́ніє получи́ти князь Дефенсор смире́нно проси́ тя, о́тче Іулія́не, научи́ти єго́ ка́ко подоба́єть житіє́ своє́ проводи́ти, да жизнь ві́чную унаследуєть. Ти же, кня́зя і дома́шніх єго́ апо́стольською про́повідію о Богі і́стинном просвіти́в, ко Креще́нію приуготовал єси́, да ви́ну восхваля́ють Бо́га пі́снію: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго ви́дим тя ізбра́нника Бо́жия, Іулія́не пресла́вне, устроївшаго благолі́пний храм в до́мі князевом, в не́мже лю́діє, во ві́рі тобо́ю наставляємії, Креще́нієм святи́м просвіща́л єси́ і чудеси́ мно́гими утвержда́л єси́. Ті́мже і нас во ві́рі Правосла́вній укріпи́, восхваля́ющих тя:","Ра́дуйся, богому́дрий пропові́дниче Єва́нгелія Христо́ва.","Ра́дуйся, Це́ркве Правосла́вния пресві́тлий світи́льниче.","Ра́дуйся, побо́рниче ві́ри непобіди́мий.","Ра́дуйся, святи́телю Христо́в пресла́вний.","Ра́дуйся, крі́пкая наде́ждо к тебі́ прибіга́ющих.","Ра́дуйся, уті́шителю всіх на милосе́рдіє твоє́ упова́ющих.","Ра́дуйся, благода́тію Бо́жиєю приосіне́нний.","Ра́дуйся, сві́том Пресвяти́я Тро́йці озаре́нний.","Ра́дуйся, святи́телю Іулія́не, те́плий о нас моли́твенниче і пресла́вний чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до ви́діша от тебе́ лю́діє гра́да Кеноманійськаго, єгда́ ідолопоклонника Анаста́сія си́на уме́ршаго воскреси́л єси́: сей бо Анаста́сій клятвенно уві́ри тя, а́ще си́на своєго́ жива́ воспри́йметь, уверуєть во Христа́ Бо́га і́стиннаго і, бого́в і́дольських отре́кшись, воспоє́ть Тому́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь ра́дости боже́ственния іспо́лнен бисть Анаста́сій, ви́дя уме́ршаго си́на своєго́ жива́, і єди́ними усти́ с при́сними свої́ми просла́ви і́стиннаго Бо́га, і, уверовав во Христа́, крести́ся с дома́шніми свої́ми. Ми же, Бо́га в се́рдці своє́м сла́в'яще, со умиле́нієм глаго́лем ті:","Ра́дуйся, воскреше́нієм уме́ршаго о́трока Го́спода просла́вивий.","Ра́дуйся, пред неві́рними і́дольськоє нече́стіє обличи́вий.","Ра́дуйся, все упова́ніє своє́ на Го́спода полага́вий.","Ра́дуйся, наслі́діє Ца́рствія Христо́ва стяжа́вий.","Ра́дуйся, в до́му Отця́ Небе́снаго оби́тель себі́ сотвори́вий.","Ра́дуйся, в ра́дость Го́спода своєго́ вше́дий.","Ра́дуйся, Подвигополо́жника Христа́ смире́нний послі́дователю.","Ра́дуйся, Апо́столов Христо́вих ре́вностний подража́телю.","Ра́дуйся, святи́телю Іулія́не, те́плий о нас моли́твенниче і пресла́вний чудотво́рче."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ удиви́ся, богоблаже́нне Іулія́не, вели́кому сви́ше тебі́ дарова́нію, ти бо на землі́, я́ко А́нгел пожи́л єси́, і во пло́ті, а́ки безпло́тен яви́лся єси́, ті́мже і дар чудотворе́нія от Го́спода прия́л єси́. Ни́ні же, к ли́ку святи́х сопричтенний, а́нгельськи воспіва́єши піснь: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я многовіща́нния недоумі́ють досто́йно восхвали́ти тя, святи́телю Іулія́не, благода́тію бо Бо́жиєю істоча́єши мно́гая і пресла́вная чудеса́, ї́хже і ісчести́ ність возмо́жно. Пребива́яй ни́ні во сла́ві Христо́вой, при́зри на нас, тебі́ моля́щихся і с любо́вію зову́щих:","Ра́дуйся, я́ко Святі́й Тро́йці ра́достно предстої́ши.","Ра́дуйся, я́ко о спасе́нії на́шем Бо́га умоля́єши.","Ра́дуйся, житія́ непоро́чнаго рачи́телю.","Ра́дуйся, послуша́нія і терпі́нія учи́телю.","Ра́дуйся, пра́ведности і благи́х діл іспо́лненний.","Ра́дуйся, дерзнове́ніє моли́твенноє ко Го́споду стяжа́вий.","Ра́дуйся, кро́тости і смире́нія о́бразе.","Ра́дуйся, оби́димих і стра́ждущих утіше́ніє.","Ра́дуйся, святи́телю Іулія́не, те́плий о нас моли́твенниче і пресла́вний чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ся хотя́ще ві́рнії от разли́чних напа́стей, бід і скорбе́й, тебі́, преблаже́нне Іулія́не, я́ко ві́рнаго наста́вника і побо́рника почита́ють. І нам, грі́шним, спасе́нія іщущим, святи́ми твої́ми моли́твами помози́, вопію́щим о тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ заступле́нія, чудотво́рче святи́й Іулія́не, всім с ві́рою к тебі́ притекающим, тебі́ бо даде́ся от Бо́га благода́ть неду́гующия врачева́ти, бедствующим помога́ти, ско́рбния утіша́ти, найпа́че же младе́нці от вся́каго зла сохраня́ти і болі́зні ісціля́ти. Сего́ ра́ди, Го́спода прославля́я, зове́м ті си́це:","Ра́дуйся, пред Царе́м Небе́сним о нас хода́таю.","Ра́дуйся, за вся христия́ни ми́лостивий предста́телю.","Ра́дуйся, о всіх чту́щих па́м'ять твою́ моли́твенниче.","Ра́дуйся, іщущим спасе́нія благи́й споспі́шниче.","Ра́дуйся, благода́ті Бо́жия сосу́де драгоці́нний.","Ра́дуйся, сві́том Святи́я Тро́йці озаре́нний.","Ра́дуйся, неду́гов на́ших ціли́телю милосе́рдний.","Ра́дуйся, в борбі́ со страстьми́ помо́щниче неодоли́мий.","Ра́дуйся, святи́телю Іулія́не, те́плий о нас моли́твенниче і пресла́вний чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прино́сим ті, святи́телю о́тче Іулія́не, на нас с небесе́ с благосе́рдієм взира́ющему, і всім усе́рдно тебі́ призива́ющим по́мощ ско́рую низпосилающему. Ми же, твоє́ блаже́нноє житіє́ на землі́ і ди́вноє прославле́ніє на небесі́ помина́юще, с любо́вію поє́м благоді́ющему тобо́ю Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тлостію но́ваго чудесе́ твоєго́, богоблаже́нне Іулія́не, всю страну́ Кеноманійськую просвіти́л єси́, ві́рния же во і́стині укріпи́л єси́: боже́ственною бо си́лою вооруженний, в і́дольськоє ка́пище вшел єси́ і призва́л єси́ і́м'я Христо́во, повеліва́я і́долу пасти́, бі́су же із него́ ізи́ти – і бисть та́ко. Лю́діє же, тобо́ю от лю́таго змі́я бісо́вськаго спасе́ннії, взива́ху тебі́:","Ра́дуйся, в броню́ боже́ственную облече́нний.","Ра́дуйся, Господом сви́ше укрепленний.","Ра́дуйся, і́дола нога́ма свої́ма попра́вий.","Ра́дуйся, бі́са із него́ вла́стію Христо́вою ізгна́вий.","Ра́дуйся, от змі́я о́гненнаго нас спаса́яй.","Ра́дуйся, крестним зна́менієм главу́ змі́єву сокруша́яй.","Ра́дуйся, от і́дольськаго суєві́рія отвраща́яй.","Ра́дуйся, ві́рою Христо́вою всіх просвіща́яй.","Ра́дуйся, святи́телю Іулія́не, те́плий о нас моли́твенниче і пресла́вний чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ті Боже́ственния іспо́лнена душа́ твоя́, преблаже́нне Іулія́не, я́ко со́лнце сія́ющая, вознесе́на бисть пресві́тлими А́нгели во оби́телі небе́сния. Ми же ві́дяще, я́ко ти по блаже́нній кончи́ні твоє́й чудоді́йствовати не преста́л єси́, неви́димо колесни́цею с почившим ті́лом твої́м управля́я, со умиле́нієм вопіє́м Бо́гу, просла́вльшему тя во святи́х Свої́х: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще просла́вльшаго тя Го́спода і ублажа́юще тя, святи́телю Христо́в Іулія́не, прилі́жно моли́мтися: сподо́би і нас хода́тайством твої́м неосужде́нно предста́ти Стра́шному Суди́щу Христо́ву, да с ра́достію і любо́вію благохва́льно зове́м ті си́це:","Ра́дуйся, благода́тію Бо́жиєю просла́вленний.","Ра́дуйся, в ли́ці святи́х возвеличенний.","Ра́дуйся, досто́йний А́нгелов собесі́дниче.","Ра́дуйся, всемо́щний наш засту́пниче.","Ра́дуйся, наш пред Бо́гом предста́телю.","Ра́дуйся, чад ма́лих покрови́телю і пита́телю.","Ра́дуйся, і по кончи́ні своє́й чудотворящий.","Ра́дуйся, душі́ на́ша благода́тію врачу́ющий.","Ра́дуйся, святи́телю Іулія́не, те́плий о нас моли́твенниче і пресла́вний чудотво́рче."]},{"h":"Кондак 13","ps":["О преди́вний Іулія́не, засту́пниче наш премилосе́рдий! Прийми́ ма́лоє сіє́ моле́ніє на́ше, с любо́вію тебі́ приноси́моє, і моли́ся за ни ко Го́споду, да сохрани́ть нас і защи́тить Своє́ю благода́тію от вся́ких бід, скорбе́й і напа́стей, і в час кончи́ни на́шея не оста́вить нас, і сподо́бит Ца́рствіє Небе́сноє наслі́довати, да во ві́ки воспіва́єм Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела земна́го і челові́ка небе́снаго ві́ми тя, свя́те Іулія́не, о́браз і́стиннаго благоче́стія собо́ю нам яви́вшаго. Ми же, Про́мислу Бо́жию, на тебі́ явле́нному, чудя́щеся, прославля́єм ве́ліє благоутро́біє Бо́жиє і с любо́вію зове́м ті:","Ра́дуйся, Ду́хом Святи́м просвіще́нний.","Ра́дуйся, святи́м Креще́нієм духо́вно обновленний.","Ра́дуйся, Це́ркві Правосла́вния украше́ніє.","Ра́дуйся, Галлії свято́є сокро́вище.","Ра́дуйся, Єва́нгелія Христо́ва усе́рдний послі́дователю.","Ра́дуйся, за́повідей Госпо́дніх ві́рний блюсти́телю.","Ра́дуйся, А́нгелов преди́вноє чу́до.","Ра́дуйся, челові́ков пресла́вноє удивле́ніє.","Ра́дуйся, святи́телю Іулія́не, те́плий о нас моли́твенниче і пресла́вний чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Бо́жий і чудотво́рче, пресві́тлий землі́ Кеноманійськия світи́льниче, святи́телю о́тче Іулія́не, велича́я просла́вльшаго тя Го́спода, похва́льноє пі́ніє прино́сим ті. Ти же, предстоя́ пред Престо́лом Всеви́шняго, моли́ся ізба́витися нам от вся́кия біди́, ско́рби і печа́лі, со умиле́нієм зовущим:","Ра́дуйся, святи́телю Іулія́не, те́плий о нас моли́твенниче і пресла́вний чудотво́рче."]},{"h":"Молитва","ps":["О пречестна́я і свяще́нная главо́, благода́ті Свята́го Ду́ха іспо́лненная, Спа́сово со Отце́м обита́лище, пресла́вний архієре́є, те́плий наш засту́пниче, святи́телю Іулія́не! Предстоя́ у Престо́ла всіх Царя́, і наслажда́яся сві́та єдиносу́щния Тро́йці і херуви́мськи со А́нгели возглаша́я піснь Трисвяту́ю, вели́коє же і неізслі́дованноє дерзнове́ніє імі́я ко Всемилостивому́ Влади́ці, моли́ спасти́ся па́стви Христо́ви лю́дем, благостоя́ніє святи́х Церкве́й утверди́, архієре́ї благолі́пієм святи́тельства украси́, мона́шествующия к по́двигом до́браго тече́нія укріпи́, вся гра́ди і страни́ до́брі сохрани́, і ві́ру святу́ю непоро́чну соблюсти́ умоли́, мир весь предста́тельством твої́м умири́, от гла́да і па́губи ізба́ви ни, і от нападе́нія іноплеме́нних сохрани́, ста́рия уті́ши, ю́ния наста́ви, нему́дрия умудри́, вдови́ці поми́луй, сироти́ заступи́, младе́нці возрасти́, пліне́нния возврати́, немощству́ющия і моля́щіяся тебі́ от всіх напа́стей і бід хода́тайством твої́м свободи́. Моли́ о нас Всеще́драго і Человіколюби́ваго Христа́ Бо́га на́шего, да в день Стра́шнаго прише́ствія Своєго́ от шу́їяго стоя́нія ізба́вить нас, і ра́дости ві́чния прича́стники сотвори́ть со всі́ми святи́ми во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Пра́вило ві́ри і о́браз кро́тости, воздержа́нія учи́теля яви́ тя ста́ду твоєму́, Я́же веще́й І́стина; сего́ ра́ди стяжа́л єси́ смире́нієм висо́кая, нището́ю бога́тая, о́тче Іулія́не, моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Боже́ственний гром, труба́ духо́вная, ві́ри насади́телю і отсіка́телю єресе́й, Тро́йці уго́дниче, вели́кий святи́телю Іулія́не, со А́нгели предстоя́ при́сно, моли́ непреста́нно о всіх нас."]},{"h":"Величання","ps":["Велича́єм тя, святи́телю о́тче Іулія́не, і чтим святу́ю па́м'ять твою́: ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святителю Спиридону Трімифунтському","e":"Akathist to St Spyridon of Trimythous","secs":[{"h":"Кондак 1","ps":["Препросла́вленний от Го́спода святи́телю і чудотво́рче Спиридо́не! Ни́ні всечестну́ю па́м'ять твою́ пра́зднующе, я́ко мно́го могу́щему споспешествова́ти нам о просла́вльшем тя Христе́, уми́льно вопіє́м ті: ізба́ви нас от вся́ких бід і зол, да с благодаре́нієм зове́м ті:","Ра́дуйся, Спиридо́не, преди́вний чудотво́рче."]},{"h":"Ікос 1","ps":["От ю́ности украше́нний всі́ми доброді́тельми, житіє́м свої́м А́нгелом подража́вий, ти, святи́телю Спиридо́не, воі́стину показа́лся єси́ друг Христо́в; ми же, зря́ще тя, небе́снаго челові́ка і земна́го А́нгела, со благогові́нієм уми́льно вопіє́м ті:","Ра́дуйся, у́ме, созерца́яй та́йни Пресвяти́я Тро́йці;","ра́дуйся, обогати́вийся Ду́ха пресві́тлим осія́нієм.","Ра́дуйся, світи́льниче многосві́тлий;","ра́дуйся, ум твой безстра́стієм просвіти́вий.","Ра́дуйся, ізмла́да і́стинную простоту́ і безмо́лвіє возлюби́вий;","ра́дуйся, украше́ніє цілому́дрія.","Ра́дуйся, любве́ неістощи́мая струя́;","ра́дуйся, я́ко страннолю́бію Авраа́ма подража́л єси́.","Ра́дуйся, я́ко всім любвеоби́льно вхо́ди до́ма своєго́ отверза́л єси́;","ра́дуйся, ни́щих предста́телю.","Ра́дуйся, пред ни́мже благогові́ють лю́діє;","ра́дуйся, я́ко ти єси́ обита́лище Пресвята́го Ду́ха.","Ра́дуйся, Спиридо́не, преди́вний чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дяще о́стров Кипр і вся христия́нськия стра́ни нетлі́нния мо́щі твоя́, святи́телю, от ни́хже істека́ють оби́льная ісціле́нія, возра́довашася; і ми, почита́юще тя я́ко преоби́льнаго істо́чника благода́ті, низпо́сланнаго сви́ше нам, вопіє́м к Верхо́вному Пода́телю Небе́сних і земни́х благ: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Боже́ственний іми́й, а́ще сий па́стир безслове́сних ове́ць, ти проізволе́нієм Пастиренача́льника Христа́ ізбра́н бил єси́ в па́стиря ове́ць слове́сних. Ві́рнії же, разумі́вше тя до́браго па́стиря, неуси́пно о ста́ді своє́м пеку́щагося, воспіва́ху:","Ра́дуйся, архієре́є Бо́га Ви́шняго, в хирото́нії восприя́вий оби́льно Боже́ственную благода́ть;","ра́дуйся, світи́льниче многосві́тлий, горя́й і світя́й.","Ра́дуйся, ві́рний ді́лателю во вертогра́ді Христо́вом;","ра́дуйся, па́стирю, на па́жити ві́ри і благоче́стія па́ству свою́ воспита́вий.","Ра́дуйся, сія́ньми доброді́телей твої́х мир просвеща́вий;","ра́дуйся, Престо́лу Христо́ву Боже́ственную Же́ртву приноси́вий.","Ра́дуйся, ієра́рше, разумі́нієм Правосла́вія украше́нний;","ра́дуйся, апо́стольськаго уче́нія іспо́лненний, ві́рних струя́ми спаси́тельнаго уче́нія напая́яй.","Ра́дуйся, я́ко і му́дрих озари́л єси́;","ра́дуйся, я́ко і прости́х сердца́ обнови́л єси́.","Ра́дуйся, сла́во правосла́вних і Це́ркве непоколеби́моє утвержде́ніє;","ра́дуйся, украше́ніє отце́в, сла́во і похвало́ ієре́єв благогові́йних.","Ра́дуйся, Спиридо́не, преди́вний чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго, осени́вшею тя, святи́телю Спиридо́не, богому́др ти показа́лся єси́ і, сжа́вши дла́нію гли́ну, тро́їчность Лиць всім очеви́дно уясни́л єси́; ті́мже лжему́дрії фило́софи, собра́вшіїся на Собо́рі, ужасо́шася, ві́рнії же непостижи́маго просла́виша Бо́га, умудри́вшаго тя во спасе́ніє, вопію́ще Єму́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́юще тя в помишле́ніїх свої́х всі отці́ Собо́ра про́ста, неіску́сна в кни́жнім уче́нії, моли́ша тя, о́тче Спиридо́не, не препира́тися словеси́ с виті́єю, мня́щимся му́дру би́ти. Ти же, святи́телю, ре́вностію по Бо́зі распаля́ємий, ві́руя, я́ко про́повідь Христо́ва не в препрі́тельних му́дрости челові́чеськія словесі́х, но в явле́нії ду́ха і си́ли, прему́дре того́ обличи́в, вразуми́л і на путь і́стинний наста́вил єси́. Всі, ви́дівше чу́до сіє́, взива́ху:","Ра́дуйся, сві́те правосла́вния му́дрости;","ра́дуйся, я́ко глаго́лемих би́ти му́дрих совопро́сников посрами́л єси́.","Ра́дуйся, істо́чниче, благода́тію оби́льний;","ра́дуйся, непоколеби́мий сто́лпе, тве́рдо содержа́щий су́щих во ві́рі.","Ра́дуйся, омрача́яй всепа́губную є́ресь;","ра́дуйся, чрез него́же попра́но бисть безу́міє.","Ра́дуйся, я́ко персть земна́я пропові́да твої́ма рука́ма Святу́ю Тро́йцю;","ра́дуйся, я́ко із гли́ни ізве́л єси́ огнь і во́ду во утвержде́ніє догма́та Святи́я Тро́йці.","Ра́дуйся, я́ко просвіти́л єси́ лю́ди сла́вити Сло́во, воі́стину Єдиносу́щноє Пребезнача́льному Отцю́;","ра́дуйся, я́ко змі́єву главу́ па́губния а́рієви є́ресі порази́л єси́.","Ра́дуйся, я́ко тобо́ю поже́рта бисть зло́ба;","ра́дуйся, неві́рнаго мудреця́ совопро́сника к і́стинній ві́рі обрати́вий.","Ра́дуйся, Спиридо́не, преди́вний чудотво́рче."]},{"h":"Кондак 4","ps":["Жизнь проводя́ в убо́жестві і нищеті́, ни́щим і бі́дним бил єси́ пита́тель і помо́щник і, любве́ ра́ди к ни́щим, змі́я в зла́то преложи́л єси́ і дал єси́ о́ноє тре́бующему твоєя́ по́мощі. Див'я́щеся о чудеси́ сем, благода́рственно вопіє́м к Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шано бисть всім і всю́ду, я́ко святи́тель Спиридо́н воі́стину єсть жили́ще Святи́я Тро́йці: всели́ся бо в нем Бог Оте́ць, Бог Сло́во і Бог Дух Святи́й. Сего́ ра́ди ти словеси́ і дія́ньми пропові́дал єси́ всім христия́ном воплоще́ннаго і́стиннаго Бо́га, вопію́щим:","Ра́дуйся, слове́с Бо́жиїх таї́нниче;","ра́дуйся, домострої́тельство Бо́жиє о спасе́нії ми́ра уясни́вий.","Ра́дуйся, я́ко научи́л єси́ не іспи́товати є́же єсть преви́ше ра́зума і му́дрости челові́чеськія;","ра́дуйся, непостижи́мую ді́йствующую в тебі́ си́лу Бо́жию яви́вий.","Ра́дуйся, я́ко уста́ми твої́ми провіща́ Сам Бог;","ра́дуйся, я́ко всі послу́шаху тебі́ в сла́дость.","Ра́дуйся, мглу ідолослуже́нія разгна́вий;","ра́дуйся, я́ко мно́гих к і́стинній ві́рі приве́л єси́.","Ра́дуйся, я́ко глави́ неви́димих змі́єв порази́л єси́;","ра́дуйся, я́ко тобо́ю прославля́ється ві́ра христия́нськая.","Ра́дуйся, я́ко сві́тло озаря́єши всіх ублажа́ющих тя;","ра́дуйся, побо́рниче христия́нськия ві́ри і Правосла́вія.","Ра́дуйся, Спиридо́не, преди́вний чудотво́рче."]},{"h":"Кондак 5","ps":["Боже́ственнаго Ду́ха преіспо́лнен бил єси́, святи́телю Спиридо́не, ра́ди доброді́тельнаго житія́ твоєго́; зане́ кро́ток, ми́лостив, чист се́рдцем, терпіли́в, непам'ятозло́бив, страннолю́бець бил єси́: сего́ ра́ди Творе́ць і в чудесі́х пресла́вна показа́ тя. Ми же, прославля́я Бо́га, просла́вльшаго тя, вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Равноа́нгельна Спиридо́на зрим, вели́каго чудотво́рця. Ні́когда страна́ от бездо́ждія і за́сухи вельми́ пострада́: бисть глад і я́зва, і мно́гоє мно́жество люде́й умро́ша, моли́твами же святи́теля сни́де с небесе́ на зе́млю дождь; лю́діє же, ізба́вльшеся от бі́дствія, благода́рственно взива́ху:","Ра́дуйся, вели́кому проро́ку Ілії́ уподо́бивийся;","ра́дуйся, я́ко дождь, от'є́млющий глад і неду́ги, благовре́менні низве́л єси́.","Ра́дуйся, па́ки моли́твами свої́ми не́бо заключи́вий;","ра́дуйся, я́ко немилосе́рдаго купця́ лише́нієм імі́нія наказа́л єси́.","Ра́дуйся, я́ко тре́бующим пи́щу оби́льно дарова́л єси́;","ра́дуйся, я́ко любоблагоутро́біє Бо́га к лю́дем подвиза́єши.","Ра́дуйся, взе́мляй не́мощі немощни́х;","ра́дуйся, богоблагода́тний челові́ком помо́щниче.","Ра́дуйся, боля́щим здра́віє подава́яй;","ра́дуйся, єго́же трепе́щуть де́мони.","Ра́дуйся, безчи́сленних чуде́с істо́чниче.","Ра́дуйся, Спиридо́не, преди́вний чудотво́рче."]},{"h":"Кондак 6","ps":["Заві́са ветхозаве́тной ски́нії закрива́ше во Свята́я Святи́х ковче́г, ма́нну і скрижа́ли. І храм твой, святи́телю Спиридо́не, імі́єть ра́ку твою́, я́ко ковче́г, святи́я мо́щі твоя́, я́ко ма́нну, се́рдце твоє́, я́ко скрижа́ли Боже́ственния благода́ті, на ни́хже зрим начерта́нную піснь: Аллилу́я."]},{"h":"Ікос 6","ps":["Наро́д Кі́пра ні́когда за умноже́ніє беззако́ній наказа́ Госпо́дь безпло́дієм землі́, єгда́ же при́йде к свято́му Спиридо́ну зна́ємий земледі́лець, прося́ по́мощі, даде́ єму́ святи́й зла́то; мину́вшу же бі́дствію, земледі́лець о́ний возврати́ па́ки зла́то. І — о чудесе́! — зла́то змій бисть. Прославля́юще Бо́га, ди́внаго во святи́х Свої́х, вопіє́м:","Ра́дуйся, я́ко Моїсе́ю, чуде́сно преложи́вшему жезл в змі́я, подража́л єси́;","ра́дуйся, человіколюби́вий па́стирю, ізбавля́яй от бід слове́сния о́вці ста́да своєго́.","Ра́дуйся, оби́льно всіх всі́ми бла́гами обогаща́яй;","ра́дуйся, я́ко Ілия́, бі́дних пита́вий.","Ра́дуйся, немилосе́рдих к милосе́рдію обраща́яй;","ра́дуйся, достоподража́ємий примі́р любве́ для челові́ков, в ми́рі живу́щих.","Ра́дуйся, ві́рних і неві́рних в біда́х утіше́ніє;","ра́дуйся, дре́во сенноли́ственноє, град і страну́ осіня́ющеє.","Ра́дуйся, сла́во і похвало́ керки́рян;","ра́дуйся, над вла́гою і су́шею, зно́єм і хла́дом благода́тію Бо́жиєю влади́чествуяй.","Ра́дуйся, уста́ви землі́ моли́твою пременя́яй;","ра́дуйся, бу́дущая, я́ко настоя́щая, прови́дівий.","Ра́дуйся, Спиридо́не, преди́вний чудотво́рче."]},{"h":"Кондак 7","ps":["Хода́тай пред Го́сподем за всіх яви́лся єси́, святи́телю Спиридо́не: сего́ ра́ди і ми прибіга́єм под кров твой, і́щуще спасе́нія, всі бо помо́щника тебі́ і́мами во всіх ну́ждах, во вре́м'я гла́да, смертоно́сния я́зви і во вся годи́ни бід і іскуше́ній. Сего́ ра́ди благода́рственно вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє чу́до ви́дим і боголі́пноє: єгда́ ти, о́тче, ше́ствовал ізба́вити непови́нно осужде́ннаго на смерть, бу́рний пото́к прегради́ путь тебі́; ти же і́менем Всемогу́щаго Бо́га повелі́л єму́ ста́ти і преше́л єси́ со спу́тники чрез реку́, я́ко по су́ху. Сла́ва о сем чудеси́ распространи́ся всю́ду, і всі просла́виша Бо́га, вопію́ще к тебі́:","Ра́дуйся, я́ко іногда́ Ісу́с Нави́н чрез Іорда́н реку́ по су́ху преше́дий;","ра́дуйся, рі́чная устремле́нія гла́сом свої́м укроти́вий.","Ра́дуйся, я́ко тру́дний путь предприя́л єси́, дви́жимий милосе́рдієм;","ра́дуйся, я́ко клевету́ разруши́л єси́ і непови́ннаго от уз темни́ці і напра́сния сме́рті ізба́вил єси́.","Ра́дуйся, жи́зні по Бо́зі благи́й поспі́шниче;","ра́дуйся, непови́нно угнете́нних защи́тителю.","Ра́дуйся, уста́вов єстества́ во́днаго премени́телю;","ра́дуйся, я́ко судію́ вразуми́л єси́ і от уби́йства спасл єси́.","Ра́дуйся, і́стинноє ісправле́ніє душ;","ра́дуйся, ди́вная си́ло, пото́ки удержава́ющая.","Ра́дуйся, услажда́ющий сердца́ челові́ков, к тебі́ притека́ющих;","ра́дуйся, человіколю́бію Авраа́ма подража́телю.","Ра́дуйся, Спиридо́не, преди́вний чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нник і пришле́ць бил єси́ на землі́, я́коже і про́чії челові́ци. Оба́че із чре́ва ма́тере Всеві́дущий вели́каго уго́дника і чудотво́рця показа́ тя, святи́телю Спиридо́не: бі́си бо ізгоня́єши, вся́кую болі́знь і я́зву ісціля́єши, помишле́нія люде́й зри́ши, ті́мже і ди́вен во святи́х показа́лся єси́. Ми же, возсила́юще моли́тву ко Благода́телю всіх Бо́гу, вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь мир у́жасом мно́гим содрогну́ся, єгда́ усли́ша, я́ко смерть, по гла́су твоєму́, возвраща́єть із гробо́в мертвеци́ своя́, і возопи́:","Ра́дуйся, уме́ршую дщер свою́, да яви́ть вруче́нноє єй сокро́вище, к жи́зні воззва́вий;","ра́дуйся, ско́рбную вдови́цю, на сохране́ніє зла́то вда́вшую, уті́шивий.","Ра́дуйся, уме́ршеє отроча́ із ме́ртвих воскреси́вий;","ра́дуйся, я́ко ма́тер єго́, внеза́пно от ра́дости уме́ршую, оживи́вий.","Ра́дуйся, я́ко уподо́бился єси́ Ілії́, моли́твами си́ну саре́птськия жени́ жизнь возврати́вшему;","ра́дуйся, я́ко і Єлиссе́ю, возбуди́вшему от сме́рти отроча́, подража́л єси́.","Ра́дуйся, па́стирю, преі́скренні лю́б'ящий челові́ки;","ра́дуйся, жені́ блудни́ці, слеза́ми но́зі твої́ оми́вшей, гріхи́ і́менем Бо́га отпусти́вий.","Ра́дуйся, святу́ю ре́вность верхо́внаго апо́стола стяжа́вий;","ра́дуйся, я́ко нераска́янная грі́шниця, по глаго́лу твоєму́, в тя́жких болі́зніх у́мре.","Ра́дуйся, землі́ плодоно́сіє моли́твами твої́ми іспроси́вий;","ра́дуйся, непрело́жноє воскресе́нія челові́ков увіре́ніє.","Ра́дуйся, Спиридо́не, преди́вний чудотво́рче."]},{"h":"Кондак 9","ps":["Ду́ха Боже́ственнаго осія́ньми озаре́н бил єси́, святи́телю Спиридо́не, імі́л бо єси́ ду́ха прему́дрости, я́ко му́дрими словеси́ безу́мних обуї́л єси́ і посреді́ отце́во ві́ру утверди́л єси́; ду́ха ра́зума, я́ко уми́ омраче́нния озари́л єси́; ду́ха стра́ха Бо́жия, я́ко ви́ну ді́ланії богоуго́дними ду́шу очи́стил єси́. Ті́мже, предста́в Престо́лу Ви́шняго, с со́нмом А́нгелов воспіва́єши Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Жезл па́стиря слове́сних ове́ць от Пастиренача́льника Го́спода Ісу́са приє́мий, святи́й Спиридо́н не преміни́ житія́ своєго́: нестяжа́телен, кро́ток, любве́ ра́ди вся терп'я́й, не постиді́ся пещи́ся і о ста́ді безслове́сних ове́ць. Вся сія́ возбужда́ють нас сла́вити Бо́га і взива́ти тебі́:","Ра́дуйся, сла́ву ми́ра сего́ я́ко су́єтную презрі́вий;","ра́дуйся, мзду мно́гу на Небесі́х стяжа́вий.","Ра́дуйся, кра́сная ми́ра сего́ в уме́ти вміни́вий;","ра́дуйся, сосу́де Небе́сних благ.","Ра́дуйся, святі́йшая па́жіте киприо́тов;","ра́дуйся, я́ко тебе́ ра́ди Бог хи́щников ове́ць твої́х неви́димими у́зами связа́.","Ра́дуйся, та́тем оте́чеськоє вразумле́ніє препода́вий;","ра́дуйся, по милосе́рдію твоєму́ за проведе́нную без сна нощ овна́ їм дарова́вий.","Ра́дуйся, непослуша́нієм ко́злища, я́ко би ра́зум іму́щаго, купця́, утаї́вшаго ці́ну єго́, обличи́вий;","ра́дуйся, утаї́вшаго сре́бреники твоя́ к покая́нію приведи́й.","Ра́дуйся, я́ко стра́сті користолю́бія увіща́нієм свої́м ісціли́л єси́ єго́.","Ра́дуйся, Спиридо́не, преди́вний чудотво́рче."]},{"h":"Кондак 10","ps":["Спаса́яй ду́ші па́стви, Бо́гом тебі́ вві́ренния, ти, святи́телю Спиридо́не, проізволе́нієм Бо́жиїм, зван бил єси́ яви́ти сла́ву твою́, па́че же сла́ву І́стиннаго Бо́га, і в іни́я страни́, да всю́ду сла́в'ять І́м'я Бо́жиє, вопію́ще: Аллилу́я."]},{"h":"Ікос 10","ps":["Ско́рий помо́щник і засту́пник во вся́ких ну́ждах і ско́рбіх, святи́й Спиридо́н, по повелі́нію царе́ву, я́коже і про́чії па́стирі, приї́де во град Антіохі́ю, іді́же бі одержи́мий болі́знію цар Константі́й; святи́тель глави́ єго́ косну́ся і сотвори́ здра́ва. Сему́ чудеси́ див'я́щеся, вопіє́м ті:","Ра́дуйся, єго́же в со́нном виді́нії А́нгел, я́ко ціли́теля, яви́ царю́;","ра́дуйся, Боже́ственния ра́ди любве́ тру́дний путь в ста́рости восприя́вий.","Ра́дуйся, царе́ву рабу́, уда́рившему тя в лани́ту, по за́повіді Спаси́теля, другу́ю подста́вивий;","ра́дуйся, сто́лпе смире́нія.","Ра́дуйся, моли́твами свої́ми сле́зно прося́щему царю́ здра́віє дарова́вий;","ра́дуйся, я́ко уничиже́нієм свої́м раба́ вразуми́л єси́ і неми́лостивий нрав єго́ преміни́л єси́.","Ра́дуйся, я́ко благоче́стію і милосе́рдію царя́ научи́л єси́;","ра́дуйся, я́ко, ненави́дяй земна́я сокро́вища, зла́то царя́ отве́ргл єси́.","Ра́дуйся, я́ко ученика́ своєго́ Трифи́ллія от пристра́стія к земни́м бла́гам отврати́л єси́ і сосу́дом благода́ті Бо́жия соді́лал єси́;","ра́дуйся, я́ко прише́дшу тебі́ в Александрі́ю, і́доли падо́ша.","Ра́дуйся, єму́же і бі́си повину́ються;","ра́дуйся, я́ко от ідолослуже́нія мно́гих отврати́л єси́.","Ра́дуйся, Спиридо́не, преди́вний чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє а́нгельськоє бисть, єгда́ во хра́мі приноси́л єси́, святи́телю Спиридо́не, вече́рнія моли́тви Твоя́, і не бі́ша сослужа́щії тебі́. Жи́теліє же гра́да, ди́вноє пі́ніє сли́шавше, внидо́ша в храм і, нікого́же ви́дівше, с Го́рніми си́лами воспіва́ху: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рноє со́лнце ми́рові, собесі́дник А́нгелов бил єси́ на землі́, святи́телю Спиридо́не; преда́в же дух твой в ру́ці Бо́жії, пресели́лся єси́ в Го́рняя селе́нія, моля́ся за мир пред Престо́лом Влади́ки. Ми же, живу́щії на землі́, вопіє́м ті:","Ра́дуйся, я́ко тебі́, єще́ жи́ву су́щу, сослужа́ху А́нгели;","ра́дуйся, псалмопі́ніє Арха́нгелов сли́шавий.","Ра́дуйся, ви́димий о́бразе на́шего преображе́нія;","ра́дуйся, я́ко недоста́вшу єле́ю в хра́мі Бог тебе́ ра́ди с ізби́тком лампа́ди напо́лни тім.","Ра́дуйся, лампа́до Боже́ственнаго сія́нія;","ра́дуйся, сосу́де благода́ті Бо́жієй, оби́льно, подо́бні єле́ю, наполня́ющей ду́шу твою́.","Ра́дуйся, неізсяка́ємий істо́чниче, при́сно істоча́ющий всім то́ки благода́ті;","ра́дуйся, о не́мже ізумля́ються А́нгели.","Ра́дуйся, преслуша́ніє дия́кона в хра́мі наказа́вий;","ра́дуйся, тщесла́вившагося свої́м гла́сом, і гла́са і язи́ка лиши́вий.","Ра́дуйся, я́ко, во вре́м'я зно́я, внеза́пу роса́, снизше́дшая Сви́ше, свяще́нную твою́ главу́ прохлади́;","ра́дуйся, в зна́менії сем бли́зость преставле́нія своєго́ прови́дівий.","Ра́дуйся, Спиридо́не, преди́вний чудотво́рче."]},{"h":"Кондак 12","ps":["Покро́в і прибі́жище би́вий всім к тебі́ притека́ющим ві́рним єще́ в житії́ твоє́м, ти, святи́телю, не оста́вил єси́ нас си́рих і по твоє́м успе́нії; Бог, побіжда́ющий єстества́ чин, сохрани́ святи́я мо́щі твоя́ нетлі́нними во укріпле́ніє правосла́вния ві́ри і благоче́стія, в зна́меніє безсме́ртія, Єго́же прославля́юще, вопіє́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Воспіва́єм тя, святи́телю Бо́жий, я́ко удиви́л єси́ мир чудеси́, істека́ющими от святи́х моще́й твої́х. Всі бо с ві́рою приходя́щії і лобиза́ющії їх получа́ють вся благопотре́бная проси́мая. І ми, да́вшаго тебі́ крі́пость, вінча́вшаго тя вінце́м нетлі́нія і ді́йствующаго тобо́ю Бо́га прославля́юще, вопіє́м ті:","Ра́дуйся, во вре́м'я гла́да корабе́льником яви́вийся і пи́щу доста́вити повелі́вий;","ра́дуйся, сліпи́м, с ві́рою прите́кшим к святи́м моще́м твої́м, зрі́ніє дарова́вий.","Ра́дуйся, от неісці́льния болі́зні о́трока ісціли́вий;","ра́дуйся, бі́са із жени́ ізгна́вий і здра́ву ю сотвори́вий.","Ра́дуйся, возбра́нний воєво́до Керки́ри;","ра́дуйся, я́ко по́лчища злочести́вих ага́рян ізгна́л єси́ і корабли́ їх в пучи́ні потопи́л єси́.","Ра́дуйся, єго́же ви́діша окруже́ннаго со́нмом А́нгелов, в десни́ці меч держа́вша і в тре́петь враго́в приве́дша;","ра́дуйся, созда́ти себі́ храм, во є́же соверша́ти в нем литургі́ю на пре́сном хлі́бе, воєво́ді возбрани́вий.","Ра́дуйся, воєво́ду лати́нськаго лю́тою сме́ртію порази́вий;","ра́дуйся, мо́лнією ізображе́ніє єго́ в до́мі во Вене́ції соже́гший.","Ра́дуйся, отсту́пльства і лжемудрова́нія За́пада посрами́вий;","ра́дуйся, єди́ную правосла́вную ві́ру би́ти і́стинную і спаси́тельную для челові́ков утверди́вий.","Ра́дуйся, Спиридо́не, преди́вний чудотво́рче."]},{"h":"Кондак 13","ps":["О пречу́дний святи́телю Христо́в, о́тче Спиридо́не! Ни́нішнєє на́ше моле́ніє приє́м, ізба́ви нас от всіх бід і напа́стей, укріпи́ на враги́ страну́ на́шу, да́руй нам оставле́ніє прегріше́ній і ізми́ от ві́чния сме́рти всіх вопію́щих о тебі́ к Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["От ю́ности украше́нний всі́ми доброді́тельми, житіє́м свої́м А́нгелом подража́вий, ти, святи́телю Спиридо́не, воі́стину показа́лся єси́ друг Христо́в; ми же, зря́ще тя, небе́снаго челові́ка і земна́го А́нгела, со благогові́нієм уми́льно вопіє́м ті:","Ра́дуйся, у́ме, созерца́яй та́йни Пресвяти́я Тро́йці;","ра́дуйся, обогати́вийся Ду́ха пресві́тлим осія́нієм.","Ра́дуйся, світи́льниче многосві́тлий;","ра́дуйся, ум твой безстра́стієм просвіти́вий.","Ра́дуйся, ізмла́да і́стинную простоту́ і безмо́лвіє возлюби́вий;","ра́дуйся, украше́ніє цілому́дрія.","Ра́дуйся, любве́ неістощи́мая струя́;","ра́дуйся, я́ко страннолю́бію Авраа́ма подража́л єси́.","Ра́дуйся, я́ко всім любвеоби́льно вхо́ди до́ма своєго́ отверза́л єси́;","ра́дуйся, ни́щих предста́телю.","Ра́дуйся, пред ни́мже благогові́ють лю́діє;","ра́дуйся, я́ко ти єси́ обита́лище Пресвята́го Ду́ха.","Ра́дуйся, Спиридо́не, преди́вний чудотво́рче."]},{"h":"Кондак 1","ps":["Препросла́вленний от Го́спода святи́телю і чудотво́рче Спиридо́не! Ни́ні всечестну́ю па́м'ять твою́ пра́зднующе, я́ко мно́го могу́щему споспешествова́ти нам о просла́вльшем тя Христе́, уми́льно вопіє́м ті: ізба́ви нас от вся́ких бід і зол, да с благодаре́нієм зове́м ті:","Ра́дуйся, Спиридо́не, преди́вний чудотво́рче."]},{"h":"Молитва","ps":["О вели́кий і пречу́дний святи́телю Христо́в і чудотво́рче Спиридо́не, Керки́рськая похвало́, всея́ вселе́нния світи́льниче пресві́тлий, те́плий к Бо́гу моли́твенниче і всім к тебі́ прибега́ющим і с ві́рою моля́щимся скоропредста́тельний засту́пниче! Ти ві́ру правосла́вную на Нике́йстім Собо́ре посреді́ отце́в пресла́вно із'ясни́л єси́, трієди́нство Святи́я Тро́йці чуде́сною си́лою показа́л єси́ і єретико́в до конця́ посрами́л єси́. Усли́ши нас, грі́шних, святи́телю Христо́в, моля́щихся тебі́, і си́льним твої́м предста́тельством у Го́спода ізба́ви нас от вся́каго зла́го обстоя́нія: от гла́да, пото́па, огня́ і смертоно́сния я́зви. Ти бо во вре́менній жи́зні своє́й от всіх сих бі́дствій ізбавля́л єси́ люде́й твої́х: от наше́ствія ага́рян і от гла́да страну́ твою́ сохрани́л єси́, царя́ от неісці́льнаго неду́га ізба́вил і мно́гія грі́шники к покая́нію приве́л єси́, ме́ртвих пресла́вно воскреша́л єси́, за свя́тость же житія́ твоєго́ А́нгели, неви́димо в це́ркві пою́щия і сослужа́щия тебі́, імі́л єси́. Си́це у́бо просла́ви тебе́, ві́рнаго Своєго́ раба́, Влади́ка Христо́с, я́ко вся та́йная челові́чеськая дія́нія дарова́ тебі́ разумі́ти і облича́ти непра́ведно живу́щия. Мно́гим, в ску́дости і недоста́точестві живу́щим, ти усе́рдно помога́л єси́, лю́ди убо́гія ізоби́льно во вре́м'я гла́да напита́л єси́ і і́на мно́га зна́менія си́лою в тебі́ живу́щаго Ду́ха Бо́жия сотвори́л єси́. Си́це і нас не оста́ви, святи́телю Христо́в, помина́й нас, чад свої́х, у Престо́ла Вседержи́теля і умоли́ Го́спода, да пода́сть мно́гих на́ших гріхо́в проще́ніє, безбі́дноє і ми́рноє житіє́ да да́руєть нам, кончи́ни же живота́ непости́дния і ми́рния, і блаже́нства ві́чнаго в бу́дущем ві́ці сподо́бит нас, да ви́ну возсила́єм сла́ву і благодаре́ніє Отцю́ і Си́ну і Ду́ху Свято́му, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О всеблаже́нне святи́телю Спиридо́не, вели́кий уго́дниче Христо́в і пресла́вний чудотво́рче! Предстоя́й на Небесі́ Престо́лу Бо́жию с ли́ки А́нгел, при́зри ми́лостивим о́ком на предстоя́щия зді лю́ди і прося́щия си́льния твоєя́ по́мощі. Умоли́ благоутро́біє Человіколю́бця Бо́га, да не осу́дить нас по беззако́ніїм на́шим, но да сотвори́ть с на́ми по ми́лості Своє́й. Іспроси́ нам у Христа́ і Бо́га на́шего ми́рноє і безм'яте́жноє житіє́, здра́віє душе́вноє і тіле́сноє, землі́ благопло́діє і во всем вся́коє ізоби́ліє і благоде́нствіє, і да не во зло обрати́м блага́я, да́руємая нам от ще́драго Бо́га, но во сла́ву Єго́ і в прославле́ніє твоєго́ заступле́нія! Ізба́ви всіх ві́рою несумні́нною к Бо́гу приходя́щих от вся́ких бід душе́вних і тіле́сних, от всіх томле́ній і дия́вольських наві́тов. Бу́ди печа́льним уті́шитель, неду́гующим врач, в напа́стіх помо́щник, наги́м покрови́тель, вдови́цям засту́пник, си́рим защи́тник, младе́нцем пита́тель, ста́рим укріпи́тель, стра́нствующим путево́ждь, пла́вающим ко́рмчий і ісхода́тайствуй всім, крі́пкия по́мощі твоєя́ тре́бующим вся, я́же ко спасе́нію, поле́зная. Я́ко да, твої́ми моли́твами наставля́ємі і соблюда́єми, дости́гнем во ві́чний поко́й і ку́пно с тобо́ю просла́вим Бо́га, в Тро́йці Святі́й сла́вимаго, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О преблаже́нне святи́телю Спиридо́не! Умоли́ благосе́рдіє Человіколю́бця Бо́га, да не осу́дить нас по беззако́нієм на́шим, но да сотвори́ть с на́ми по ми́лості Своє́й. Іспроси́ нам, рабо́м Бо́жиїм (імена́), у Христа́ і Бо́га на́шего ми́рноє і безм'яте́жноє житіє́, здра́віє душе́вноє і тіле́сноє. Ізба́ви нас от вся́ких бід душе́вних і тіле́сних, от всіх томле́ній і дия́вольських наві́тов. Помина́й нас у Престо́ла Вседержи́теля і умоли́ Го́спода, да пода́сть мно́гих на́ших гріхо́в проще́ніє, безбі́дноє і ми́рноє житіє́, да да́руєть нам, кончи́ни же живота́ непости́дния і ми́рния і блаже́нства ві́чнаго в бу́дущем ві́ці сподо́бит нас, да непреста́нно возсила́єм сла́ву і благодаре́ніє Отцю́ і Си́ну і Ду́ху Свято́му, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Собо́ра Пе́рваго показа́лся єси́ побо́рник і чудотво́рець, / Богоно́се Спиридо́не, о́тче наш. / Ті́мже ме́ртву ти во гро́бі возгласи́в, / і змію́ в зла́то претвори́л єси́, / і внегда́ пі́ти тебі́ святи́я моли́тви, / А́нгели, сослужа́щия тебі́, імі́л єси́, свяще́ннійший. / Сла́ва Да́вшему тебі́ крі́пость, / сла́ва Вінча́вшему тя, // сла́ва Ді́йствующему тобо́ю всім ісціле́нія."]},{"h":"Кондак, глас 2","ps":["Любо́вію Христо́вою уязви́вся, свяще́ннійший, / ум впери́в заре́ю ду́ха, / ді́тельним виді́нієм твої́м дія́ніє обрі́л єси́, Богоприя́тне, / же́ртвенник Боже́ственний бив, // прося́ всім Боже́ственнаго сія́нія."]},{"h":"Величання","ps":["Велича́єм тя, святи́телю о́тче Спиридо́не, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святителю Пітириму, єпископу Тамбовському, чудотворцю","e":"Akathist to St Pitirim, Bishop of Tambov, the Wonderworker","secs":[{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і ізря́дний уго́дниче Христо́в, святи́телю о́тче Питири́ме, всім прибегающим к тебі́ ско́рий помо́щниче! Сподо́би нас недосто́йними усти́ воспі́ти тебі́ сія́ похва́льная. Ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, зову́щих:","Ра́дуйся, святи́телю Питири́ме, Тамбовський чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгелом подража́тель і челові́ков наста́вник бил єси́, святи́телю о́тче Питири́ме: от ю́ности бо возлюби́л єси́ Боже́ственноє уче́ніє і, сему́ послі́довав, до́брому житію́ поревнова́л єси́. Сего́ ра́ди тебе́, на Небесі́ і на землі́ просла́вленному, вопіє́м си́це:","Ра́дуйся, от рожде́нія твоєго́ Бо́гом ізбра́нний;","ра́дуйся, на служе́ніє апо́стольськоє призва́нний.","Ра́дуйся, ізбра́ніє твоє́ по́двигом благоче́стія оправда́вий;","ра́дуйся, о́бразом житія́ твоєго́ і нам путь к Небесі́ показа́вий.","Ра́дуйся, от ю́ности і́го Христо́во возлюби́вий;","ра́дуйся, чистоту́ се́рдця твоєго́ до конця́ сохрани́вий.","Ра́дуйся, я́ко, сего́ ра́ди, єще́ сий на землі́, А́нгелом уподо́бился єси́;","ра́дуйся, я́ко, сего́ ра́ди, Го́спода Сла́ви всегда́ зрі́ти сподо́бился єси́.","Ра́дуйся, святи́телю Питири́ме, Тамбовський чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дя Благопромислитель Госпо́дь душі́ твоєя́ добро́ту, напра́ви по́мисл твой ко іска́нію єди́наго на потре́бу. Ти же, сего́ возжелі́в, єще́ із ді́тства нави́кл єси́ непреста́нно взива́ти к Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Боже́ственний іми́й, всю суєту́ привре́менния сла́сти презрі́л єси́, о́тче Питири́ме: ті́мже оста́вив мир і вся я́же в нем, ізмла́да прия́л єси́ о́браз а́нгельський, всего́ себе́ отда́в на служе́ніє Єди́ному Го́споду. Таково́є у́бо ізволе́ніє твоє́ восхваля́юще, глаго́лем ті сицева́я:","Ра́дуйся, я́ко путь пра́вий в Ца́рствіє Небе́сноє обрі́л єси́;","ра́дуйся, я́ко сим путе́м невозвра́тно шел єси́.","Ра́дуйся, я́ко кра́сная ми́ра сего́ ні во что́же вміни́л єси́;","ра́дуйся, я́ко, земна́я отри́нув, Небе́сная возлюби́л єси́.","Ра́дуйся, се́рдце твоє́ при́сно ко Христу́ імі́вий;","ра́дуйся, Тому́ Єди́ному служи́ти вожделі́вий.","Ра́дуйся, ра́зум твой в послуша́ніє ві́ри пліни́вий;","ра́дуйся, в Бо́зі благоче́стно пожи́вий.","Ра́дуйся, святи́телю Питири́ме, Тамбовський чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лою Бо́жиєю укріпля́єм, о́тче Питири́ме, вся послуша́нія монасти́рськая до́брі проходи́л єси́ во В'яземстей оби́телі свята́го Предте́чі, єму́же подража́л єси́ по́двиги твої́ми, всегда́ взива́я к Подвигополо́жнику всіх, Спа́су Христу́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я по́мисл чист, і ду́шу непоро́чну, свяще́нства благода́ть, єще́ млад сий, досто́йно восприя́л єси́, о́тче Питири́ме; ті́мже, во ігу́мена оби́телі ізбра́н бил єси́ і са́ном архімандрі́та почте́н, ре́вностно подвиза́яся о спасе́нії Бо́гом вруче́ннаго тебі́ слове́снаго стада́. Сего́ ра́ди вопіє́м ті си́це:","Ра́дуйся, я́ко вся послуша́нія і́ночеськая нелі́ностно проше́л єси́;","ра́дуйся, я́ко сим на висоту́ доброді́телей возше́л єси́.","Ра́дуйся, красото́ смиренному́дрія і воздержа́нія;","ра́дуйся, о́бразе кро́тости і послуша́нія.","Ра́дуйся, цілому́дрія ревни́телю;","ра́дуйся, ді́вства і чистоти́ храни́телю.","Ра́дуйся, і́ночествующих му́дрий нача́льниче;","ра́дуйся, всіх, благоче́стно жи́ти хотя́щих, до́брий наста́вниче.","Ра́дуйся, святи́телю Питири́ме, Тамбовський чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́ри злосло́вія і людська́го м'яте́жа не убоя́лся єси́, о́тче Питири́ме, єгда́ іко́ну преподо́бнаго Арка́дія, недобре писанную, почита́нія лиши́л єси́. Ті́мже, о правові́рії ревну́я, поуча́л єси́ па́ству твою́ пра́во взива́ти к Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав і ви́дів премно́гую твою́ доброді́тель, блаже́нний Патріа́рх Іоаки́м святи́теля тебі́ нарече́ і па́ству Тамбо́вськую смотре́нію твоєму́ вручи́. Ми же, о сем веселя́щеся, глаго́лем ті сицева́я:","Ра́дуйся, вся степе́ні і́ночеськаго зва́нія с че́стію і сла́вою проше́дий;","ра́дуйся, на престо́лі святи́тельстім досто́йно возсі́дий.","Ра́дуйся, стра́же Це́ркве Христо́ви неустраши́мий;","ра́дуйся, ді́лателю виногра́да Христо́ва неутоми́мий.","Ра́дуйся, благовре́менні і безвре́менні па́ству твою́ поучавий;","ра́дуйся, ко Христу́ о́вці заблу́ждшия призва́вий.","Ра́дуйся, лю́ди, во тьмі сідя́щия, сві́том Христо́вим озари́вий;","ра́дуйся, сим от поги́белі їх сохрани́вий.","Ра́дуйся, святи́телю Питири́ме, Тамбовський чудотво́рче."]},{"h":"Кондак 5","ps":["Боготечноє світи́ло, путь жи́зні твоєя́ озаря́ющеє, бисть тебі́ уго́дник Бо́жий Проко́пій, єго́же і́менем во святі́м Креще́нії нарече́н бил єси́ і к нему́же при́сно с моли́твою прибегал єси́, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діл єси́, о́тче Питири́ме, твої́ма очи́ма уго́дника Бо́жия Проко́пія, предстоя́ща пред лице́м Го́спода і к Нему́ моля́щася си́це: Безсме́ртний Бо́же, хвалу́ Тебі́ воздаю́, Цар бо єди́н єси́ всім; поми́луй ду́шу єго́ і сподо́би сего́ Ца́рствія Небе́снаго. Сего́ ра́ди і ми взива́єм к тебі́: не преста́й моли́тися о всіх нас ку́пно со Прокопієм блаже́нним, да і нас сподо́бит Госпо́дь дости́гнути Небе́снаго Ца́рствія. О сем воздиха́юще, похва́льная воспіва́єм ті:","Ра́дуйся, очеса́ твоя́ всегда́ на не́бо возводи́вий;","ра́дуйся, сла́ву Небе́сную па́че всего́ возлюби́вий.","Ра́дуйся, непреста́нними моли́твами се́рдце твоє́ освяти́вий;","ра́дуйся, мисль твою́ в Бо́зі утверди́вий.","Ра́дуйся, я́ко Проко́пія свята́го, моли́твенника дерзновеннаго всегда́ імі́л єси́;","ра́дуйся, я́ко сему́ споспішеству́ющу, в ра́дость Го́спода твоєго́ вшел єси́.","Ра́дуйся, я́ко в ра́йських оби́теліх ни́ні пребива́єши;","ра́дуйся, я́ко от Го́рних висо́т і нас, многогрі́шних, ми́лостивно назира́єши.","Ра́дуйся, святи́телю Питири́ме, Тамбовський чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дник ві́ри правосла́вния і ревни́тель благоче́стія сло́вом і житіє́м твої́м бил єси́, святи́телю Питири́ме. Ті́мже духо́вная па́ства твоя́ непреста́нно па́м'ятуєть і вся Россі́йськая страна́ досто́йно ни́ні прославля́єть труди́ твоя́, ї́миже труди́лся єси́, при́сно взива́я ко Го́споду: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ во Це́ркві Тамбо́встій сві́том Христо́ва уче́нія і ре́вностію твоє́ю о сла́ві Бо́жієй, святи́телю о́тче Питири́ме: ти бо, красоту́ Госпо́дню возлюби́в, о устроє́нії хра́мов святи́х і о благочи́нії церковнім всеусе́рдно приліжа́л єси́. Сего́ ра́ди воспіва́єм ті си́це:","Ра́дуйся, сла́ви Христо́ви ревни́телю;","ра́дуйся, хра́мов святи́х строї́телю.","Ра́дуйся, благочи́нія церко́внаго стро́гий блюсти́телю;","ра́дуйся, чте́нія і пі́нія Боже́ственнаго іску́сний учи́телю.","Ра́дуйся, я́ко тобо́ю Це́рков Ру́ськая благоукраси́ся;","ра́дуйся, я́ко в ней ві́ра Христо́ва тобо́ю утверди́ся.","Ра́дуйся, гра́да Тамбо́ва сла́во і украше́ніє;","ра́дуйся, всім нам зашито і огражде́ніє.","Ра́дуйся, святи́телю Питири́ме, Тамбовський чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́й невозбра́нно возноси́тися ду́хом в Го́рняя Селе́нія, безмо́лвіє пусти́ні возлюби́л єси́, о́тче Питири́ме, іді́же мно́гі дні в пості́ і моли́тві подвиза́лся єси́, овогда́ же со святи́телем Митрофа́ном, друго́м твої́м, бесі́довал єси́, воспіва́я с ним ку́пно хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую оби́тель в мі́сті пусти́ннім, я́коже ти́хую при́стань, во сла́ву Предте́чі Госпо́дня созда́в і в само́м гра́де Тамбо́ве с сестро́ю твоє́ю Єкатериною оби́тель же́нськую устро́їв, сим яви́л єси́ нам, о́тче Питири́ме, ве́лію твою́ любо́в ко оби́телем святи́м. Сего́ ра́ди воспіва́єм ті похва́льная сія́:","Ра́дуйся, Предте́чу Госпо́дня возлюби́вий і тому́ в житії́ твоє́м поревнова́вий;","ра́дуйся, стро́гий по́двиг благоче́стія в себі́ показа́вий.","Ра́дуйся, пусти́ні безмо́лвія люби́телю;","ра́дуйся, поста́ і моли́тви стро́гий блюсти́телю.","Ра́дуйся, Тамбо́вськия де́бри і ліса́ моли́твою твоє́ю облагоуха́вий;","ра́дуйся, оби́тель і́ноком та́мо основа́вий.","Ра́дуйся, святи́теля Митрофа́на дру́же і собесі́дниче;","ра́дуйся, во Ца́рствії Небе́снім тому́ сонаслі́дниче.","Ра́дуйся, святи́телю Питири́ме, Тамбовський чудотво́рче."]},{"h":"Кондак 8","ps":["Странника і прише́льця в ми́рі сем помишля́л єси́ себе́, о́тче Питири́ме. Ті́мже, Небе́сная возлюби́в, сокро́вище некра́домоє сокро́виществовал єси́, гряду́щаго гра́да взиску́я і ко Го́споду ра́достно взива́я: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь іспо́лнь любве́ Христо́ви, ду́шу твою́ за о́вці твоя́ положи́ти гото́в бил єси́, спасе́ніє всім устроя́я і всім во всем угожда́я, не іски́й своєя́, но мно́гих по́льзи, да вся́ко ні́кия спасе́ши. Сего́ ра́ди чтим святу́ю па́м'ять твою́ і усе́рдно вопіє́м ті:","Ра́дуйся, о́тче благосе́рдий, о спасе́нії мно́гих ревнова́вий;","ра́дуйся, не свої́х си, но бли́жняго іска́вий.","Ра́дуйся, па́стирю до́брий, на па́житіх ту́чних ча́да твоя́ духо́вная пита́вий;","ра́дуйся, стра́же неуси́пний, от волко́в хи́щних о́вці твоя́ охранявий.","Ра́дуйся, ни́щих корми́телю і гла́дних пита́телю;","ра́дуйся, си́рих защи́тниче і оби́димих предста́телю.","Ра́дуйся, я́ко і ни́ні во вся́ких ну́ждах ско́ро нам помога́єши;","ра́дуйся, я́ко і ни́ні всіх, с ві́рою к тебі́ притека́ющих, ми́лостивно утіша́єши.","Ра́дуйся, святи́телю Питири́ме, Тамбовський чудотво́рче."]},{"h":"Кондак 9","ps":["Всяк во́зраст і вся́ко сосло́віє єще́ в житії́ твоє́м велича́ху тя, я́ко челові́ка Бо́жия, і в час кончи́ни твоєя́ вся па́ства твоя́ пла́каше о тебі́, я́ко о отці́ своє́м. Зря́щи же тя погребаєма і но́ваго предста́теля на Небесі́ імі́ти упова́ющи, с рида́нієм, ку́пно же і благода́рним се́рдцем, возглаша́ше о тебі́ надгро́бную піснь: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство челові́чеськоє не довлі́єть ко прославле́нію мно́гих чуде́с твої́х, святи́телю Питири́ме: но́вая бо купі́ль Силоа́мськая откри́ся всім стра́ждущим во істо́чниці твоє́м, рука́ма твої́ма іскопаннем; та́же і ри́за твоя́ честна́я, на неду́жния полага́єма, да́руєть їм ісціле́ніє, і гроб твой святи́й яви́ся воі́стину неоску́дная враче́бниця: нікто́же бо, с ві́рою к нему́ притека́яй, тощ і неуті́шен отхо́дить. Сего́ ра́ди гла́си хвале́бними тя сла́вим:","Ра́дуйся, врачу́ безме́здний, ту́не врачева́нія всім подава́яй;","ра́дуйся, сосу́де драгоці́нний, целебноє ми́ро всім ві́рним бога́тно ізлива́яй.","Ра́дуйся, глухи́х сли́шаніє і сліпи́х прозрі́ніє;","ра́дуйся, хроми́х хожде́ніє і сляче́нних ісправле́ніє.","Ра́дуйся, разсла́бленних укріпи́телю;","ра́дуйся, бесноватих от наси́лія дия́вольськаго свободи́телю.","Ра́дуйся, лише́нним сми́сла ум здра́вий подава́яй;","ра́дуйся, в со́ніїх і виді́ніїх по́мощ твою́ явля́яй.","Ра́дуйся, святи́телю Питири́ме, тамбовський чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ па́ству твою́, о́тче Питири́ме, не суди́л єси́ ві́діти в ней і́но что, то́чію Ісу́са Христа́, і Сего́ ра́сп'ята. Сего́ ра́ди поста́вил єси́ о́браз расп'я́тія Го́спода, зна́меніє на́шего спасе́нія, на враті́х гра́да, да всі мимоходя́щії покланя́ються єму́, воспіва́юще хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ни необори́мия і Засту́пниці ро́да христия́нськаго іко́ну ди́вную гра́ду Тамбо́ву дарова́л єси́, о́тче Питири́ме, от нея́же додне́сь всім с ві́рою приходящим то́ки чуде́с ізлива́ються. Сего́ ра́ди благода́рні взива́єм ті си́це:","Ра́дуйся, все упова́ніє твоє́ на Ма́тер Бо́жию возложи́вий;","ра́дуйся, і град твой покро́ву Тоя́ вручивий.","Ра́дуйся, іко́ну Єя́ святу́ю в щит і огражде́ніє гра́ду поста́вивий;","ра́дуйся, зало́г любве́ твоєя́ іко́ну Богома́тере па́стві оста́вивий.","Ра́дуйся, я́ко іко́ною то́ю чудеса́ мно́га содіва́ються;","ра́дуйся, я́ко ми́лости Бо́жия от нея́ непреста́нно ізлива́ються.","Ра́дуйся, Богоро́дицю нам указа́вий от всіх бід ізбавле́ніє;","ра́дуйся, я́ко ми́лостію Єя́ ти єси́ на́ша ра́дость і утіше́ніє.","Ра́дуйся, святи́телю Питири́ме, Тамбовський чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє немо́лчноє да́же додне́сь соверша́ється у святі́й іко́ни твоє́й, уго́дниче Бо́жий Питири́ме: мно́зі бо, в ну́ждах су́щії, ві́дять тя помо́щника благопоспешлива і моли́твенника благоуві́тлива. Ті́мже ни́ні вся Россі́йськая земля́ благода́рні вопіє́ть просла́вльшему тя Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льник світоза́рен бил єси́ в земні́м житії́ твоє́м, о́тче наш Питири́ме, благода́тно озаря́я душі́ ві́рних. Просвіти́ у́бо моли́твами твої́ми о́чі душе́вния і нам, в пучи́ні гріха́ погиба́ющим, да благода́рні вопіє́м ті:","Ра́дуйся, вели́кий уго́дниче Бо́жий, благочестную жизнь на землі́ возлюби́вий;","ра́дуйся, ві́ру, наде́жду і любо́в да́же до конця́ сохрани́вий.","Ра́дуйся, світи́льниче многосві́тлий, сві́том і́стиннаго Богопозна́нія нас озаря́яй;","ра́дуйся, луче́ Со́лнця Пра́вди, теплото́ю Боже́ственния любве́ душі́ на́ша согреваяй.","Ра́дуйся, би́сере честни́й, сія́нієм Небе́сния Сла́ви се́рдця на́ша увеселя́яй;","ра́дуйся, ка́меню драги́й, страну́ на́шу правосла́вную украша́яй.","Ра́дуйся, я́ко тобо́ю бе́здну милосе́рдія Бо́жия призива́єм;","ра́дуйся, я́ко тобо́ю спасе́ніє ві́чноє получи́ти упова́єм.","Ра́дуйся, святи́телю Питири́ме, Тамбовський чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть от Бо́га ті да́нную ві́дяще, ни́ні прилі́жно мо́лим тя, святи́телю Питири́ме: проле́й те́плую о нас моли́тву ко Го́споду, да сохрани́ть Це́рков Свою́ Святу́ю неврежде́ну от єресе́й і раско́лов і вся правосла́вния да поми́луєть і спасе́ть, вопію́щия Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́ Богоуго́дноє житіє́, о́тче Питири́ме, і на Небесі́ от Бо́га прославле́ніє, велича́єм безчи́сленная чудеса́ і ісціле́нія твоя́, і, на неусипния моли́тви твоя́ упова́юще, взива́єм ті сицева́я:","Ра́дуйся, храм Преображе́нія Госпо́дня благолі́пен устро́ївий;","ра́дуйся, ві́чноє поко́їще себі́ в нем предуготовавий.","Ра́дуйся, житіє́ твоє́ земно́є благоче́стне сконча́вий;","ра́дуйся, от Царя́ Небе́снаго віне́ць сла́ви приє́мий.","Ра́дуйся, апо́столов собесі́дниче;","ра́дуйся, святи́телей сопресто́льниче і сонаслі́дниче.","Ра́дуйся, Арха́нгелов і А́нгелов сослужи́телю;","ра́дуйся, всіх Небе́сних Сил сожи́телю.","Ра́дуйся, святи́телю Питири́ме, Тамбовський чудотво́рче."]},{"h":"Кондак 13","ps":["О пресла́вний чудотво́рче, уго́дниче Бо́жий Питири́ме! Прийми́ сіє́ от любве́ на́шея приноси́моє тебі́ благохвале́ніє і твої́м благоприя́тним хода́тайством ізба́ви нас от вся́ких бід і зол, от внеза́пния сме́рти і бу́дущия муки́, да сподо́бимся ку́пно с тобо́ю во ві́ки пі́ти: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом подража́тель і челові́ков наста́вник бил єси́, святи́телю о́тче Питири́ме: от ю́ности бо возлюби́л єси́ Боже́ственноє уче́ніє і, сему́ послі́довав, до́брому житію́ поревнова́л єси́. Сего́ ра́ди тебе́, на Небесі́ і на землі́ просла́вленному, вопіє́м си́це:","Ра́дуйся, от рожде́нія твоєго́ Бо́гом ізбра́нний;","ра́дуйся, на служе́ніє апо́стольськоє призва́нний.","Ра́дуйся, ізбра́ніє твоє́ по́двигом благоче́стія оправда́вий;","ра́дуйся, о́бразом житія́ твоєго́ і нам путь к Небесі́ показа́вий.","Ра́дуйся, от ю́ности і́го Христо́во возлюби́вий;","ра́дуйся, чистоту́ се́рдця твоєго́ до конця́ сохрани́вий.","Ра́дуйся, я́ко, сего́ ра́ди, єще́ сий на землі́, А́нгелом уподо́бился єси́;","ра́дуйся, я́ко, сего́ ра́ди, Го́спода Сла́ви всегда́ зрі́ти сподо́бился єси́.","Ра́дуйся, святи́телю Питири́ме, Тамбовський чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і ізря́дний уго́дниче Христо́в, святи́телю о́тче Питири́ме, всім прибегающим к тебі́ ско́рий помо́щниче! Сподо́би нас недосто́йними усти́ воспі́ти тебі́ сія́ похва́льная. Ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, зову́щих:","Ра́дуйся, святи́телю Питири́ме, Тамбовський чудотво́рче."]},{"h":"Молитва","ps":["О вели́кий уго́дниче Бо́жий і пресла́вний чудотво́рче, святи́телю Питири́ме! К тебі́ смире́нно припа́даєм і усе́рдно мо́лимся: яви́ нам, грі́шним, любо́в твою́ оте́чеськую і многомо́щноє твоє́ заступле́ніє. Ві́руєм бо, я́ко ве́ліє дерзнове́ніє і́маши ко Го́споду і я́ко мно́го мо́жеть предста́тельство твоє́ пред Престо́лом бла́гости Єго́. Сохрани́ моли́твами твої́ми Це́рков Святу́ю от єресе́й і раско́лов, от суєві́рія і неві́рія. Іспроси́ нам ві́ру пра́ву, наде́жду несомні́нну, любо́в нелицемі́рну, в до́брих ді́ліх преспі́яніє, во іскуше́ніях му́жество, в злострада́ніїх терпі́ніє, в моли́твах постоя́нство, мир і благоустроє́ніє страні́ на́шей, здра́віє же і спасе́ніє лю́дем єя́. При́зри ми́лостивно на предстоящия і моля́щіяся пред свято́ю іко́ною твоє́ю і вся проше́нія їх во бла́го іспо́лни, і всім вся в жи́зні вре́менній і ві́чній потре́бная да́руй, во сла́ву ди́внаго во святи́х Свої́х Бо́га, в Тро́йці сла́вимаго і покланя́ємаго, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Ві́ри і благоче́стія наста́вниче, / Це́ркве світи́льниче, мона́шествующих о́бразе, / святи́телю Питири́ме прему́дре, / ста́до твоє́ благоче́стно упа́сл єси́ / і ко Христу́ приве́л єси́, / ті́мже во Ви́шніх вінце́м сла́ви украше́н, / с на́ми на землі́ ду́хом пребива́єши, сія́я чудеси́. / Моли́ Христа́ Бо́га, // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Мона́хов наста́вника ізря́дна і святи́теля всім лю́дем ми́лостива, / чудотво́рця преди́вна і моли́твенника о нас неуси́пна, // соше́дшеся воспої́м Питири́ма, Тамбо́вськия землі́ похвалу́."]},{"h":"Величання","ps":["Велича́єм тя, святи́телю о́тче Питири́ме, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]}];
export default D;
